window.D=window.D||{};D["mb_19"]={"476":[{"s":"<b>מנהג אכילת צלי בליל פסח. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מקום <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>שנהגו <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>לאכול צלי <i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>בלילי פסחים אוכלים מקום שנהגו <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>שלא לאכול <i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>אין אוכלין גזירה שמא יאמרו פסח הוא <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ובכל מקום אסור לאכול <i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i>שה צלי כלו כא' בלילה זה מפני שנרא' כאוכל קדשים בחוץ <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואם היה מחותך או שחסר ממנו אבר או שלק בו אבר והוא מחובר ה\"ז מותר במקום שנהגו: <small>הגה ולא יאכל ולא ישתה הרבה יותר מדאי <i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i>שלא יאכל האפיקומן על <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אכילה גסה או ישתכר וישן מיד (מהרי\"ל)</small>:","m":["(א) שלא לאכול וכו' - ובאלו ארצות אין נוהגין לאכול צלי בשני הלילות ואפילו צלי קדר [פי' שנצלה בקדירה בלא מים ושום משקה אלא מתבשל במוהל היוצא ממנו] אע\"פ שאינו דומה לצליית הפסח שהפסח שנצלה בקדירה פסול אפ\"ה יש לאוסרו מפני מראית העין שלא יטעו להתיר גם צלי אש ואפילו אם בישלו מתחלה במים ואח\"כ עשאו צלי קדר יש לאסור מטעם זה ומיהו לצורך חולה קצת יש להקל בזה ואם היה צלוי ואח\"כ בשלו מותר לכל:","(ב) שה - בין שה כשבים או שה עזים:","(ג) כולו כאחד כאחד - דהיינו ראשו על כרעיו ועל קרבו כמו בפסח:","(ד) ואם היה מחותך או שחסר וכו' - ר\"ל שצלה אותו כשהוא מחותך או אפילו כשהוא מחובר אלא שנחתך ממנו אבר אחד קודם הצליה ובשעת צליה הניחו אצלו וצלאו ביחד:","(ה) או שלק וכו' והוא מחובר - ר\"ל ואח\"כ צלהו כולו כאחד הואיל ואינו דומה לצליית הפסח הרי זה מותר בכל זה:","(ו) אכילה גסה - דהיינו שאינו מתאוה כלל לאכול שאז אינו עושה מצוה מן המובחר שאף שאפיקומן הוא זכר לפסח והפסח נאכל על השובע דהיינו שהוא שבע כבר ולכן אוכלין האפיקומן אחר גמר הסעודה כמו שיתבאר בסימן תע\"ז מ\"מ צריך שיהא לו קצת תאוה לאכול ואם לאו אין זה מן המובחר ואם שבע כ\"כ עד שנפשו קצה באכילה מרוב שובע אף שדוחק עצמו לאכול אינו יוצא ידי חובתו כלל במצוה זו שאכילה גסה כזו אינה נקראת אכילה כלל. כתבו הפוסקים אל יהיה אכילת אפיקומן עליו לטורח דעי\"ז אין מתקיים המצוה מן המובחר:","(ז) וישן מיד - ותניא בתוספתא חייב אדם לעסוק בהלכות פסח כל הלילה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>אפילו בשר עגל <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>ועוף כל דבר <i data-commentator=\"Chok Yaakov\" data-order=\"5\"></i>שטעון <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>שחיטה אסור לאכול צלי במקום שנהגו שלא לאכול צלי: <small>הגה נוהגים בקצת מקומות לאכול בסעודה <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>ביצים זכר לאבילות ונראה לי הטעם משום <i data-commentator=\"Chok Yaakov\" data-order=\"6\"></i>שליל <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>תשעה באב נקבע בליל פסח ועוד זכר לחורבן <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>שהיו מקריבים קרבן פסח ויש נוהגים שלא לאכול שום טיבול בלילה <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>רק ב' טבולים שעושים בסדר (מהרי\"ל)</small>:","m":["(ח) אפילו בשר עגל ועוף - ר\"ל אף שאין הפסח בא מהם מ\"מ אסור לאכלו צלי לפי שהעולם יטעו בין צלי לצלי ויבואו להתיר גם בשר צלוי מכבשים ועזים:","(ט) שטעון שחיטה - לאפוקי דגים וביצים מותר לאכלם צלוים בכל מקום לפי שאין דומין כלל לבשר ולא יטעו בהם. ואפילו הביצה שמניחים על הקערה מותר ע\"י צלי ולאכלה [ט\"ז]:","(י) במקום שנהגו שלא וכו' - אבל במקום שנהגו לאכול צלי מותר לאכול אפילו עגל שצלוי כולו כאחד דאין הפסח בא ממנו:","(יא) ונ\"ל הטעם וכו' - והגר\"א כתב עוד טעם מפני שהביצה הוא זכר לחגיגה וכמבואר לעיל בסימן תע\"ג ס\"ד וע\"כ צריך לאכלו ג\"כ ומה שאין אוכלין הזרוע לפי שעושין אותו צלי כמ\"ש בסימן תע\"ג ואין אוכלין צלי ויוצאין באפיקומן שאוכלין עכ\"ד ולפ\"ז נראה דיהדר לאכול גם בליל א' אותה ביצה שעל הקערה ושאר ביצים שאוכלין הוא משום שנשתרבב המנהג:","(יב) שליל ת\"ב נקבע וכו' - פי' כמו שחל יום א' של פסח יהיה לעולם באותו יום ת\"ב וכמבואר לעיל בסימן תכ\"ח ע\"ש:","(יג) שהיו מקריבין - ומתאבלין ע\"ז ולפי טעם זה שייך המנהג גם ביום השני [ח\"י] וכן הוא ג\"כ לטעם הגר\"א הנ\"ל ומ\"מ צריך לידע שלכל הטעמים הביצים שאוכלין בתוך הסעודה הוא רק זכר בעלמא ודלא כההמון שחושבים זה למצוה ומחמת זה ממלאים כרסם עד שאוכלין אפיקומן על אכילה גסה ולכן צריך אדם לידע בנפשו [ח\"א]:","(יד) רק ב' טיבולים - ומה שטובלין גם המרור שעל הכריכה בחרוסת אין זה טיבול שלישי דהוא רק משום ספק בלבד [ט\"ז בסימן תע\"ה]:"]}],"477":[{"s":"<b>דיני אכילת האפיקומן. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>לאחר גמר כל הסעודה אוכלים <i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>ממצה השמורה תחת המפה <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>כזית כל אחד זכר לפסח הנאכל על השובע <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ויאכלנו בהסיבה ולא יברך עליו <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ויהא זהיר לאכלו קודם חצות: <small> (ויקדים עצמו שגם ההלל <i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i>יקרא קודם חצות) (ר\"ן פרק ע\"פ וס\"ב דמגילה)</small>:","m":["(א) כזית - ולכתחלה טוב שיקח שני זיתים אחד זכר לפסח ואחד זכר למצה הנאכלת עמו:","(ב) כל אחד - ואף נשים חייבות בזה:","(ג) על השובע - ועיין לעיל בסימן תע\"ו ס\"א בהג\"ה ובמה שכתבנו שם במ\"ב:","(ד) ויאכלנו בהסיבה - ובדיעבד אם שכח ואכלו בלא הסיבה א\"צ לחזור ולאכול אם קשה עליו האכילה:","(ה) ולא יברך עליו - שהוא רק לזכר וכנ\"ל כתב של\"ה ראיתי מבני עליה שהיו מנשקין המצות והמרור וכן הסוכה בכניסתו וביציאתו וכן ארבעה מינים שבלולב והכל לחבוב המצוה ואשרי מי שעובד ה' בשמחה:","(ו) ויהא זהיר וכו' - שכיון שהוא זכר לפסח צריך לאכלו בזמן פסח והפסח אינו נאכל אלא עד חצות וכ\"ש כזית הראשון שמברכין עליו על אכילת מצה שצריך ליזהר מאד שלא לאחרו עד חצות ובדיעבד אם איחר מסתפקים הראשונים אם יצא ידי חובתו וע\"כ יאכלנו ולא יברך עליו על אכילת מצה וגם מרור אף שהוא מדרבנן יזהר לאכלו קודם חצות ואם איחר יאכלנו בלא ברכה ואם החשיך לו קודם אמירת הגדה עד סמוך לחצות יקדש וישתה כוס ראשון ויטול ידיו ויברך המוציא ועל אכילת מצה ויאכל וגם יברך על המרור תיכף קודם חצות ואח\"כ יאמר הגדה ואח\"כ יסעוד סעודתו [אחרונים]:","(ז) שגם ההלל - ר\"ל עם ברכתו שמברך לאחריה יאמר לכתחלה קודם חצות:","(ח) בלא ברכת המוציא - דאף דבסימן קע\"ט י\"א דאם אמר הב לן ונברך הוי היסח הדעת ואם ירצה לאכול צריך לחזור ולברך הכא אתכא דרחמנא סמכינן דאין תלוי בדעתו דהא צריך לקיים רצון ה' ובודאי השכחה גרמה לו שיטול ידיו או לומר הב לן ונברך ולא הסיח דעתו לגמרי:"]},{"s":"אם שכח ולא אכל אפיקומן ולא נזכר עד שנטל ידיו או שאמר הב לן ונברך אוכל אפיקומן <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>בלא ברכ' המוציא ואם לא נזכר עד שבירך ברכת המזון <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אם נזכר קודם שבירך בורא פרי הגפן <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>יטול ידיו ויברך המוציא ויאכל האפיקומן <small> (ויחזיר ויברך ברכת המזון ויברך בפה\"ג וישתה הכוס) (בית יוסף) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ואם לא נזכר עד אחר שבירך בורא פרי הגפן <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>לא יאכל האפיקומן <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>ויסמוך על מצה שאכל <i data-commentator=\"Chok Yaakov\" data-order=\"5\"></i>בתוך הסעוד' שכולן שמורות הן משעת לישה <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אבל <i data-commentator=\"Chok Yaakov\" data-order=\"6\"></i>במקום שנהגו לעשו' <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>שימור למצת מצוה <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>משע' <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>קצירה אפילו לא זכר עד <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>אחר ההלל יטול ידיו ויברך המוציא ויאכל האפיקומן: <small>הגה <i data-commentator=\"Chok Yaakov\" data-order=\"7\"></i>ויחזור ויברך על הכוס <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>ואין לחוש במה <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"4\"></i>שמוסיף על הכוסות (תשובת הרא\"ש כלל כ\"ד) ואם נאבד האפיקומן יאכל כזית אחד ממצה שמורה אחרת (רוקח)</small>:","m":["(ט) יטול ידיו - דכיון שבירך ברכת המזון אסח דעתיה ועיין בפמ\"ג שכתב דיטול בלא ברכה ובפרט היכא שיודע שלא הסיח דעתו שלא יברך:","(י) ויברך בפה\"ג וכו' - וזהו כוס שלישי ולא הצריכו ליה לשתות כוס זה סמוך לברכת המזון הראשון דלא תקנו כוס ג' אלא בגמר אכילתו וזה ששכח לאכול אפיקומן כמי שלא גמר אכילתו דמי [ב\"ח]:","(יא) לא יאכל האפיקומן - דאם יאכל יצטרך לברך ברכת המזון וברכת המזון צריך כוס וא\"כ הוא כמוסיף על הכוסות וכתבו כמה אחרונים דכ\"ז הוא להני פוסקים דס\"ל לעיל סימן קפ\"ד ברכת המזון טעונה כוס אמנם לפי מנהגנו כמ\"ד ברכת המזון בעלמא אינה טעונה כוס גם עכשיו יאכל האפיקומן ויברך בהמ\"ז בלי כוס:","(יב) ויסמוך על מצה וכו' - ר\"ל שזה יהיה נחשב לשם אפיקומן אע\"פ שלא כוון אז לשם זה ואף דקי\"ל בסימן תע\"ט דאחר אפיקומן אין לאכול שום דבר ואיהו הלא אכל אחר המצה עוד דברים אחרים מ\"מ בדיעבד יצא:","(יג) בתוך הסעודה וכו' - הא אם לא היה לו שמורה כלל בתוך הסעודה אף שבתחלת הסעודה אכל הכזית מצה שמורה כדין חוזר ואוכל אפיקומן דלא יצא מצות אפיקומן בזה דהא בעינן שיהא נאכל על השובע [פר\"ח ופמ\"ג]:","(יד) שימור למצת מצוה - ולא אכל מאותה מצה תוך הסעודה שיהיה יכול לסמוך ע\"ז לשם אפיקומן:","(טו) אפילו לא נזכר וכו' - וכ\"ש אם נזכר קודם שהתחיל לומר הלל בודאי אוכל אפיקומן ומברך בהמ\"ז על הכוס ואין כאן משום שתיה בין כוס שלישי לרביעי דאסור כדלקמן בסי' תע\"ט שכיון שהשלישי היה בטעות חוזר הכוס שהוא מברך עתה עליו להיות שלישי:","(טז) עד אחר ההלל - ר\"ל וגם בירך בפה\"ג על כוס רביעי ששותה אחריו:","(יז) ואין לחוש וכו' - שכיון שמתחלה היה הכוס שלישי בטעות נחשב זה הכוס לכוס שלישי ואף שא\"כ הוא שלא כסדרן שהקדים לזה הכוס של הלל שהוא ראוי להיות אחרון אין הסדר מעכב. ודע דלפי מה דנוהגין בכל השנה לברך בהמ\"ז בלא כוס גם בזה יאכל האפיקומן בלא כוס:\n"]}],"478":[{"s":"<b>שלא לאכול אחר אכילת אפיקומן. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אחר אפיקומן <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>אין לאכול שום דבר: <small>הגה ולא יאכלנו <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>בשני מקומות דלא עדיף מאלו הפסיק בשינה דאסור משום דהוי כשני מקומות (טור)</small>:","m":["(א) אין לאכול - כדי שלא יעבור מפיו טעם מצה של אפיקומן שהוא מצוה ע\"י טעם אותו מאכל ובדיעבד אם אכל אחריו שום דבר יחזור ויאכל כזית מצה שמורה לשם אפיקומן:","(ב) שום דבר - ולענין שתיה נחלקו הפוסקים ויש להחמיר במשקה המשכר ולכתחלה נכון ליזהר מכל משקה חוץ ממים וכה\"ג כמו שמבואר לקמן בסימן תפ\"א במ\"ב סק\"א:","(ג) ולא יאכלנו - להאפיקומן אבל שאר הסעודה לית לן בה:","(ד) בשני מקומות - וה\"ה בחדר אחד מקצתו בשולחן זה ומקצתו בשולחן אחר דהוי כשני מקומות והטעם שאפיקומן זכר לפסח ופסח אינו נאכל בשני מקומות לפי שנאמר בבית אחד יאכל:","(ה) דלא עדיף - מביא ראיה שגם במצה מחמירין בשני מקומות כמו בפסח:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>מי שישן בתוך הסעודה והקיץ <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>אינו חוזר לאכול בני חבור' <i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i>שישנו מקצתן בתוך הסעוד' חוזרים ואוכלים נרדמו כולם וננערו לא יאכלו <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>נתנמנמו כולם יאכלו: <small>הגה וכל זה אינו אלא שישנו לאחר שהתחילו לאכול האפיקומן <i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i>אבל שינה <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>קודם לזה <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>לא הוי הפסק (טור ורבינו ירוחם)</small>:","m":["(ו) בתוך הסעודה - עיין בדברי הרמ\"א בהג\"ה:","(ז) אינו חוזר לאכול - דהשינה חשובה הפסק ועשאוהו רבנן כאוכל בשני מקומות:","(ח) חוזרים ואוכלים - דכיון שיתר בני החבורה היו נעורים לא חשב הפסק אפילו לגבי הישינים:","(ט) נתנמנמו - היינו שלא נשקע בשינה כולי האי ואם שואלים אותו היכן הנחת כלי זה וכשמזכירין לו הנחתו במקום פלוני נזכר ואומר הן או לאו זהו קרוי מתנמנם:","(י) אבל שינה קודם לזה - דהיינו בתוך האכילה:","(יא) לא הוי וכו' - ר\"ל דלא חיישינן להפסק זו כיון שאינו בתוך האפיקומן ולענין אם צריך לברך המוציא עוד הפעם משום השינה עיין לעיל בסימן קע\"ח ס\"ז ובמ\"ב שם:"]}],"479":[{"s":"<b>ברכת המזון על כוס שלישי. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אחר כך <i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>מוזגין כוס שלישי ומברך עליו ברכ' המזון ובורא פרי הגפן <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>ושותיהו בהסיבה <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ולא יברך אחריו <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ולא ישתה <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>יין בינו לכוס רביעי: <small>הגה מיהו מכוס שלישי <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i>יכול לשתות <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>כמה פעמים והכל מחשב שתייה אחת אע\"ג דהפסיק בנתיים (מהרי\"ל ומהר\"י ותשב\"ץ) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>מצוה לחזור <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"5\"></i>אחר זימון: <small>הגה <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>והגדול שבהן אומר הודו ואנא והאחרים עונין אחריו (כל בו) . והגדול יכול <i data-commentator=\"Chok Yaakov\" data-order=\"6\"></i>ליתן לקטן רשות (מהרי\"ל) ויכול לצרף לזימון לענין הלל אף על גב שלא אכל עמהם ונהגו <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"7\"></i>שבעל הבית מברך ברכת המזון בליל פסח שנא' טוב עין הוא יבורך והוא מיקרי טוב עין שאמר כל דכפין ייתי ויכול וכו'</small>:","m":["(א) מוזגין לו כוס שלישי - וצריך הדחה ושטיפה אם אינו נקי ואף מי שאינו נזהר בכל השנה לראות אם הוא נקי מ\"מ בזה הלילה יזהר משום הידור מצוה:","(ב) ומברך עליו בהמ\"ז - אפילו אם מברך ביחידי ואפילו למ\"ד בעלמא דבהמ\"ז אינה טעונה כוס מ\"מ הואיל שתקנו חכמים לשתות ארבעה כוסות בלילה זו יש לעשות מצוה בכל כוס וכוס להכי סומכין כוס שלישי לבהמ\"ז [גמרא]:","(ג) ושותהו בהסיבה - ואם שתה בלא הסיבה אם יחזור וישתה עיין לעיל בסימן תע\"ב ס\"ז ובהגה\"ה:","(ד) ולא יברך אחריו - אפילו שתה כל הרביעית דסומך על ברכה אחרונה שמברך על כוס רביעי:","(ה) ולא ישתה יין - שמא ישתכר ויישן ולא יגמור את ההלל ויש שכתבו הטעם מפני שהוא נראה כמוסיף על הכוסות וכתבו האחרונים דלאו דוקא יין ה\"ה שאר משקין המשכרין מיהו אם אינו משכר מותר והוא שלא היה חמר מדינה דאם היה חמר מדינה יש להחמיר ולחוש לטעם השני דנראה כמוסיף על הכוסות:","(ו) מיהו מכוס שלישי וכו' - דלטעמא קמא משום שכרות בודאי לא שייך שהרי אינו שותה יותר מארבעה כוסות. ולטעמא דנראה כמוסיף נמי ליכא שהרי אינו אלא כוס אחת. ומ\"מ אם לאחר ששתה רוב רביעית לא היה בדעתו לשתות יותר ואח\"כ נמלך לשתות עוד דעת מ\"א וח\"י כיון שצריך לברך עליו מחדש מחזי כמוסיף על הכוסות ועיין לעיל בסי' תע\"ב בבה\"ל מה שכתבנו בזה:","(ז) כמה פעמים - ומ\"מ אם הכוס גדול הרבה יותר מדאי לא ישתנו כולו שלא ישתכר [אחרונים]:","(ח) דהפסיק בינתים - ר\"ל לאחר ששתה רוב רביעית בתחלה הפסיק הרבה יותר מכדי אכילת פרס:","(ט) אחר זימון - הסכימו האחרונים דהאי זימון אינו לענין בהמ\"ז דבשביל זה אינו מחוייב להדר יותר מבשאר ימות השנה והכא לענין הלל מיירי שמצוה להדר לומר הלל בשלשה כדי שיהא אחד אומר לשנים הודו והם יענו פסוק שאחר זה ואותו שיקראוהו לזימון זה לא יאכל ולא ישתה ולא יסייע לברך ברכת הזימון אלא ישמע הודו ויענה עמהם ויחזור לביתו וגם בזה הסכימו דאף שמצוה מן המובחר לומר הלל בשלשה גברים גדולים ועל כן אם יש בביתו על שולחן אחד גברא בר חיובא בודאי מהנכון לצרף אותו לאמירת הודו מ\"מ אין קפידא כ\"כ שיכול לצאת בזה באשתו ובניו (ואם בניו הם קטנים עיין לקמיה) דהיינו שהוא יאמר והם יענו [וה\"ה שאשתו יכולה לומר הודו שהרי גם נשים מחויבות בהלל זה כמו שהם מחויבות בד' כוסות וכתב הח\"י דלפי מה שנוהגין לומר הודו בניגון נעימת קול יש לחוש למאי דאמרינן בגמרא זמרן נשי ועניין גברי כאש בנעורת] ואם רוצה לחזור אחר זימון לבהמ\"ז ורוצה לילך לשכנו לברך שם לא יאכל האפיקומן בביתו דהא ע\"כ יהא צריך לאכול שם דבר מה כדי להצטרף לבהמ\"ז ואסור לאכול אחר האפיקומן שום דבר וגם האפיקומן גופא אסור לחלק ולאכול בשני מקומות וכדלעיל בסימן תע\"ח אלא יאכל האפיקומן במקום שמזמן ומברך שם וגם ישתה שם הכוס וישאר שם עד גמר הסדר ואם רוצה יחזור לביתו אחר בהמ\"ז ויגמור ההלל וישתה כוס רביעי אבל מ\"מ לא נהגו עכשיו כן לילך לאכול האפיקומן בבית אחר וכ\"כ טוב יותר לברך בביתו יחידי מלילך באמצע סעודתו לבית אחר ולחפש אחר זימון. אכן אם רוצה להדר ולקיים הכל מן המובחר ואין לו בביתו זימון שלם של ג' אנשים יראה להזמין לכתחלה לסעודה איזה אורח כדי שיהא לו זימון שלם לבהמ\"ז וגם לאמירת הודו:","(י) אומר הודו ואנא וכו' - הוא רק מצוה לכתחלה ואינו לעיכובא [פר\"ח]:","(יא) והאחרים עונין אחריו - ואם אין שם כ\"א שנים שניהם יאמרו הודו [אחרונים]:","(יב) ליתן לקטן רשות - שהוא יאמר כדי שלא יישנו וגם כדי לחנכם במצות. וזהו דוקא באמירת אנא מפני שהם עונין אחריו אותו פסוק גופא אבל לא בהודו:","(יג) שבעל הבית מברך - אף אם יש לו אורח ומ\"מ אין קפידא בזה אם בירך אחר [ח\"י]:"]}],"480":[{"s":"<b>סדר כוס רביעי. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>מתחיל לא לנו <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>וגומר עליו את ההלל ואינו אומר יהללוך אלא אומר אחר גמר ההלל <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>הלל הגדול שהוא מהודו ליי' <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i>עד על נהרות <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>בבל שהם כ\"ו כי לעולם חסדו ואח\"כ אומר <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>נשמת כל חי וישתבח עד <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>מעולם ועד עולם אתה אל <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i>ואז יאמר יהללוך עד מלך מהולל בתשבחות <i data-commentator=\"Chok Yaakov\" data-order=\"5\"></i>ושותהו בהסיבה <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>בלא ברכה תחל' <small> (וכבר נתבאר לעיל סי' תע\"ד דאנו נוהגין לברך) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ומברך אחריו על הגפן ואם שותהו בלא הסיבה <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>צריך לשתות פעם אחרת בהסיבה <small> (וע\"ל סי' תע\"ב סעיף ז') </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>ומברך לפניו בורא פרי הגפן לפי שהסיח דעתו מלשתות עוד: <small>הגה וי\"א שיש לומר שפוך חמתך וכו' קודם לא לנו (ר\"ן פרק ע\"פ) ולפתוח הפתח כדי לזכור שהוא ליל שמורים <i data-commentator=\"Chok Yaakov\" data-order=\"6\"></i>ובזכות אמונה זו יבא משיח וישפוך חמתו על העכו\"ם (מהרי\"ב) וכן נוהגים ויכול לגמור הלל אף שלא במקום סעודה (רמב\"ם והמגיד פ\"ח)</small>:","m":["(א) מתחיל לא לנו - בלא ברכה ואומרים ההלל מיושב אף שבכל השנה אומרים מעומד בפסח שאני מפני שמיושב הוא דרך הסיבה וחירות:","(ב) את ההלל - מי שאירע לו אבל ביו\"ט שלא נהג אבילותו קודם יו\"ט מ\"מ גומר את ההלל:","(ג) עד על נהרות בבל - ואינו אומר רננו צדיקים:","(ד) עד מעולם ועד עולם - ונוסחתנו בישתבח הוא מעתה ועד עולם ובדיעבד אם חתם ישתבח בברכה יאמר אח\"כ יהללוך בלא חתימה:","(ה) ואז יאמר יהללוך - ויש נוהגין כהפוסקים לומר תיכף אחר הלל יהללוך עד כי מעולם ועד עולם אתה אל ואח\"כ אומר הלל הגדול ונשמת וישתבח וחותם בא\"י מלך מהולל בתשבחות (ויש שחותמין הבוחר בשירי זמרה וכו' כמו שאומרים בישתבח תמיד) ולפי מנהג זה אם בשעה שאומר יהללוך שכח וחתם בא\"י מלך מהולל בתשבחות שוב לא יחתום בישתבח אלא יאמר הלל הגדול ונשמת וישתבח עד מעתה ועד עולם:","(ו) ושותהו - והפיוטים דהיינו אז רוב ניסים וכו' אומר אחר שתיית הכוס שאינו אלא מנהג ומהר\"מ היה שותה אחר הפיוטים ואחר כי לו נאה כדי שלא יהיה צמא כשישכב וכ\"ה בסידורים. בלילה א' יאמר אז רוב נסים ובלילה ב' יאמר אומץ גבורותיך ויש נוהגין שאומרים הכל בשני לילות שוין:","(ז) ומברך אחריו וכו' - ובברכה זו יפטור גם הכוס ג' וכדלעיל סימן תע\"ד:","(ח) צריך לשתות פעם וכו' - וה\"ה בכוס ג' ג\"כ דינא הכי להמחבר מיהו לענין ברכה לפניה דוקא בכוס רביעי שלא חשב לשתות עוד כלל משא\"כ בכוס שלישי שבלא\"ה חשב לשתות עוד על סמך ברכה זו לא מיקרי היסח הדעת ואין צריך לברך:","(ט) ועיין לעיל סי' תע\"ב - ר\"ל דהכריע שם בהג\"ה דלדידן שאין דרכנו להסב בכל השנה אין לחזור ולשתות בהסיבה:","(י) כדי לזכור שהוא ל\"ש - ואין מתייראין משום דבר ונוהגין באלו מדינות למזוג כוס אחד יותר מהמסובין וקורין אותו כוס של אליהו הנביא (לרמז שאנו מאמינים שכשם שגאלנו הש\"י ממצרים הוא יגאלנו עוד וישלח לנו את אליהו לבשרנו):","(יא) אף שלא במקום סעודה - ואף שאינו שותה הארבעה כוסות במקום אחד אין בכך כלום:"]}],"481":[{"s":"<b>שלא לשתות אחר ד' כוסות. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אחר ארבע כוסו' <i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>אינו רשאי לשתות יין אלא מים: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>וכל המשקים דינן <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>כיין (בית יוסף) ומי שהוא איסטניס או תאב הרבה לשתות יכול לשתות כוס חמישי ויאמר <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>עליו הלל <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>הגדול (מרדכי)</small>:","m":["(א) אינו רשאי וכו' - הרבה טעמים יש בזה בפוסקים יש שכתבו משום שמצוה לספר ביציאת מצרים ובנפלאותיו של הקב\"ה אפילו כל הלילה כ\"ז שלא חטפתו שינה וכדלקמיה ולהכי לא ישתה שלא ישתכר ויתבטל ממצוה זו ולפי סברא זו דוקא יין או שאר משקה המשכר ויש שכתבו דלא יהא נראה כמוסיף על הכוסות שנראה כמתחיל בסעודה אחרת ולפ\"ז כל חמר מדינה אסור אף שאינו משכר ויש שכתבו משום שלא יתבטל טעם מצה מפיו ע\"י שתייתו וכמו שאסרו לאכול אחר הסדר מטעם זה ולפי טעם זה כל משקה אפילו אינו חמר מדינה ואינו משכר אסור ומסתימת דברי המחבר ורמ\"א משמע שדעתם להחמיר ככל הני טעמי ומ\"מ כתבו האחרונים דאינגבע\"ר וואסע\"ר וה\"ה טייא או עפיל טראנק ויש שכתבו גם לאקרי\"ץ מותר דזה אינו מבטל טעם מצה וכמיא בעלמא הוא [אכן בעפיל טראנק שכותש את התפוחים בבית הבד ויש להם טעם גדול יש אוסרים] והנה אף דלכתחלה נכון להחמיר בכל דבר שמבטל טעם מצה מ\"מ במקום צורך גדול יש לסמוך על סברא הראשונה להתיר לו לשתות שאר משקין שאין משכרין ובפרט בליל שני בודאי יש להקל בשאר משקין שאין משכרין:","(ב) תאב הרבה לשתות - אפילו יין:","(ג) ויאמר עליו הלל הגדול - דוקא אם לא סיים עדיין הברכה ושתה כוס ד' אז יכול לומר הלל הגדול עד סוף ולחתום בברכה ולשתות הכוס ה' אבל אם כבר סיים סוף הברכה אין לחזור ולומר הלל הגדול ולברך לבסוף דלא תקנו כ\"א ברכה אחת:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>חייב אדם לעסוק בהלכות הפסח וביציאת מצרי' ולספר בניסים ובנפלאו' שעשה הקב\"ה לאבותינו <i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>עד שתחטפנו שינה: <small>הגה וכל דין ליל ראשון יש <i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i>ג\"כ בליל <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>שני (אגור) ונוהגים שלא לקרות על מטתו <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i>רק פרשת <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"4\"></i>שמע ולא שאר דברים שקורין בשאר הלילות כדי להגן כי ליל שמורים הוא מן המזיקים</small>:","m":["(ד) שמע - וצריך לברך ברכת המפיל. ואם קרא ק\"ש בבהכ\"נ קודם הלילה צריך לקרות כל הק\"ש כדי לצאת וכנ\"ל בסי' רל\"ה:"]}],"482":[{"s":"<b>דין מי שאין לו מצה שמורה. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מי שאין לו מצה משומרת אלא כזית <i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>מברך <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>על אכיל' <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>מרור ואוכל <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>וכשגומר סעודתו <i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i>ממצ' שאינה משומרת מברך על אכילת מצה ואוכל אותו כזית ואינו טועם אחריו כלום: <small>הגה ומי שאין לו ב' הלילות רק ג' מצות יברך ליל ראשון המוציא ועל אכילת מצה וכן הכריכה <i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i>הכל מן הפרוסה <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"5\"></i>וב' השלימות לליל ב' (אבודרהם בשם אבן ירחי)</small>:","m":["(א) משומרת - עיין לעיל סי' תנ\"ג ס\"ד מהו משומרת ועיין בה\"ל:","(ב) אלא כזית - וא\"כ אם יאכלו בראשונה לא יהיה לו לאפיקומן ואם ירצה לצאת בו גם במקום אפיקומן א\"כ לא יהא רשאי לאכול אחריו וכדלעיל בסימן תע\"ח וע\"כ צריך לעשות כמו שמבאר והולך:","(ג) מברך על אכילת מרור וכו' - ר\"ל לאחר שמברך מתחלה ברכת המוציא לבד על מצה שאינה משומרת מברך על המרור וברכת על אכילת מצה יברך לבסוף בשעה שאוכל כזית המשומרת ואע\"ג דלכתחלה צריך לאכול מצה של חיוב והדר מרור משום שנאמר על מצות ומרורים בתחלה מצה והדר מרורים היכא דלא אפשר שאני והמחבר השמיט דין דכריכה ומשמע דס\"ל דלא מצרכינן ליה כריכה משום דאין לו מצה שמורה רק כזית ובמצה שאינה שמורה לא חשיב כריכה שהרי אינה מצה כלל:","(ד) על אכילת מצה - דברכת המוציא כבר בירך:","(ה) אותו כזית - המשומר ועולה לו גם במקום אפיקומן שהרי אוכלו על השובע:","(ו) ואינו טועם אחריו כלום - וכמו בכל מקום לאחר אפיקומן. והנה כ\"ז בשאין לו רק כזית אחד שמורה אבל אם יש לו שני זיתים אוכל כזית אחד בתחלת אכילתו ומברך עליו המוציא ועל אכילת מצה וכזית אחר יאכלנו אחר גמר סעודתו לשם אפיקומן. וחולה שאינו יכול לאכול רק כזית או מי שאין לו שום מצה רק כזית יאכל תבשילו בלא המוציא ואחר סעודתו יברך המוציא ועל אכילת מצה ויאכל אותו כזית אבל אם אין לו גם כן יין א\"כ צריך לקדש על המצה תחלה ואח\"כ יאכל תבשילו:","(ז) רק ג' מצות - דאם היה לו ארבעה היה מסתפק ביום הראשון משנים ושנים לליל שני:","(ח) מן הפרוסה - שפרס ממנה כבר כזית לאפיקומן:","(ט) וב' השלימות לליל ב' - משום לחם משנה יש מאחרונים שכתבו שבזה לא יבצע פרוסה לאפיקומן בליל שני עד לאחר ברכת המוציא קודם ברכת על אכילת מצה כדי שיברך המוציא על לחם משנה שלימות ועל אכילת מצה יברך על הפרוסה שהפרוסה היא לחם עוני. כתב מ\"א אם אפשר לו לשייר בליל א' פרוסה קטנה של כזית ישייר ויניחנה בליל ב' בין שתי השלימות כדי שיהיה לו לחם משנה מלבד הפרוסה שמברך עליה על אכילת מצה כמו שנתבאר בסימן תע\"ג. וכן להיפך אם אין מספיק לו ללילה הראשונה במצה אחת לכל בני ביתו יקח פרוסה מן השניה וישאיר מצה א' וחציה לליל שניה דכיון שהוא שעת הדחק יכול לסמוך על הפוסקים דס\"ל דבליל פסח סגי לכתחלה בפרוסה ויברך המוציא ועל אכילת מצה על הפרוסה שעל גבי השלמה ומהשלמה יעשה כריכה והאפיקומן:"]}],"483":[{"s":"<b>דין מי שאין לו יין. ובו סעיף אחד:</b><br><i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>מי שאין לו <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>יין בליל פסח <i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>מקדש על הפת שמברך המוציא <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ובוצע ומניח ידיו עליו עד שגומר הקידוש <i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>ומברך על אכילת מצה ואוכל ואח\"כ אוכל <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>שאר ירקות ומסלק השלחן ואומר מה נשתנה וכל ההגדה <i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i>עד <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>גאל ישראל ומברך על המרור ואוכל ואח\"כ כורך מצה ומרור ואוכל: <small>הגה בלא ברכה ובמקום <i data-commentator=\"Chok Yaakov\" data-order=\"5\"></i>שנוהגים לשתות משקה הנעשה מדבש שקורין מע\"ד יכול ליקח אותו משקה לארבע כוסות אם אין לו יין (מהרי\"ל) וי\"א שאין עושין קידוש על שאר משקין כמו שנתבאר לעיל סי' רע\"ב סעיף ט' ול\"נ דלענין ד' כוסות יש לסמוך אמאן דאמר דמקדשין על שאר משקין <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>אם הוא <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>חמר מדינה כמו שנתבאר לעיל סי' רע\"ב</small>:","m":["(א) מי שאין לו יין - היינו שאין לו כלל אבל אם יש לו יין אפילו רק על כוס אחד [וה\"ה שאר משקין אם הוא חמר מדינה לפי מה שמסיק הרמ\"א בהג\"ה] יקדש עליו ולא יקדש על הפת אף אם דרכו בשארי שבתות ויו\"ט לקדש על הפת מ\"מ בלילה זה כשתקנו חכמים ד' כוסות תקנו לקדש על היין ולא על הפת. ואם יש לו שני כוסות יקדש על הראשון ואח\"כ יאמר ההגדה בלא כוס ובהמ\"ז יברך על כוס השני ויצא בזה גם דעת הי\"א בסימן קפ\"ב דס\"ל דבהמ\"ז טעונה כוס ואם יש לו ג' כוסות מקדש על אחד ואומר הגדה על אחד ובהמ\"ז על אחד וחצי הלל שאחר בהמ\"ז יאמר בלא כוס:","(ב) ובוצע - עיין בבה\"ל:","(ג) ומניח ידיו עליו - שכיון שמקדש עליו מצוה לאוחזו בידו כשם שאוחז בכוס שמקדש עליו:","(ד) ואח\"כ אוכל שאר ירקות - זהו הכרפס. וטובל במי מלח או בחומץ וקודם מצה כנהוג שאר שנים א\"א לאכול דהא אסור לטעום קודם קידוש. ולענין ברכה עליהם תלוי הדבר באם הוא דבר שממשיך תאות המאכל אין מברך עליהם דהוא בא בכלל הסעודה ואם לאו מברך עליהם בורא פרי האדמה:","(ה) ואומר מה נשתנה וכו' - וה\"ה דאומר הא לחמא עניא וכו'. עד גאל ישראל. עיין במ\"א שכתב דיהללוך לא יאמר בחתימה שנתקנה על הכוס דוקא והעתיק הח\"י את דבריו אבל בפר\"ח מסיק דנראה יותר שיאמרנה וכמו שכתב הד\"מ דאין הכוס מעכב לזה דהא בבהכ\"נ אומרים הלל בלא כוס וכן הסכימו כמה אחרונים:","(ו) ומברך על המרור - וטובלו בחרוסת שלענין נטילה שנית כשרוצה לגמור סעודתו מסיק במאמר מרדכי דצריך ליטול ידיו מדינא דהא הפסיק בהגדה והלילא [ודומיא דפסקינן לעיל דצריך ליטול ידיו לאכילה אע\"ג דנטל מתחלה כדין לדבר שטיבולו במשקה משום דהפסיק באמירת הגדה וה\"נ דכוותיה] אכן אם כוון בנטילה ראשונה לגמור סעודתו ולשמור ידיו שלא לטנפם מסיק שם דא\"צ ליטול שנית:","(ז) בלא ברכה - ר\"ל שא\"צ לברך שנית על המצה אע\"ג דהפסיק הרבה באמירת הגדה אחר הברכה ראשונה שבירך על המצה ואח\"כ גומר הסעודה וכל הסדר בלא כוס יין:","(ח) ובמקומות שנוהגים לשתות וכו' - עיין לעיל בסימן תס\"ז ס\"ח בהג\"ה:","(ט) כמו שנתבאר לעיל וכו' - ר\"ל כמו שהסכים שם כהג\"ה דבלילה אין לקדש על שאר משקין:","(י) יש לסמוך וכו' - כדי שיוכל לעשות הסדר כסדרו ולקיים ד' כוסות:","(יא) אם הוא חמר מדינה - ואפילו במקום שכל השנה אין רוב שתיית העם במי דבש ורק בפסח ג\"כ יש להקל [מ\"א וא\"ר וש\"א דלא כח\"י]. ואפשר עוד דאם שתיית רוב ההמון לאקרי\"ץ או עפי\"ל טראנ\"ק מותר ליקח אותו לארבעה כוסות אם אין לו יין:"]}],"484":[{"s":"<b>מי שרוצה לעשות הסדר בהרבה בתים. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מאן דבעי לברוכי בתרי או בתלת בתי מברך ברישא בביתי' ואכיל כל מאי דצריך <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>ומברך ברכת המזון <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>והדר מברך לכל חד וחד בביתיה ושתן אינהו כסא דקדושא ודאגדתא ואכלי ירקי ומצה <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>ואיהו לא אכיל ושתי בהדייהו ושביק להו למגמ' סעודתייהו <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>ומברכי אינהו ברכת המזון <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ואי לא ידעי <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>יקרא מלה במלה <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>והדר אזיל לביתא אחרינא ועביד הכי והדר אזיל לביתיה וגמר הלילא ושתי כסא דהלילא ואי בעי לאקדומי להנך בתי ברישא בריך להו <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>ולא אכיל ולא טעים והדר אזיל לביתיה ומקדש ואם ירצה <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>יגמור הכל בביתו ואח\"כ ילך לקדש בבתים האחרים ולא יאכל וישתה עמהם:","m":["(א) מאן דבעי וכו' - משום שאין בהם מי שיודע לקדש ולומר הגדה:","(ב) מברך ברישא וכו' - היינו שמקדש ואומר הגדה הכל כסדר ואוכל מצה ומרור ואפיקומן עד בהמ\"ז:","(ג) ומברך בהמ\"ז - ושותה הכוס ובלא ברכת המזון אסור לעקור ממקומו לילך למקום אחר ואפילו בדעתו לאכול שם יותר:","(ד) והדר מברך - ר\"ל שמקדש להם ומברך להם גם בפה\"ג ומברך להם ברכת כרפס ואומר לפניהם ההגדה וברכת כוס שני וגם ברכת המוציא וברכת אכילת מצה ומרור ואע\"ג דבשאר ברכות הנהנין קיימ\"ל שאין יכול לברך לאחרים אא\"כ יהנה עמהן שאני ברכת הלחם של מצה וקידוש היום שהם חובה הלכך יכול לברך להוציא אחרים אף שאינו נהנה וכן ברכת הירקות חשיב ג\"כ מצוה ויכול להוציא אחרים:","(ה) ירקי - היינו כרפס ומרור:","(ו) ואיהו לא אכיל וכו' - שהרי כבר אכל אפיקומן ואסור לו לטעום שוב וכדלעיל בסימן תע\"ח וגם שתיה אסור לכו\"ע שהרי הוא עומד בין כוס ג' לד' וכנ\"ל בסימן תע\"ט:","(ז) ומברכי אינהו בהמ\"ז - אבל הוא אסור לברך בשבילם בה\"מ דבבהמ\"ז אין להוציא אחר אא\"כ אכל ונתחייב גם כן דכתיב ואכלת ושבעת וברכת מי שאכל הוא יברך:","(ח) יקרא מלה במלה - והם יענו אחריו דכל שקורא מלה במלה והאחר עונה עמו לא הוי ברכה לבטלה אע\"פ שיצא מכבר דהרי הוא רק מלמדו לברך:","(ט) ולא אכיל וכו' - ואסור לטעום קודם קידוש כמ\"ש סימן רע\"א. ואם יכוין לצאת ג\"כ בהקידוש שאומר לפניהם יצטרך לאכול שם כזית ולברך בהמ\"ז ג\"כ:","(י) יגמור הכל - אפילו הלל:","(יא) ולא יאכל וישתה - כנ\"ל בסק\"ו:"]}],"485":[{"s":"<b>דין מי שנשבע שלא לאכול מצה. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אמר שבועה שלא אוכל <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>מצה <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>סתם <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>אסור לאכול מצה <i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>בליל פסח אמר שבועה שלא אוכל מצה בליל פסח <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i>לוקה ואוכל מצה בליל פסח:","m":["(א) שלא אוכל מצה סתם - בין אם אמר זה קודם הפסח בין אמר בליל פסח גופא כיון דלא אמר בשבועתו דמשתבע רק אמצת מצוה אלא כולל בשבועתו כל מצה ולאו דוקא מצה של לילה זו חיילא שבועתו דשבועה חל בכולל דברים המותרים עם דברים האסורים בשב ואל תעשה ומ\"מ כתבו הפוסקים דמצוה להתיר שבועתו כדי שיוכל לקיים מ\"ע דאכילת מצה:","(ב) בליל פסח - דכיון דאמר ליל פסח מסתמא כוונתו אמצת מצוה בלחוד:","(ג) לוקה וכו' - משום שבועת שוא דאין שבועה חלה ע\"ד מצוה ומ\"מ אם אמר קונם אכילת מצת מצוה עלי אסור באכילת מצה דנדר חל אדבר מצוה. אם אמר שבועה שלא אוכל מרור של מצוה אסור באכילת מרור דמרור בזמן הזה דרבנן ושבועה חיילא אמצוה דרבנן וה\"ה באמר שלא ישתה ד' כוסות. ומ\"מ כופין אותו שישאל על שבועתו וה\"ה אם אמר שבועה שלא אוכל מצה בליל שני שהוא ג\"כ מדרבנן לדידן דבקיאין אנו בקביעא דירחא דנמי חיילא ואסור אלא שגם בזה יש לכופו שישאל על שבועתו:"]}],"486":[{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>שיעור כזית יש אומרים <i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>דהוי <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>כחצי ביצה: <small>הגה <i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>ויאכלנו ביחד ולא מעט מעט ובירקות צריך <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>למעך חלל האויר שבין הירק ולשער שיעור הכזית בירקות עצמן ולא <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>באויר שביניהם </small> <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>:","m":["(א) דהוי כחצי ביצה - בינונית עם קליפתה ודעת הרמב\"ם דכזית הוא כשליש ביצה ועיין במ\"א וביאור הגר\"א מש\"כ בזה. ולענין דינא במצוה דאורייתא כגון במ\"ע דאכילת מצה יש להחמיר ולאכול עכ\"פ כחצי ביצה [אם לא שהוא חולה וקשה לו לאכול כחצי ביצה יכול לסמוך על הרמב\"ם] ולענין מרור וכה\"ג שהוא דרבנן יש לסמוך בדיעבד אם אכל כשליש ביצה אך לכתחלה כיון שצריך לברך על המרור נראה דאין להקל בזה אם לא שהוא אדם חלש וקשה לו יכול לסמוך ולאכול רק כשליש וכנ\"ל. ולענין בהמ\"ז ששיעורו מד\"ס בכזית [וכן לענין ברכה אחרונה] ספק ברכות להקל ולא יברך עד שידע שאכל כחצי ביצה. ולכתחלה נכון ליזהר שלא יכניס עצמו בספק ברכות ויאכל כחצי ביצה או פחות הרבה משליש ביצה [פמ\"ג] ולענ\"ד נראה דנכון לכתחלה שיאכל כביצה פת דאל\"ה יש חשש ברכה לבטלה על הברכה שבירך מתחלה על הנטילה לאיזה פוסקים וכנ\"ל בסימן קנ\"ח ס\"ב עי\"ש. ועתה נחזור לעניננו דע דמש\"כ המחבר כזית כחצי ביצה לאו מלתא פסיקתא היא בזמנינו דיש מאחרונים שהוכיחו דביצים המצויים בזמנינו נתקטנו הרבה עד למחצה מכפי שהיו בימים הקדמונים שבהם שיערו חכמים ולפ\"ז בכל מקום שהשיעור הוא כחצי ביצה צריך לשער בכביצה בזמנינו ועיין בשע\"ת שהכריע שיש לחלק בזה לענין שיעורין בין דבר שחיובו מן התורה לדבר שחיובו מדרבנן כגון מרור בזה\"ז ואפיקומן וכוסות ונמצא לפ\"ז בזמנינו יתחייב לאכול מצה עד כשיעור ביצה ומרור יצא בדיעבד אף אם לא אכל רק כשליש ביצה וכנ\"ל ועיין במש\"כ לעיל סימן רע\"א בבה\"ל בד\"ה של רביעית:","(ב) ויאכלנו ביחד - עיין לעיל סימן תע\"ה במ\"ב סוף סק\"ט:","(ג) ובירקות צריך למעך חלל האויר - וה\"ה אם יש חלל במצה אינו מצטרף החלל לשיעור כזית וצריך למעכו אבל אם אין חלל במצה אפילו היא רכה ועשויה כספוג א\"צ למעכו:"]}],"487":[{"s":"<b>סדר תפלת ערבית של פסח. ובו ד סעיפים:</b><br>סדר היום <i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>ערבית ושחרית ומנחה אומר שלש ראשונו' ושלש אחרונו' וקדושת היום באמצע אתה בחרתנו וכו' ותתן לנו יי אלהינו את יום חג המצות הזה <i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>את יום טוב <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>מקרא <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>קודש הזה <small> (ע\"ל סי' ת\"צ סעיף ג') </small> זמן חירותינו יעלה ויבא והשיאנו וחותם <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>מקדש ישראל והזמני' <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ואם אמר מקדש השבת <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>וחזר בו תוך כדי דיבור יצא <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>אחרי שהוא יודע שהוא <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>יום טוב ואם חל בשבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אומר את יום <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i>המנוח הזה ואת יום חג המצו' הזה <i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>וחותם <i data-commentator=\"Chok Yaakov\" data-order=\"5\"></i>מקדש השבת <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"5\"></i>וישראל והזמנים <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i><i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>ואין אומרים ברכת מעין <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>שבע:","m":["(א) את יום טוב וכו' - ומנהגנו לומר את יום חג המצות הזה זמן חירותינו מקרא קודש וכו' ואין אומרים באהבה מקרא קודש שהרי כבר אמרו ותתן לנו ה' אלהינו באהבה מועדים לשמחה אכן כשחל בשבת יש אומרים שאומרים שני פעמים באהבה [אחרונים]:","(ב) מקדש ישראל והזמנים - ואם אמר מקדש ישראל לבד לא יצא וכן בשבת אם לא אמר מקדש השבת ואמר מקדש ישראל ג\"כ לא יצא אף שהזכיר באמצע התפלה של שבת כיון שלא חתם בשל שבת וכל זה בין בקידושא בין בצלותא:","(ג) וחזר בו - היינו שחזר ואמר מקדש ישראל והזמנים:","(ד) תוך כדי דיבור - היינו שלא שהה משגמר מקדש השבת רק כדי ג' תיבות ואם שהה יותר משיעור זה לא מהני חזרתו וצריך לחזור לראש הברכה כיון שהחתימה היתה שלא כהוגן אף שהזכיר של יו\"ט באמצע:","(ה) אחרי שהוא יודע - ר\"ל בעת שאמר ברוך אתה ה' היתה כהוגן ע\"ד לסיים בשל יום טוב אלא שאח\"כ נכשל בלשונו ומשמע מלשון זה דאם טעה בעת שאמר ברוך אתה ה' שהיה סבור שהוא שבת אפילו אם חזר בתוך כ\"ד לאחר שסיים מקדש השבת וסיים כדין לא יצא אבל רוב הפוסקים ס\"ל אע\"פ שלא ידע שהוא יו\"ט יצא כיון שנזכר בתוך כדי דבור וחתם כדין כן פסקו הרבה אחרונים ועיין בביאור הגר\"א שגם הוא מכריע כן להלכה:","(ו) המנוח - ומנהגנו לומר את יום השבת הזה ונהרא נהרא ופשטיה [חק יעקב]:","(ז) מקדש השבת וכו' - ובדיעבד אם לא הזכיר רק שבת או ישראל והזמנים לבד יש דעות בין האחרונים אם צריך לחזור או לא ועיין בבה\"ל שהכרענו דאם לא הזכיר רק שבת לבד בודאי אין לחזור הברכה משום זה:","(ח) וישראל והזמנים - וי\"א שצריך לומר ישראל בלא וי\"ו וכן הסכים המהרש\"ל בפ\"ב דביצה אבל מנהגנו כהשו\"ע:","(ט) וא\"א ברכת וכו' - דלא נתקנה אלא מפני המזיקין [וכדלעיל בסימן רס\"ח סק\"כ במ\"ב] ובפסח הוא ליל שמורים ואומרים ויכולו בקול רם וקדיש שלם אחריו [פמ\"ג]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"6\"></i><i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>אין שליח צבור <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>מקדש בבית הכנס':","m":["(י) אין ש\"ץ מקדש וכו' - דענין הקידוש הוא כדי להוציא מי שאין לו יין ובפסח אין עני בישראל שאין לו יין והסכימו האחרונים דאפילו כשאין יין בעיר כ\"א בביהכ\"נ אפ\"ה אין לקדש:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>שכח לומר אתה בחרתנו ואמר יעלה ויבא יצא: <small>הגה ואפילו היה שבת אם הזכיר יעלה ויבא יצא (ב\"י בשם א\"ח) ואם אמר אתה בחרתנו והזכיר בו שבת אפ\"ה <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"7\"></i>צריך לחזור ולהזכירו ביעלה <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>ויבא (תשובת מהרי\"ל) מיהו אם לא הזכירו ביעלה ויבא אין צריך לחזור (ב\"י) וש\"צ ששכח להזכיר של יו\"ט בשחרית ע\"ל סימן קנ\"ו</small>:","m":["(יא) ואמר יעלה ויבוא - דהרי מזכיר ענינו של יום ביעלה ויבוא ומיירי שחתם כל הברכה כדין דאם לא חתם אפילו אמר גם אתה בחרתנו לא יצא ואם נזכר אחר שהתחיל רצה חוזר לאתה בחרתנו ואם עקר רגליו חוזר לראש התפלה ועיין לעיל סימן קכ\"ב ס\"ה ואם לא אמר אתה בחרתנו וגם לא יעלה ויבוא רק והשיאנו אע\"פ שאמר מועדי קדשיך אם לא הזכיר חג פלוני בפרט לא יצא [דה\"ח אבל בפמ\"ג מסתפק בזה]:","(יב) יצא - ואפילו אם נזכר קודם שחתם הברכה א\"צ לחזור לאתה בחרתנו:","(יג) ואפילו היה שבת - ר\"ל דכיון שלא אמר אתה בחרתנו ותתן לנו ממילא לא הזכיר גם של שבת מ\"מ כיון שחזר והזכירו ביעלה ויבוא שאמר ביום השבת הזה וביום חג פלוני הזה יצא דהא עכ\"פ הזכיר של שבת בתוך הברכה ומשמע מלשון זה דאם גם ביעלה ויבוא לא הזכיר של שבת לא יצא ויש לעיין דהא מזכיר שבת בוהשיאנו שאומר והנחילנו וכו' שבת ומועדי קדשך ואולי משום דהוא מזכירו רק סמוך לחתימה לבד ואנן בעינן שיהא פותח נמי בשל שבת כדאיתא בגמרא וצ\"ע:","(יד) צריך לחזור ולהזכירו - כמו שמזכיר שניהם באתה בחרתנו:","(טו) א\"צ לחזור - דיש בזה פלוגתא דרבוותא אם צריך להזכירו ולכן בדיעבד אין צריך לחזור וגם בלא\"ה הרי הזכיר פעם אחת באתה בחרתנו ואיננו לעיכובא בדיעבד לכו\"ע. ודע דהרבה אחרונים הסכימו שאפילו לכתחלה אין להזכיר של שבת ביעלה ויבוא וכן המנהג ועיין בלבוש שכתב טעם נכון לזה שעיקר יעלה ויבוא נתיסד על הזכירה ועל הפקידה ואין שייך זכרון אלא ביו\"ט ובר\"ח דכתיב וביום שמחתכם ובמועדיכם ובר\"ח וגו' ונזכרתם ולא נזכר שם שבת כלל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>בליל ראשון של פסח <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"9\"></i>גומרין ההלל בציבור בנעימ' <i data-commentator=\"Chok Yaakov\" data-order=\"8\"></i>בברכה תחלה וסוף וכן בליל שני של שני ימים טובי' של גליות: <small>הגה וכל זה אין נוהגים כן כי אין אנו אומרים בלילה בבהכ\"נ ההלל כלל</small>:","m":["(טז) אין אנו נוהגים - היינו במדינות אלו ומנהג ספרדים לומר:"]}],"488":[{"s":"<b>דין תפלת שחרית של פסח. ובו ג סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>שחרי' נכנסים לבית הכנס' <i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>וקורין <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>הזמירו' של שבת ומתפללין תפלת שחרי' <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>וגומרין ההלל <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><small> (ומברכין <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>לקרות ההלל) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"•\" data-order=\"4\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"5\"></i>ואין מפסיקין בו אלא כדרך שאמרו בקריא' שמע באמצע הפרק שואל בשלום אביו <i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>או רבו ומשיב שלום לאדם נכבד שנתן לו שלום ובין הפרקים שואל בשלום אדם נכבד ומשיב שלום לכל אדם: <small>הגה ודוקא בב' ימים הראשונים <i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i>שגומרים בהם ההלל דינא הכי לענין הפסקה אבל בימים שאין גומרים (ע\"ל סי' תכ\"ב סעיף ד') </small>: <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"6\"></i>ואם פסק באמצע ושהה אפי' כדי לגמור את כולו אינו צריך לחזור אלא למקום שפסק:","m":["(א) וקורים הזמירות וכו' - היינו המזמורים שאומרים קודם פסוקי דזמרה וגם מזמור שיר ליום השבת אומרים דיו\"ט נמי אקרי שבת. וכן אומרים ברכת נשמת כמו בשבת ואחר ברכו אומרים ברכת יוצר אור כמו בחול:","(ב) וגומרין ההלל - ואם חיסר פסוק אחד או תיבה אחת צריך להתחיל אח\"כ מאותו פסוק ולגמור עד סוף ההלל דאם יאמרנו במקום שנזכר הו\"ל קריאה למפרע ולא יצא:","(ג) לקרות ההלל - ר\"ל שלא יאמר לגמור ההלל דשמא ידלג תיבה או אות אחת ויש חשש ברכה לבטלה ואם אמר לגמור יצא ובמקום שנהגו לומר לגמור אין לבטל מנהגם [פמ\"ג]. אם בא לבהכ\"נ סמוך להלל יקרא תחלה הלל עם הצבור ואח\"כ יתפלל והוא שלא יעבור זמן ק\"ש ותפלה עי\"ז ועיין לעיל בסימן תכ\"ב במ\"ב סקט\"ז:","(ד) כדרך שאמרו בק\"ש וכו' - ופרטי ופרטי דינים אלו עיין לעיל סימן ס\"ו:","(ה) באמצע הפרק וכו' - ואלו הן הפרקים הללויה הללו עבדי ה' וגו'. בצאת ישראל ממצרים וגו'. לא לנו ה' לא לנו וגו'. אהבתי וגו'. הללו את ה' כל גוים וגו' מן המצר וגו'. ורד\"ק כתב דמן המצר אינו תחלת המזמור אלא מתחיל הודו לה' כי טוב וגו':","(ו) באמצע - היינו אפי' באמצע הפרק:","(ז) ושהה וכו' - מדסתם משמע אפי' שהה באונס ועיין לעיל בסימן תכ\"ב סקכ\"ד במ\"ב:","(ח) אפילו עשרה קורין כאחד - ר\"ל אפילו היכא שמוציאין ידי חובה באמירתן לאחרים ולא אמרינן תרי קלא לא משתמעי כדאשכחן סימן קמ\"א ס\"ב לענין קה\"ת דהלל חביבי להו משום זכרון הנס ויהבי דעתייהו ושמעי. ומה\"ט ג\"כ המנהג שמקדשין שנים או יותר יחד בשבת ויו\"ט או כשיושבין בסוכה כמה בעלי בתים ומקדשין להוציא בני ביתם משום דהקידוש חביב להם ויהבי דעתייהו ושמעי ומ\"מ יותר טוב שלא יקדשו בבת אחת היכי שצריכין להוציא ב\"ב אלא זה אחר זה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"7\"></i>בהלל <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i>אפי' עשרה <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>קורין כאחד:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"8\"></i>מוציאין שני ספרים וקורין בראשון חמשה גברי <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"5\"></i><small> (ואם מוסיפין בי\"ט ע\"ל ר\"ס רפ\"ב) </small> בפרשת בא <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"9\"></i>מן משכו עד מארץ מצרים על צבאותם <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"6\"></i>ומפטיר קורא בשני בפרש' פנחס ובחדש הראשון ומפטיר ביהושע בעת ההיא ומתפללין תפלת מוסף <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"10\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"7\"></i>ואין מזכירין גשם מכאן ואילך <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><small> (וע\"ל סי' <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>קי\"ד ס\"ג) </small> וכן פוסקין משם ואילך מלשאול בברכת השנים: <small>הגה ונוהגין לומר בכל י\"ט בתפלת מוסף פסוקי מוסף היום אחר שאמר על ידי משה עבדך כאמור</small>:","m":["(ט) ומפטיר קורא וכו' - ועיין לעיל בסימן קל\"ז במ\"ב סקי\"א:","(י) בעת ההיא - ויש מתחילין ויאמר יהושע אל העם התקדשו וכן נוהגין עכשיו:","(יא) ואין מזכירין וכו' - דעת המחבר דהוא מנהג ספרד שאפילו במוסף גופא אין מזכירין גשם ולזה כתב רמ\"א ועיין לעיל סימן קי\"ד ס\"ג דשם מבואר בהג\"ה דמנהגנו הוא כפוסקים דס\"ל דהצבור מזכירין במוסף עד שישמעו שהש\"ץ אינו מזכיר בתפלתו שחוזר בקול רם אז הם פוסקין במנחה וה\"ה היחיד שאיחר תפלתו במוסף עד אחר שהתפלל הש\"ץ ופסק לומר משיב הרוח ומוריד הגשם ג\"כ שוב לא יזכיר גשם וע\"ש במ\"ב ובה\"ל כמה פרטים בדין זה:","(יב) משם ואילך מלשאול וכו' - היינו בחוה\"מ שוב לא יבקש על מטר ובדיעבד אם שכח ועבר עיין לעיל בסימן קי\"ז ס\"ג ובבה\"ל. והנה אף שהסכימו הפוסקים שאין נכון שיכריז השמש ד\"ז בצבור ששוב לא יזכירו גשם ומטר שנראה כאלו ממאנים על הגשמים וע\"ד שאמרו אין מתפללין על רוב גשמים מ\"מ נ\"ל שנכון מאוד שהשמש יזכיר בחשאי לרוב העולם קודם תפלת מעריב של לילה ראשונה של חוה\"מ שיאמרו ותן ברכה וכו' כי האנשים פשוטין רובן נכשלין בלילה ראשונה וכן למחר בתפלת שחרית עד שישמעו מן הש\"ץ שפסק ויש בזה חשש כמה מאות ברכות לבטלה:","(יג) ונוהגין לומר וכו' - ובדיעבד אף אם לא הזכיר אותם כלל יצא. ואם טעה במוספין והזכיר של יום אחר וכן בסוכות שאמר ביום א' דחוה\"מ מה שאינו שייך כלל לאותו יום כגון שאמר ביום הרביעי אם לא סיים הברכה יתחיל מפסוקי הקרבנות ואם סיים הברכה א\"צ לחזור [ח\"א בסוף כלל כח]:"]}],"489":[{"s":"<b>סדר תפל' ליל שני של פסח וספירת העומר. ובו י סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>בליל שני אחר <i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>תפל' ערבית <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>מתחילין <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>לספור העומר ואם שכח לספור בתחל' הלילה <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>הולך וסופר כל הלילה <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i>ומצוה <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>על כל אחד <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i>לספור לעצמו וצריך לספור <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i><i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"5\"></i>מעומד <i data-commentator=\"Chok Yaakov\" data-order=\"6\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>ולברך <i data-commentator=\"Chok Yaakov\" data-order=\"7\"></i>תחל' <i data-commentator=\"Chok Yaakov\" data-order=\"8\"></i>וסופר <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>הימים <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"6\"></i><i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>והשבועו' כיצד ביום הראשון אומר <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"9\"></i>היום יום אחד <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"8\"></i><small> (בעומר) </small> <i data-commentator=\"Chok Yaakov\" data-order=\"10\"></i>עד שמגיע לשבעה ימים ואז יאמר היום שבעה ימים שהם <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>שבוע <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>אחד <small> (בעומר) </small> וביום שמיני אומר היום שמונה ימים שהם שבוע א' ויום א' <small> (בעומר) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>וכן עד שיגיע לארבע' עשר יאמר היום ארבעה עשר ימים שהם שני שבועו' <small> (בעומר) </small> ועל דרך זה <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>מונה והולך <i data-commentator=\"Chok Yaakov\" data-order=\"11\"></i>עד <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"10\"></i>מ\"ט יום:","m":["(א) בליל שני - כתבו האחרונים דאומרים מערבית השייך ליום ב' אפילו חל ליל שני במו\"ש ואע\"פ דבשארי חגים שחל יום ראשון בשבת אומרים מערבית של יום א' בליל שני שאני הכא דהמערבית הוא מענין של ספירה:","(ב) אחר תפלת ערבית - וקודם עלינו דכל מה דאפשר לאקדומי מקדמינן כדי שיתקיים יותר מה שכתוב תמימות תהיינה:","(ג) מתחילין לספור וכו' - ונשים ועבדים פטורות ממצוה זו דהוי מ\"ע שהזמן גרמא וכתב המ\"א מיהו כבר שויא עלייהו חובה וכמדומה דבמדינותינו לא נהגי נשי כלל לספור וכתב בספר שולחן שלמה דעכ\"פ לא יברכו דהא בודאי יטעו ביום אחד וגם ע\"פ רוב אינם יודעים פירוש המלות:","(ד) הולך וסופר וכו' - דכל שלא עבר הלילה לא נפיק עדיין מכלל הכתוב תמימות תהיינה:","(ה) לספור לעצמו - דכתיב וספרתם לכם משמע שהמצוה חל על כל יחיד ויחיד והנה משמע מזה דבספירה אינו כמו בשאר מצות התלוי באמירה לענין קידוש והבדלה וכיו\"ב דאם שמע לחבירו ונתכוין לצאת דיוצא בזה משום דשומע כעונה והכא גילתה התורה דלא יצא כל כמה דלא ספר בעצמו אבל יש מאחרונים שכתבו דכונת התורה הוא רק דלא נימא דמצוה זו אב\"ד לבד קאי כמו בשמיטין ויובלות דכתיב שם וספרת לך אלא קאי אציבור אבל באמת אם שמע מחבירו שספר והתכוין לצאת וגם חבירו כוון להוציאו יצא כמו בכל מקום דקיי\"ל שומע כעונה וכל זה בספירה אבל בברכה שמברכין על הספירה דכו\"ע אפשר לצאת ע\"י חבירו אפילו הוא בקי וכמו בכל הברכות מיהו מנהג בכל ישראל שכל אחד מברך וסופר לעצמו ואין סומכין על הש\"ץ. כתבו האחרונים דספירה מותר בכל לשון ובלבד שיבין אותו הלשון ואם אינו מבין אפילו סיפר בלשה\"ק אינו יוצא דכיון דלא ידע מאי קאמר אין זה ספירה:","(ו) וצריך לספור מעומד - וצריך לעמוד משעה שמתחיל הברכה. ובדיעבד אפילו אם סיפר מיושב יצא [פוסקים]:","(ז) וסופר הימים והשבועות - דכתיב תספרו חמשים יום וכתיב שבעה שבועות תספר לך. ואם סיפר ימים לחוד ולא הזכיר שבועות י\"א שיצא בדיעבד וי\"א שצריך לחזור ולספור ימים ושבועות כדין וע\"כ חוזר וסופר בלא ברכה [ואם שכח לחזור ולספור מונה שאר ימים בברכה] ואם מנה שבועות ולא ימים כגון שאמר ביום השביעי היום שבוע אחד ולא הזכיר ימים כלל לכו\"ע לא יצא:","(ח) בעומר - וברוב פוסקים הנוסח לעומר מיהו עיקר ד\"ז אינו אלא לכתחלה כדי לבאר שהוא מונה מיום שהקריבו את העומר והלאה ואם לא אמר אלא היום כך וכך נמי יצא:","(ט) וביום שמיני יאמר וכו' - ואם לא אמר אלא היום שמונה ימים ולא סיים שהם שבוע אחד וכו' נמי יצא שהרי הזכיר שבועות אתמול ביום השביעי וכן אם לא אמר אלא היום שבוע אחד ויום אחד בלחוד נמי יצא שהרי כבר הזכיר הימים שעברו כל אחד ביומו. אומרים שבוע אחד ולא אחת. וכן אומרים שני שבועות ולא שתי דשבוע לשון זכר. עד עשרה אומר ימים ומי\"א ואילך אומר יום. כן יש לומר מנין המועט מתחלה כגון אחד ועשרים יום וכל אלו הדברים אינן לעיכובא אלא לצחות הלשון:","(י) ועל דרך וכו' - ומנהג לומר אחר הספירה יהי רצון וכו' שיבנה בהמ\"ק וכו' כלומר ואז נקיים מצות הבאת העומר ויש נוהגים ג\"כ לומר מזמור אלהים יחננו וגו':","(יא) זה וכו' - כתבו האחרונים דאם אמר בלשון אחר כגון ביום ל\"ט אמר היום ארבעים חסר אחת נמי יצא:","(יב) חוזרים וכו' - הוא מדברי הרשב\"א בתשובה סימן קנ\"ד ומבואר שם שהקהל התפללו גם מעריב קודם ולענין מעריב אין להם לחזור ולהתפלל משום טרחא דציבורא (וכדלעיל ריש סימן רס\"ג סעיף י\"ד) רק לענין ספירה לא משגחינן בטרחא דידהו כי איך יאמר למשל עשרה ימים ואינן אלא תשעה כי אותו היום תשיעי הוא ולא עשירי עד צאת הכוכבים עכ\"ד שם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אם טעו ביום המעונן ובירכו על ספירת העומר <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"12\"></i>חוזרים לספור כשתחשך והמדקדקים אינם סופרים <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i><i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>עד <i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>צאת הכוכבים וכן ראוי לעשות:","m":["(יג) לספור כשתחשך - ובברכה כדין:","(יד) והמדקדקים - ר\"ל דמן הדין היה אפשר להקל לספור משתחשך אף קודם צה\"כ דבה\"ש הוא ספק לילה ואזלינן לקולא בספק דרבנן בספירה בזה\"ז שהוא מדרבנן לרוב הפוסקים אלא דמ\"מ אינו נכון להכניס עצמו לספק לכתחלה ולהכי המדקדקים ממתינים עד צה\"כ שהוא בודאי לילה:","(טו) וכן ראוי לעשות - ר\"ל לכתחלה ומ\"מ בדיעבד אם בירך ביה\"ש יצא וכנ\"ל אבל הא\"ר מפקפק בזה ומצדד דנכון שיחזור ויספור בצה\"כ בלי ברכה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i><i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>המתפלל עם הצבור <i data-commentator=\"Ba'er Hetev\" data-order=\"13\"></i>מבעוד יום <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>מונה עמהם בלא ברכה ואם יזכור בלילה יברך ויספור. <small>הגה <i data-commentator=\"Chok Yaakov\" data-order=\"13\"></i>ואפי' ענה אמן על ברכת הקהל אם היה <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>דעתו <i data-commentator=\"Chok Yaakov\" data-order=\"14\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"14\"></i>שלא לצאת יחזור ויברך ויספור בלילה (ב\"י בשם רשב\"א)</small>:","m":["(טז) מבעוד יום - יש מאחרונים שפירשו דהיינו בין השמשות דהוא ספק לילה ויוצאין אז ידי ספירה לפוסקים דס\"ל דספירה בזה\"ז דרבנן אכן הוא רוצה לדקדק ולספור מצאת הכוכבים וכנ\"ל וקאמר המחבר דהוא ימנה עמהם פן ישכח אח\"כ ויחשוב בדעתו אם אזכור אח\"כ בלילה למנות אין אני רוצה לצאת בספירה זו וכדלקמיה בהג\"ה. וע\"כ כשיגיע הזמן אח\"כ יברך ויספור ועיין בה\"ל:","(יז) שלא לצאת - ודוקא אם מתכוין שלא לצאת אבל בסתמא יצא למ\"ד דמצות א\"צ כונה ואף דפסקינן לעיל בסימן ס' דמצות צריכות כונה אפשר לענין ברכה שצריך להזכיר שם שמים צריך לחוש להך דעה:","(יח) ויברך ויספור בלילה - ואפילו בע\"ש שכבר קיבל שבת וגם התפלל עם הצבור אפ\"ה יברך ויספור בלילה כיון שלא רצה לצאת במה שסיפר עמהן ביה\"ש. כתבו האחרונים דאם יצאו הכוכבים מותר לו לספור אפילו לא התפלל עדיין מעריב ואפילו הוא במו\"ש דהא לילה הוא לכל מילי ואפילו לקדש ולהבדיל מותר קודם תפלה אלא שאסור במלאכה עד שיבדיל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>מי ששואל אותו חבירו בין השמשות כמה ימי הספירה בזה הלילה יאמר לו אתמול היו כך <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>שאם יאמר לו <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"15\"></i>היום כך וכך <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>אינו יכול <i data-commentator=\"Chok Yaakov\" data-order=\"15\"></i>לחזור ולמנו' <i data-commentator=\"Ba'er Hetev\" data-order=\"16\"></i>בברכה אבל קודם בין השמשות כיון שאינו זמן ספירה אין בכך כלום: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"16\"></i>וכשהגיע <i data-commentator=\"Ba'er Hetev\" data-order=\"17\"></i>הזמן אסורים לאכול עד שיספור ואפי' התחיל לאכול <i data-commentator=\"Chok Yaakov\" data-order=\"17\"></i>פוסק וסופר מיהו אם התחיל לאכול קודם שהגיע הזמן א\"צ להפסיק אלא גומר אכילתו וסופר אח\"כ: (ד\"ע למאן דאמר ספירה בזמן הזה דאורייתא)</small>:","m":["(יט) בין השמשות וכו' - נקט בין השמשות משום דבדיעבד אם בירך ביה\"ש יצא וכנ\"ל וכ\"ש אם שאל אותו אחר צה\"כ שצריך ליזהר מלהשיב היום כך וכך:","(כ) היום כך וכך - ואפי' בלשון לע\"ז. ואם לא אמר היום לית לן בה משום דעיקר מצות ספירה הוא שיאמר היום כך וכך:","(כא) אינו יכול וכו' - דאע\"ג דלא אמר בעומר יצא בדיעבד וכנ\"ל בסק\"ח:","(כב) לחזור ולמנות בברכה - שכבר יצא בזה ידי ספירה למ\"ד מצות א\"צ כונה ואף דאנן קי\"ל דצריכות כונה וזה הלא לא כוון לצאת בזה ידי מצוה לענין ברכה צריך להחמיר ולחוש להך דעה ולא יברך על הספירה שימנה אח\"כ. ויש עוד עצה שיכוין בפירוש שלא לצאת בזה ידי ספירה. כתבו האחרונים דמיירי ששאל אתו קודם שהגיע לשבועות הא אי שאל לו בשעה שהגיע לשבועות אפילו אמר לו היום כך וכך לאו כלום הוא כל שלא הזכיר שבועות וצריך לחזור ולספור בברכה:","(כג) וכשהגיע הזמן - ר\"ל צאת הכוכבים ואפילו אם כבר התפללו ק\"ש ותפלה דאל\"כ בלא\"ה אסור משום ק\"ש ותפלה. והסכימו האחרונים דלפי מאי דפסקינן לעיל בסימן רל\"ה להחמיר מחצי שעה קודם הזמן ה\"ה הכא יש לנו להחמיר שלא לאכול מחצי שעה הסמוך לספירה והלאה [אפילו אם כבר הקדים והתפלל] אך במקום שהמנהג שהשמש קורא לספור ספירה אין להחמיר בקודם זמנו:","(כד) לאכול - וה\"ה שאר מלאכות וכדלעיל בסימן רל\"ב ורל\"ה:","(כה) פוסק וסופר - היינו למ\"ד ספירה בזה\"ז דאורייתא וכדמציין בהג\"ה וא\"כ לדידן דנקטינן ספירה בזה\"ז דרבנן אינו פוסק וכדלעיל בסימן רל\"ב לענין מנחה ויש מאחרונים שכתבו דלפיכך חשש הרמ\"א פה בעניננו להחמיר כאותו דעה שהוא דאורייתא משום דהוא דבר שאין בו טורח כלל להפסיק מעט ולספור:","(כו) קודם שהגיע הזמן - ולפי מה דכתבנו לעיל דמחצי שעה סמוך לזמן מתחיל האיסור יהיה שייך דינא דרמ\"א כשהתחיל לאכול ביותר מחצי שעה קודם הזמן:","(כז) א\"צ להפסיק - אפילו למ\"ד ספירה בזה\"ז דאורייתא כיון שיש עוד שהות לספור:"]},{"s":"אם <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>אינו יודע החשבון ופתח אדעתא דלסיים כמו שישמע מחבירו ושתק עד ששמע מחבירו <i data-commentator=\"Turei Zahav\" data-order=\"8\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"18\"></i>וסיים כמוהו <i data-commentator=\"Ba'er Hetev\" data-order=\"18\"></i>יצא:","m":["(כח) ופתח - את הברכה:","(כט) וסיים כמוהו יצא - ר\"ל אף בברכה דאדעתא דהכי פתח הברכה וסיים ואיכא סיום ופתיחה ומ\"מ לכתחלה אין לו לברך אלא א\"כ יודע מתחלה איזה יום היום דאסור להפסיק אפילו בשתיקה בין הברכה להמצוה יותר מכדי דיבור:"]},{"s":"אם <i data-commentator=\"Turei Zahav\" data-order=\"9\"></i>פתח ואמר בא\"י אמ\"ה אדעתא דלימ' היום ד' שהוא סבור שהם ד' ונזכר וסיים בה' והם ה' או איפכא שהם ד' ופתח אדעתא דלימא ארבע' <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>וטעה וסיים בה' <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"19\"></i>אינו חוזר <i data-commentator=\"Ba'er Hetev\" data-order=\"19\"></i>ומברך:","m":["(ל) וסיים בה' - ר\"ל שסיפר חמשה ימים:","(לא) וטעה וסיים וכו' - ר\"ל שסיפר חמשה:","(לב) אינו חוזר ומברך - האחרונים תמהו על דין זה דבשלמא ברישא שסיים בה' והוא ה' ניחא דיצא שהרי סיפר כדין אע\"ג דבשעת ברכתו סבור שהוא ד' לאו כלום הוא שהרי אף בלא בירך כלל יצא אבל בסיפא מאי מהני לן שבשעת ברכה ידע איזה יום הוא הלא עכ\"פ בפיו סיפר יום שאינו והסכימו דבזה צריך לספור מחדש ולברך דברכתו ראשונה היתה לבטלה כיון שסיים אחריה יום אחר אם לא שנזכר תוך כדי דיבור לספירתו שאז חוזר וסופר כדין והברכה עולה לו. ודע עוד דאף דבשו\"ע מיירי שבעת הברכה היה יודע יום הספירה ובירך אדעת לספור כהוגן אלא שאח\"כ טעה וסיים שלא כהוגן אבל כמה אחרונים הסכימו דאף אם בעת הברכה היה דעתו ג\"כ על יום אחר וכן סיפר בטעות מ\"מ אם בתוך כדי דיבור נזכר שטעה יסיים תיכף כהוגן ויוצא בזה. עוד כתבו דאם טעה ואמר היום יום ד' בעומר ובתוך כ\"ד נזכר שהוא יום חמישי דיו שיסיים חמישי בעומר ויוצא בזה אף שלא אמר היום יום ה' כיון שהוא עדיין תוך כדי דיבור:"]},{"s":"שכח ולא בירך כל הלילה <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>יספור ביום <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>בלא ברכה:","m":["(לג) יספור ביום - כדעת הרבה פוסקים דבדיעבד ספירת יום עולה לספירה:","(לד) בלא ברכה - דיש לחוש לדעת הפוסקים דאין זמן ספירה אלא בלילה וכשמברך ביום הוא לבטלה מיהו מכאן ולהבא סופר בכל לילה בברכה ולא הוי כדילג יום אחד לגמרי שאינו סופר עוד בברכה וכדלקמיה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>אם שכח לברך באחד מהימים בין יום ראשון בין משאר ימים סופר בשאר ימים <i data-commentator=\"Ba'er Hetev\" data-order=\"20\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"20\"></i>בלא <i data-commentator=\"Eshel Avraham\" data-label=\"ב\" data-order=\"2\"></i>ברכה <i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>אבל אם הוא מסופק אם דילג יום אחד ולא ספר יספור בשאר ימים בברכה:","m":["(לה) שכח לברך וכו' - ר\"ל שלא סיפר ולא נזכר עד ספירה שאחריה. וה\"ה אם נודע לו שאתמול טעה במנין וספר ספירה אחרת דינו כמו שלא סיפר כלל:","(לו) סופר בשאר ימים - כדעת הרבה פוסקים דאין ספירת הימים מעכבין זה את זה וכל יומא ויומא מצוה בפ\"ע היא:","(לז) בלא ברכה - לחוש למ\"ד דספירת שבע שבתות תמימות בעינן והא ליכא דהא חסר חד יומא ונכון בזה שישמע הברכה מן הש\"ץ או מאחד מהמברכין ויענה אמן בכונה לצאת ואח\"כ יספור [א\"ר ופר\"ח]:","(לח) יספור בשאר ימים בברכה - דאיכא ספק ספיקא שמא לא דילג כלל ואת\"ל שדילג שמא הלכה כאותן פוסקים דכל יום הוא מצוה בפ\"ע. וה\"ה בכל דבר שדינו לחזור ולספור בלי ברכה מחמת ספק אם לא חזר וסיפר יספור שארי לילות בברכה [אחרונים]. ולכן אם טעה בימים ולא טעה בשבועות או טעה בשבועות ולא טעה בימים דדינו לחזור ולספור בלא ברכה וכנ\"ל בסק\"ז אם לא חזר וסיפר אפ\"ה מונה שאר ימים בברכה ועיין ביאור הלכה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>ליל שבת וליל יום טוב מברכין וסופרים <i data-commentator=\"Turei Zahav\" data-order=\"10\"></i><i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>אחר <i data-commentator=\"Ba'er Hetev\" data-order=\"21\"></i>קידוש בבית הכנסת <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>ובמוצאי שבת ויום טוב <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"20\"></i>קוד' הבדל' <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>אחר קדיש <i data-commentator=\"Ba'er Hetev\" data-order=\"22\"></i>תתקבל <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"21\"></i>וכשחל י\"ט האחרון <i data-commentator=\"Ba'er Hetev\" data-order=\"23\"></i>של פסח במוצאי שבת דאז אומר קידוש והבדלה בפעם א' <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>יש לספור קודם שמברכין על הכוס בבית הכנסת: <small>הגה ואם אין לו יין וצריך לקדש יקנה\"ז ע\"ל סי' רצ\"ו</small>:","m":["(לט) אחר קידוש בבהכ\"נ - שכל מה שנוכל להקדים קדושת היום יש לנו להקדים ואם סופר בביתו יספור קודם קידוש דאסור לאכול קודם ספירה וכנ\"ל:","(מ) קודם הבדלה - דאפוקי יומא מאחרינן ליה כל מה דאפשר:","(מא) אחר קדיש תתקבל - ר\"ל מה שאומרים אחר ויהי נועם ואתה קדוש דאז הוא גמר התפלה דקדיש קמא אינו גומר שאינו קדיש שלם. ויתן לך אומרים אחר הספירה:","(מב) וכשחל יו\"ט האחרון וכו' - להכי נקט יו\"ט אחרון דשביעי של פסח אינו חל במו\"ש וליל שני של פסח אין מקדשין בבהכ\"נ כמ\"ש בסי' תפ\"ז [הגר\"א וח\"י]:","(מג) יש לספור קודם - כנ\"ל דאפוקי יומא מאחרינן כמה דאפשר אע\"ג שמקבל הכא קדושת יו\"ט בקידושו מ\"מ קדושת שבת גדולה מקדושת יו\"ט ודעת הט\"ז דלאו דוקא אם חל יו\"ט אחרון במו\"ש דה\"ה אפילו בחול נמי יש להקדים ספירה לקידוש דטפי עדיף לאחר קדושת יום השביעי שהוא מן התורה מלקבל קדושת יו\"ט אחרון שאינו אלא מדרבנן אבל האחרונים חלקו עליו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i><i data-commentator=\"Turei Zahav\" data-order=\"11\"></i><i data-commentator=\"Magen Avraham\" data-order=\"17\"></i>אסור <i data-commentator=\"Chok Yaakov\" data-order=\"22\"></i>לאכול <i data-commentator=\"Ba'er Hetev\" data-order=\"24\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"24\"></i>חדש <i data-commentator=\"Chok Yaakov\" data-order=\"23\"></i>אף בזמן הזה בין לחם בין קלי בין כרמל עד תחל' ליל י\"ח בניסן ובארץ ישראל <i data-commentator=\"Chok Yaakov\" data-order=\"24\"></i>עד תחל' י\"ז בניסן:","m":["(מד) אסור לאכול חדש - היינו תבואה שנשרשה אחר ט\"ז בניסן שהוא זמן הקרבת העומר דאם נשרשה קודם העומר העומר מתירה כדאיתא ביו\"ד סימן רצ\"ג וע\"ש עוד שחדש שייך רק בחמשת המינים חטים ושעורים וכוסמין ושבולת שועל ושיפון:","(מה) אף בזמן הזה - מדכתיב ולחם וקלי וכרמל לא תאכלו עד עצם היום הזה וגו' בכל מושבותיכם משמע מזה דאף בחוץ לארץ נוהג איסור עד עצם היום דהיינו יום הבאת קרבן שהוא ט\"ז בניסן ומשום ספיקא דיומא מחמרינן עוד על יום אחד. והנה ביו\"ד סימן רצ\"ג כתב רמ\"א היתר לחדש דהוי ס\"ס חדא שמא התבואה היא משנה שעברה ואת\"ל משנה זו דלמא נשרשה קודם לעומר וה\"ה אם הוא מקום שמביאים תבואה ממקומות אחרים שתבואתן נשרשת קודם לעומר וכתבו האחרונים דבמדינת פולין אין להקל כ\"א בחטין ושיפון דרובא דרובא נזרעים בחודש חשון ואין שייך בהם חדש [אם לא אותן שידועין שנזרעו בקיץ] אבל שעורים ושבולת שועל וכוסמין רובן וכמעט כולם נזרעים אחר הפסח וגם אין רגיל להביא שם תבואה ממדינות אחרות אין להקל בם. ומ\"מ רוב העולם אין נזהרין כלל באיסור חדש ויש שלמדו עליהם זכות לפי שהוא דבר קשה להיות זהיר בזה ולכן סומכין מפני הדחק על מקצת הראשונים שסוברין שחדש בחו\"ל אינה אלא מד\"ס שגזרו משום א\"י ולא גזרו אלא במקומות הסמוכין לא\"י כגון מצרים ובבל ויש שלמדו עליהם זכות שסוברין שחדש אינו נוהג אלא בתבואה של ישראל אבל לא בשל עכו\"ם ולפ\"ז צריך להזהיר לישראלים שיש להם תבואה זרועה בשדות שלהם שינהגו בה איסור חדש. והנה אף שאין בידינו למחות ביד המקילין מ\"מ כל בעל נפש לא יסמוך על התירים הללו ויחמיר לעצמו בכל מה שאפשר לו כי להרבה גדולי הראשונים הוא איסור דאורייתא בכל גווני. ודע עוד דאף שכתבנו לעיל בשם האחרונים דבחטין אין לחוש כלל שמא הם של חדש מפני דהרוב נזרעו בודאי בחודש חשון כהיום שדרך להביא ע\"ד מסלת הברזל קמח חטים ממקומות הרחוקין וידוע שבפנים רוסיא נמצא הרבה מקומות שנזרעו החטין בקיץ ומצוי שם חדש כמעט יותר מן הישן אם יודע שבא הקמח משם צריך ליזהר בזה בימות החורף שאז כבר נעשין הקמח מתבואה חדשה. ולענין שכר ויתר דיני חדש עיין ביו\"ד סי' רצ\"ג ובאחרונים שם:","(מו) בין קלי - גרעינים של חמשת המינים הנ\"ל הקלויין באור:","(מז) בין כרמל - היינו שנתמולל ביד ולא הובהב באור:","(מח) עד תחלת וכו' - וכתבו האחרונים דאף הנזהרים מחדש אינם נזהרים בפליטת כלים אם לא שברור לו שנתבשל בו מתבואה חדשה ונראה שאף בזה אין להחמיר רק בתוך מעל\"ע מן הבישול הראשון:","(מט) ובא\"י עד תחלת וכו' - דשם אינו אלא יום אחד והא דמחמרינן כל יום ט\"ז משום דכתיב עד עצם היום הזה וקי\"ל דעד ועד בכלל:"]}],"490":[{"s":"<b>סדר תפלת יום שני ותפלת חולו של מועד. ובו ט סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>ביום שני קורין בפרשת אמור <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>שור או כשב <i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>עד סוף <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>הענין ומפטיר קורא כמו ביום ראשון ומפטיר במלכים בפסח דיאשיהו מוישלח המלך עד ואחריו לא קם כמוהו:","m":["(א) שור או כשב - דמיירי שם מעניני כל המועדים וגם של פסח:","(ב) עד סוף הענין - דהיינו עד וידבר משה את מועדי ה' וגו'. וכתבו הספרים דטוב לעשות ביום ב' בסעודה איזה דבר לזכר סעודת אסתר שביום ההוא נתלה המן:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>יום ג' שהו' חש\"מ ערבית ושחרית ומנחה <i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>מתפלל כדרכו ואומר יעלה ויבא בעבודה ואם לא אמרו מחזירין אותו וכן מזכירו בברכת המזון <i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i>ואם לא אמרו <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>אין מחזירין אותו ובמוסף מתפלל כדרך שמתפלל במוסף של י\"ט: <small>הגה אלא כשמגיע לעל ידי משה עבדך כאמור אומר והקרבתם עולה וגו' עד ושני תמידים כהלכתם (טור)</small>:","m":["(ג) אין מחזירין אותו - דדוקא בתפלה דלא סגי דלא יתפלל וכיון שלא התפלל כראוי יחזור [דהיינו אם נזכר לאחר שעקר רגליו חוזר לראש ואם עד שלא סיים תפלתו חוזר לרצה] משא\"כ בברכת המזון בחול המועד דאי בעי לא אכיל דבר המחייב לבהמ\"ז שיאכל בשר ופירות ע\"כ אין מחזירין אותו בכל גווני ועיין לעיל בסימן קפ\"ח ס\"ז ובמ\"ב ובה\"ל שם:","(ד) אומר והקרבתם עולה וגו' - ר\"ל שלא יאמר ובחודש הראשון דכבר עבר:","(ה) ובחולו של מועד וכו' - ש\"מ דח\"ה לא מקרי יו\"ט וא\"ל בחוש\"מ בבהמ\"ז הרחמן הוא ינחילנו יום שכולו טוב. וביו\"ט שחל להיות בשבת כתב הא\"ר שיאמר הרחמן על כל אחד בפני עצמו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>נוהגים שבי\"ט <i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i>אומר את יום טוב מקרא קודש <i data-commentator=\"Eshel Avraham\" data-label=\"ב\" data-order=\"2\"></i>הזה <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ובחש\"מ אומר <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>את יום מקרא קודש הזה <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><small> (ואנו <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"4\"></i>אין נוהגין לומר מקרא קודש כלל לא בי\"ט ולא בחוה\"מ) (טור)</small>:","m":["(ו) ואנו אין נוהגין לומר - וכתבו האחרונים דמנהגנו לומר מקרא קודש בין ביו\"ט ובין בחוש\"מ ואין אומרים את יו\"ט אפילו ביו\"ט:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>כל הימים של חולו של מועד ושני ימים אחרונים של י\"ט <i data-commentator=\"Chok Yaakov\" data-order=\"6\"></i>קורין <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>ההלל בדילוג כמו בראש חודש:","m":["(ז) קורין ההלל בדילוג וכו' - מפני שביום שבעה של פסח נטבעו המצרים אמר הקב\"ה מעשי ידי טובעין בים ואתם אומרים שירה לפני וכיון שבז' אין אומרים אותו ע\"כ בחוה\"מ ג\"כ אין אומרים אותו שלא יהיה עדיף מיו\"ט אחרון:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>סימן הפרשיות של שמונת ימי הפסח <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"7\"></i>משך תורא קדש בכספא פסל במדברא שלח בוכרא וזה הסדר לא ישתנה כי אם כשחל פסח ביום ה' שביום שלישי שהוא שבת קורא ראה אתה אומר אלי שהוא פסל וביום א' ב' ג' קורין קדש בכספא במדברא:","m":["(ח) משך תורא - והם סימני ראשי פרשיות דהיינו יום ראשון משכו וקחו וגו' יום ב' שור או כשב יום ג' קדש לי כל בכור יום ד' אם כסף תלוה יום ה' פסל לך יום ו' במדברא דהיינו וידבר וגו' במדבר סיני ויעשו בני ישראל את הפסח ביום ז' פ' בשלח ביום ח' בוכרא כל הבכור אשר יולד וגו':","(ט) קורא וכו' - מפני שכתוב בו מעניני דשבת:","(י) קורין הרביעי - קאי על חול המועד ואין אומרים קדיש עד אחר שקרא הרביעי שנשלם מנין הקרואים משא\"כ בשבת ויו\"ט ויוה\"כ נשלם מנין הקרואים קודם שקורא מפטיר וע\"כ אומרים תיכף קדיש:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>בכל ימי חול המועד ושני ימים טובים אחרונים <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>קורים <i data-commentator=\"Chok Yaakov\" data-order=\"8\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><small> (הרביעי) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>בספר שני בקרבנו' המוספין שבפנח' ומתחיל והקרבתם עד סוף פיסקא:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>בליל <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>יום טוב <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"6\"></i>האחרון מקדשין על היין <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>ואין אומרים זמן: <small>הגה ואומרים בתפלה ובקידוש <i data-commentator=\"Chok Yaakov\" data-order=\"9\"></i>זמן חירותינו כמו בי\"ט ראשון (מהרי\"ל ומנהגים)</small>:","m":["(יא) בליל יו\"ט האחרון - בין בז' בין בח':","(יב) מקדשין על היין - ר\"ל בבהכ\"נ וכונתו דאף דבב' לילות הראשונים אין מקדשין בבהכ\"נ והטעם לפי שאין לך עני בישראל שאין לו ד' כוסות משא\"כ הכא לא שייך זה:","(יג) וא\"א זמן - דהיינו שהחיינו שאינו רגל בפני עצמו כמו שמיני עצרת של החג. מילה כשחל בשביעי של פסח או בשמיני אומרים יום ליבשה נהפכו מצולים קודם גאל ישראל [ואם חל בשבת אומרים קודם שירה חדשה משום שאז נוהגין לומר הפיוט של ברח דודי קודם גאל ישראל] משא\"כ בשאר יו\"ט דאין אומרים יום ליבשה מחמת מילה אא\"כ כשחלו בשבת [מ\"א בשם הלבוש] עוד כתב דאם חל יום ז' בשבת אומרים ביוצר הפיוטים של שבת חוה\"מ מפני שאז אומרים שיר השירים באותו יום והפיוטים של שבת חוה\"מ מיוסדים על שה\"ש ואם חל יום אחרון בשבת אומרים ביוצר הפיוטים של שבת חוה\"מ ובשמו\"ע מהפכין ואומרים הפיוט של יום ז':","(יד) ומפטירין היתה עלי - האמורה לענין תחית המתים. והטעם כי תחית המתים יהא בניסן וגוג ומגוג בתשרי ע\"כ מפטירין בניסן העצמות היבשות ובתשרי בוא גוג [טור]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>מפטירין ביום שביעי וידבר דוד וביום שמיני עוד היום בנוב לעמוד:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>שבת שחל בחול המועד ערבית שחרית ומנחה מתפלל כדרכו של שבת ואומר יעלה ויבא בעבוד' <i data-commentator=\"Eshel Avraham\" data-label=\"ג\" data-order=\"3\"></i>ובמוסף אומר סדר מוסף יום חול המועד אלא שמזכיר של שבת ואומר ותתן לנו את יום המנוח הזה ויום חג המצות הזה וכן אומר את מוספי יום המנוח הזה ויום חג המצות הזה וחותם מקדש השבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>וישראל והזמנים <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>ומפטירים <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>היתה עלי: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>ואין מזכירין בברכת ההפטרה לפסח לא באמצע <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"10\"></i>ולא <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>בחתימה ונוהגין לומר <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>שיר השירים בשבת של חול המועד ואם שבת בי\"ט האחרון אומרים אותו באותו שבת וכן הדין בסוכות עם קהלת ונוהגין לומר רות בשבועות (אבודרהם) <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>והעם נהגו <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"11\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"9\"></i>שלא לברך עליהם על מקרא מגילה ולא על מקרא כתובים</small>:","m":["(טו) ואין מזכירין וכו' - דבשבת שחל בחוה\"מ פסח אין הפטרה באה אלא בשביל שבת בלבד שהרי אין מפטירין בנביא בשאר ימי חוה\"מ לפיכך אומרים ברכת הפטרה כמו בשאר שבתות השנה:","(טז) ולא בחתימה - דהיינו שאינו חותם רק מקדש השבת וכתבו האחרונים דבשבת חוה\"מ סוכות מסיים מקדש השבת וישראל והזמנים וכן מזכיר של סוכות באמצע הברכה כמו ביו\"ט ראשון של סוכות והטעם שכל יום ויום מחוה\"מ סוכות הוא כמועד בפ\"ע משום דחלוקין בקרבנות המוספין:","(יז) ונוהגין לומר שה\"ש וכו' - מפני שמפורש בו ענין יציאת מצרים ובסוכות קהלת מפני שהם ימי שמחה וכתיב בקהלת ולשמחה מה זו עושה ורות בשבועות דאיתא בילקוט רות מה ענין רות אצל עצרת שנקראת בזמן מתן תורה ללמדך שלא ניתנה תורה אלא ע\"י יסורין ועוני וכו' ונהגו לקרותה ביום שני:","(יח) בשבת של חוה\"מ - מפני שהפיוטים של אותו שבת מיוסדים על שה\"ש וכנ\"ל:","(יט) והעם נהגו וכו' - וכן הסכים הט\"ז ומ\"א הסכים עם אותן הפוסקים המצריכין לברך על כולם חוץ מקהלת והגר\"א בביאורו כתב דאף על קהלת יש לברך. ולכן הנוהג לברך עכ\"פ כשכתובין על קלף בודאי אין למחות בידו. יו\"ט שחל בשבת אומרים במנחה ואני תפלתי וקורין בסדר השבוע:"]}],"491":[{"s":"<b>סדר הבדלה במוצאי יום טוב. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>במוצאי יום טוב בין במוצאי י\"ט לחול בין במוצאי יום טוב לחולו של מועד <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>מבדיל בתפלה כמו במוצאי שבת ומבדיל על הכוס כמו במוצאי שבת אלא שאינו מברך <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>לא על הנר <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ולא על הבשמים:","m":["(א) אלא שאינו וכו' - חסרון הניכר יש כאן וקודם לזה צ\"ל ומבדיל על הכוס כמו במו\"ש אלא שאינו וכו' [הגר\"א] וכן מצאתי בשו\"ע הראשון שהדפיס המחבר בחייו. מי שהתחיל לאכול במוצאי פסח מבע\"י עד הלילה ועדיין לא התפלל והבדיל מותר לאכול חמץ דכיון שחשכה הוי לילה לכל מילי אלא שחכמים אסרו במלאכה עד שיבדיל [מ\"א וש\"א] אמנם אם עדיין לא בירך בהמ\"ז בודאי אין לו לאכול חמץ דהרי יצטרך לומר יעלה ויבוא משום דאזלינן בתר התחלת הסעודה כדאיתא לעיל בסוף סימן קפ\"ח וא\"כ יהיה תרתי דסתרי:","(ב) לא על הנר - שאין מברכין על הנר אלא במו\"ש ובמוצאי יה\"כ שנאסר אור כל היום ועכשיו חוזר להתירו כמו שנתבאר בסימן רצ\"ח אבל ביו\"ט לא נאסר האור מעולם לצורך יו\"ט:","(ג) ולא על הבשמים - דענין הבשמים הוא כדי להשיב את הנפש שכואבת על הנשמה היתירה שניטלה ממנו אחר שבת וביו\"ט ליכא נשמה יתירה. וכתבו הפוסקים דה\"ה דביו\"ט שחל במו\"ש אין מברכין על הבשמים והטעם לפי שיש מאכלים טובים מיישבים דעתו כמו בשמים:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>יום טוב שחל להיות במוצאי שבת אומר באתה בחרתנו ותודיענו:","m":["(ד) אומר באתה בחרתנו ותודיענו - והוא דוגמת אתה חוננתנו שמזכירין במו\"ש בברכת אתה חונן וע\"כ דינו ג\"כ כאתה חוננתנו שאם טעה ולא אמרו אין מחזירין אותו שיכול לומר אח\"כ קידוש על הכוס ושם נזכר הבדלה ג\"כ ועיין לעיל בריש סימן רצ\"ד בבה\"ל ד\"ה ואם טעה:"]}],"492":[{"s":"<b>תענית שני וחמישי ושני אחר המועדים. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>יש נוהגים להתענות <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>שני וחמישי <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>ושני אחר הפסח <i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>וכן אחר חג הסוכות וממתינים עד שיעבור כל <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>חדש ניסן <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ותשרי ואז מתענים: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>מיד שני וחמישי ושני שאפשר להתענות (ד\"ע) ובאשכנז וצרפת נהגו להתענות ועושין אותו כמו <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i>תענית צבור לקרות ויחל (טור)</small>:","m":["(א) שני וחמישי וכו' - שחוששין שמא מתוך משתה ושמחה באו לידי עבירה כמו שמצינו באיוב שהביא קרבנות והתענית במקום קרבן אבל בעצרת דאינו אלא יום אחד אין חוששין:","(ב) עד שיעבור וכו' - דבניסן המנהג שאין מתענים בו כלל כדאיתא לעיל בסימן תכ\"ט ובתשרי לא משום דרובו הוא מועדות וע\"כ אין נכון לקבוע בו תענית בתחלה:","(ג) מיד בה\"ב - ר\"ל לאפוקי ממה שכתבו בשם מהרי\"ו שימתינו מלהתענות עד י\"ז חשוון דליתא ומברכין בבהכ\"נ בשבת הראשון שאחר ר\"ח למי שיתענה בה\"ב ואחר אותו שבת מתחילין להתענות הבה\"ב וצריך לקבל התענית במנחה שלפניהם אכן מי שענה אמן על אותו מי שבירך ודעתו להתענות אין צריך לקבל עוד במנחה שלפני יום התענית ומ\"מ אם אח\"כ נמלך שלא להתענות אינו מחוייב להתענות מחמת עניית אמן כ\"ז שלא קיבל עליו התענית בפירוש בפיו וכשיש מילה או חתונה באותו שבת שמברכין בה\"ב נוהגין לברכו במנחה משום מהיות טוב וגו':","(ד) שאפשר להתענות - ר\"ל כיון שהגיע הזמן שאפשר להתענות אין לאחר יותר:","(ה) להתענות - ואם אירע בהם ברית מילה או פדיון הבן או שאר סעודת מצוה מצוה לאכול וא\"צ התרה כי כל המתענה אדעתא דמנהגא מתענה ולא נהגו להתענות בהם כשיש סעודת מצוה ויכולים לומר סליחות אפילו אין בבהכ\"נ עשרה מתענים רק שלא יאמרו הסליחה של תענית צבור קבעו וכו' [בה\"ט] ובפמ\"ג כתב שידלג רק תיבת צבור. ומ\"מ הסליחה של אפפונו מים וכו' בודאי אין נכון לאומרה כל שאין צבור מתענין:","(ו) לקרות ויחל - היינו בשחרית ומנחה כל שיש בבהכ\"נ עשרה שמתענין ויתר דיני תענית בה\"ב יבואר לקמן בסימן תקס\"ו ס\"ב:"]}],"493":[{"s":"<b>דינים הנוהגים בימי העומר. ובו ד סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i><i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>נוהגים שלא <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>לישא אשה בין פסח לעצרת <i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>עד ל\"ג בעומר מפני שבאותו זמן <i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i>מתו תלמידי ר' עקיבא <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i>אבל <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>לארס ולקדש <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>שפיר דמי ונשואין נמי מי שקפץ וכנס אין עונשין אותו: <small>הגה מיהו מל\"ג בעומר ואילך <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>הכל <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>שרי (אבודרהם וב\"י ומנהגים)</small>:","m":["(א) שלא לישא אשה - ואין חילוק בין נשואין של מצוה כגון שאין לו בנים או יש לו כי כן פשט המנהג במדינתנו שלא לחלק ולהחזיר גרושה שרי שאינו כ\"כ שמחה [אחרונים]:","(ב) מפני שבאותו זמן וכו' - ר\"ל ואין ראוי להרבות בשמחה [טור]. ומ\"מ אם נזדמן לו איזה ענין שצריך לברך עליו שהחיינו יברך:","(ג) שפיר דמי - שמא יקדמנו אחר. ומותר לעשות ג\"כ סעודת אירוסין ועכשיו שאין מקדשין אלא בשעת נשואין מ\"מ מותר לעשות שידוכין ולעשות סעודה אבל לעשות ריקודין ומחולות נהגו איסור וכ\"ש בשאר ריקודין ומחולות של רשות בודאי יש ליזהר:","(ד) אין עונשין אותו - היינו דוקא בנשואין שעשה עכ\"פ מצוה אבל אם נסתפר בימי העומר היו נוהגין לקנסו ולהענישו:","(ה) הכל שרי - היינו לאותן הנוהגין לספר מל\"ג בעומר ואילך וכדלקמיה בס\"ב אבל לדידן שנוהגין איסור בתספורת וכדלקמיה בס\"ג אסור ג\"כ לישא דנשואין ותספורת דין אחד להם ולעומת זה יש קולא למנהגנו שיהא מותר לישא ולהסתפר עד ר\"ח אייר. ולענין ר\"ח גופא יבואר בס\"ג. וטעם לאלו שני המנהגים יבואר לקמיה. ואף להנוהגין איסור גם עד ר\"ח אייר מ\"מ אם חל ר\"ח בשבת כיון שיש כאן תוספת שמחה שבת ור\"ח יש להתיר להסתפר בע\"ש מפני כבוד השבת וגם לישא אשה בו ביום כיון שעיקר הסעודה יהיה בשבת ור\"ח:","(ו) עד ל\"ג לעומר - עד ועד בכלל והיינו עד ל\"ג ימים שלמים כל אחד לילו ויומו משא\"כ יום ל\"ד לא החמירו בו כ\"א בלילה בלבד אבל משיאור היום לאחר נץ החמה מותר דמקצת היום ככולו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>נוהגים שלא להסתפר עד ל\"ג לעומר שאומרים שאז פסקו מלמות <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ואין להסתפר עד יום ל\"ד בבוקר <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אלא אם כן חל יום ל\"ג ערב שבת שאז מסתפרים בו מפני כבוד השבת: <small>הגה ובמדינות אלו אין נוהגין כדבריו אלא מסתפרין ביום ל\"ג <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"5\"></i>ומרבים בו קצת <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>שמחה <i data-commentator=\"Chok Yaakov\" data-order=\"6\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ואין אומרים בו <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"5\"></i>תחנון (מהרי\"ל ומנהגים) ואין להסתפר עד ל\"ג בעצמו ולא מבערב (מהרי\"ל) מיהו אם חל ביום א' <i data-commentator=\"Chok Yaakov\" data-order=\"7\"></i>נוהגין להסתפר ביום ו' לכבוד <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>שבת (מהרי\"ל) <i data-commentator=\"Chok Yaakov\" data-order=\"8\"></i>מי שהוא <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>בעל <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"7\"></i>ברית או מל בנו <i data-commentator=\"Eshel Avraham\" data-label=\"ב\" data-order=\"2\"></i>מותר להסתפר בספירה לכבוד המילה (הגהות מנהגים)</small>:","m":["(ז) שאומרים שאז פסקו וכו' - ואף דגם ביום ל\"ד מתו דמשום זה החמירו גם כל ליל ל\"ד עד הנץ אפשר דעיקר ההפסקה היה ביום ל\"ג וביום ל\"ד מתו רק מעט [פמ\"ג]:","(ח) ביום ל\"ג - דס\"ל דביום ל\"ג פסקו לגמרי מלמות:","(ט) וא\"א בו תחנון - גם בערב של ל\"ב:","(י) עד ל\"ג בעצמו - דהיינו לאחר שתנץ החמה והטעם לדידהו גם כן משום דמקצת היום ככולו:","(יא) ולא מבערב - ויש מאחרונים שמקילין להסתפר מבערב [מי\"ט וא\"ר] וסיים א\"ר דמ\"מ לענין נשואין לא ראיתי מקילין כ\"א ביום ל\"ג בעומר בעצמו ולא בלילה שלפניו אכן כשחל ל\"ג בעומר בע\"ש והוא לו שעת הדחק לעשות ביום אפשר שיש להקל לו לעשות בלילה שלפניו:","(יב) בעל ברית - היינו הסנדק והמוהל ואבי הבן אף שאינו מוהלו בעצמו (ומ\"ש הרמ\"א או מל בנו היינו שיש לו בן שצריך למול אותו) אבל לא המוציא והמביא [אחרונים]:","(יג) להסתפר בספירה - היינו אפילו ביום שלפני המילה סמוך לערב קודם הליכה לבהכ\"נ. ואם חל המילה בשבת מותרים להסתפר בע\"ש אפילו קודם חצות [פמ\"ג]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>יש <i data-commentator=\"Chok Yaakov\" data-order=\"9\"></i>נוהגים להסתפר בראש חדש אייר וטעות הוא בידם: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>מיהו בהרבה <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"8\"></i>מקומות נוהגין להסתפר עד ר\"ח אייר <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ואותן לא יסתפרו מל\"ג בעומר ואילך אף ע\"פ שמותר להסתפר בל\"ג בעומר בעצמו ואותן מקומות שנוהגים להסתפר מל\"ג בעומר ואילך לא יסתפרו כלל אחר פסח עד ל\"ג בעומר ולא ינהגו בעיר אחת <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"10\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>מקצת מנהג זה ומקצת מנהג זה משום לא תתגודדו וכ\"ש <i data-commentator=\"Chok Yaakov\" data-order=\"11\"></i>שאין לנהוג היתר <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>בשתיהן (ד\"ע)</small>:","m":["(יד) יש נוהגים וכו' וטעות הוא בידם - אבאר בקצרה. דלכו\"ע נוהגין איסור ל\"ג ימים אך יש בזה מנהגים שונים [ויש לכל אחד טעם למנהגו כמבואר בבה\"ל] יש שבחרו אותן מיום ב' של פסח עד ל\"ג בעומר ומשם והלאה עד שבועות לא קבלו עלייהו שום איסור אמנם עד ל\"ג בעומר אין מתירין שום יום. ויש שניכו ממ\"ט ימי העומר ט\"ז ימים הראשונים דהיינו עד יום שני של ר\"ח אייר ומשם והלאה עד שבועות שהוא ל\"ג ימים אין מתירין שום יום (לבד מל\"ג בעומר עצמו התירוהו במקצתו ומשום דמקצת יום ככולו) ונמצא מי שאוחז החבל בשני ראשין דהיינו שמיקל בר\"ח אייר וגם מיקל מל\"ג והלאה טעות הוא בידו:","(טו) ואותן לא יסתפרו מל\"ג בעומר ואילך - ר\"ל עד שבועות ממש וכנ\"ל. והנה במדינתנו המנהג לישא ולהסתפר בג' ימי הגבלה ע\"כ מסיק המ\"א דצריך ליזהר שלא לישא ולהסתפר בהשני ימים של חודש אייר וגם בראשון של ימי הגבלה בבוקר דוקא דאמרינן מקצת היום ככולו וא\"כ עי\"ז יושלם ל\"ג ימים שאנו נוהגים אבילות עבורם. וכתב הח\"א שכן המנהג ג\"כ בק\"ק ווילנא שנוהגים איסור מיום א' דר\"ח אייר עד ג' סיון בבוקר מלבד בל\"ג בעומר נוהגין בו היתר ויש מקומות שנוהגין להקל רק בר\"ח אייר ובל\"ג בעומר ובר\"ח סיון עד שבועות. ובענינים אלו יתפוס כ\"א כפי מנהג מקומו:","(טז) מקצת מנהג זה וכו' - ר\"ל שמקצת בני אדם ינהגו כך ומקצת ינהגו כך:","(יז) היתר בשתיהן - דהיינו שינהג היתר עד ר\"ח אייר כסברא אחרונה וגם ינהג היתר מל\"ג בעומר ואילך עד עצרת כסברא ראשונה כיון ששתי קולות אלו סותרות זו לזו וכנ\"ל אבל יכול לתפוס חומרי המנהגים דהיינו שינהג איסור מפסח עד ערב שבועות או עד יום א' של הגבלה חוץ מל\"ג בעומר ואף שנוהג ב' חומרות הסותרות זו לזו אינו ככסיל ההולך בחושך כיון שעושה כן רק מחמת ספק שאינו יודע איזה מנהג הוא העיקר ומ\"מ א\"צ לעשות כן אלא יכול לתפוס איזה מנהג שירצה ואין לו לחוש שמא מנהג המקום ההוא אינו כן דכיון שהוא רק מנהג בעלמא אין להחמיר בספיקא אבל אם ידוע לו מנהג המקום אין לו לשנות בין להקל ובין להחמיר [אחרונים]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"12\"></i>נהגו <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i>הנשים <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>שלא לעשות מלאכה מפסח ועד עצרת משקיעת החמה ואילך:","m":["(יח) הנשים - וה\"ה אנשים:","(יט) משקיעת החמה ואילך - הטעם שנקברו אחר שקיעת החמה והיו העם בטלים ממלאכה ויש עוד טעם בטור לפי שאז זמן ספירת העומר ובעומר כתיב שבע שבתות מלשון שבות דהיינו שבזמן הספירה יש לשבות ממלאכה ולפי טעם זה אחר שספר מותר תיכף במלאכה:"]}],"494":[{"s":"<b>סדר תפלת חג השבועות. ובו ג סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"1\"></i>ביום חמשים לספירת העומר <i data-commentator=\"Chok Yaakov\" data-order=\"2\"></i>הוא חג <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>שבועות וסדר התפלה כמו ביום טוב של פסח אלא שאומרים את יום חג השבועות הזה זמן מתן תורתינו <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>וגומרים ההלל <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>ומוציאין <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>שני ספרים <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>וקורין <i data-commentator=\"Chok Yaakov\" data-order=\"3\"></i>בראשון <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>חמשה <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"4\"></i>מבחודש <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>השלישי עד סוף הסדר ומפטיר קורא בשני וביום הבכורים <i data-commentator=\"Chok Yaakov\" data-order=\"5\"></i>ומפטיר <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>במרכבה דיחזקאל ומסיים בפסוק ותשאני רוח:","m":["{א} ביום נ' לספירת העומר וכו' - ומאחרין להתפלל ערבית בכניסת שבועות בצאת הכוכבים כדי שיהיו ימי הספירה מ\"ט יום תמימות. איתא בזוהר שחסידים הראשונים היו נעורים כל הלילה ועוסקים בתורה וכבר נהגו רוב הלומדים לעשות כן ואיתא בשו\"ע האר\"י ז\"ל דע שכל מי שבלילה לא ישן כלל ועיקר והיה עוסק בתורה מובטח לו שישלים שנתו ולא יארע לו שום נזק. והטעם כתב מ\"א ע\"פ פשוטו שישראל היו ישנים כל הלילה והוצרך הקב\"ה להעיר אותם לקבל התורה [כדאיתא במדרש] לכך אנו צריכין לתקן זה. וצריכין ליזהר אותם הנעורים כל הלילה שלא לברך על נטילת ידים בבוקר רק אחר שעשה צרכיו קודם התפלה ואז מברך על נט\"י ואשר יצר וכמבואר לעיל בסימן ד' סק\"ל ע\"ש ולענין ברכה על טלית קטן יש דעות בין הפוסקים וע\"כ יראה לכוין לפטור אותה בברכה שמברך על טלית גדול כמבואר לעיל סימן ח' במ\"ב ס\"ק מ\"ב ולענין ברכת התורה עיין לעיל בסימן מ\"ז במ\"ב סקכ\"ח ולענין ברכת אלהי נשמה וברכת המעביר שנה עיין בסימן מ\"ו במ\"ב סקכ\"ד. נכון ליזהר ע\"פ קבלה מלשמש בליל שבועות אם לא בליל טבילה ועיין מה שכתבנו לעיל בסימן ר\"מ במ\"ב סק\"ז ובה\"ל שם:","{ב} וקורין בראשון וכו' - והמנהג לומר אקדמות והסכימו כמה אחרונים לומר זה קודם שמתחיל הכהן לברך על התורה וכן המנהג כהיום בכמה קהלות אכן יציב פתגם שאומרים ביום שני בעת קריאת הפטרה נתפשט באיזה מקומות לאמרו אחר פסוק ראשון של הפטרה:","{ג} מבחודש השלישי - וקורין הדברות בטעם העליון ועיין בבה\"ל שביארתי בארוכה:","{ד} במרכבה דיחזקאל - ונוהגין במקצת מקומות שגדול וחכם קורא זאת ההפטרה וסמך לדבר ולא במעשה מרכבה אא\"כ היה חכם ומבין מדעתו וגם יש נוהגין שכל מי שקורא אותה עם המפטיר בלחש אומר אותה ג\"כ מעומד מפני כבודה:","{ה} כל הבכור - ואם חל בשבת שצריכין לקרות יותר דהא בשבת צריך ז' קרואים מתחילין עשר תעשר:","{ו} במוצאי - מפני כשחל עצרת בשבת היה יום זביחת הקרבנות אחר השבת והוא כעין יו\"ט [מ\"א] ולפי טעם זה באסרו חג שאחר סוכות מותר להתענות אכן מדברי הגר\"א משמע דגם שם אין להתענות וכ\"מ בב\"י:","{ז} וא\"א תחנון - וגם אין מתענים בם:","{ח} מתחלת ר\"ח סיון - דמיד בשני בסיון א\"ל משה לקדשם לתורה כדכתיב אם שמוע תשמעו בקולי ושמרתם את בריתי וגו' ואח\"כ מתחיל ג' ימי הגבלה:","{ט} בשבועות - היינו בין ששוטחן בעיו\"ט או ביו\"ט גופא ואפילו אם אותן עשבים אין ראויין למאכל בהמה כיון שחשב עליהן מבעוד יום שרי לטלטלן כמש\"כ סימן ש\"ח ס\"כ ובפרט אם הם עשבים המריחין אכן אם חל שבועות ביום א' אין לשוטחן בשבת כיון שכונתו לצורך יו\"ט ואין שבת מכין ליו\"ט אלא ישטחם ביו\"ט גופא או בע\"ש:","{י} זכר לשמחת מתן תורה - שהיו שם עשבים סביב הר סיני כדכתיב הצאן והבקר אל ירעו וגו'. כתבו האחרונים במקום שנוהגין לחלק עשבים המריחים בבהכ\"נ לא יחלקו מברוך שאמר עד אחר תפלת י\"ח כדי שיוכל לברך עליהן דבינתים אסור להפסיק. נוהגין להעמיד אילנות בבהכ\"נ ובבתים זכר שבעצרת נידונו על פירות האילן [מ\"א] והגר\"א ביטל מנהג זה משום שעכשיו הוא חק העמים להעמיד אילנות בחג שלהם:","{יא} בכמה מקומות לאכול - ואם מותר להתענות תענית חלום בשבועות עיין לקמן בסימן תר\"ד במ\"א ובמה שכתבנו שם במ\"ב:","{יב} מאכלי חלב - עיין מ\"א ואני שמעתי עוד בשם גדול אחד שאמר טעם נכון לזה כי בעת שעמדו על הר סיני וקבלו התורה [כי בעשרת הדברות נתגלה להם עי\"ז כל חלקי התורה כמו שכתב רב סעדיה גאון שבעשרת הדברות כלולה כל התורה] וירדו מן ההר לביתם לא מצאו מה לאכול תיכף כ\"א מאכלי חלב כי לבשר צריך הכנה רבה לשחוט בסכין בדוק כאשר צוה ה' ולנקר חוטי החלב והדם ולהדיח ולמלוח ולבשל בכלים חדשים כי הכלים שהיו להם מקודם שבישלו בהם באותו מעל\"ע נאסרו להם ע\"כ בחרו להם לפי שעה מאכלי חלב ואנו עושין זכר לזה:","{יג} ביום ראשון וכו' - גם נוהגין בקצת מקומות לאכול דבש וחלב מפני התורה שנמשלה לדבש וחלב כמש\"כ דבש וחלב תחת לשונך וגו':","{יד} כמו השני תבשילין וכו' כן אוכלים וכו' - ר\"ל כשם שבפסח עושין זכר לקרבן כן אנו צריכין לעשות בשבועות זכר לשתי הלחם שהיו מביאין וע\"כ אוכלים מאכלי חלב ואח\"כ מאכל בשר וצריכין להביא עמהם שתי לחמים דאסור לאכול בשר וחלב מלחם אחד ויש בזה זכרון לשתי הלחם:","{טו} ב' לחם וכו' - ולכן נהגו לאפות לחם אחד עם חמאה דאז בודאי יצטרך להביא לחם אחר לאכול עם בשר ויזהר אז להסיק התנור יפה בין לחם ללחם וגם צריך מרדה חדשה דלא כמקצת נשים שמהפכין אותה על צד השני דהא בלוע מעבר אל עבר משמנונית:","{טז} על השלחן - ויזהר ליקח מפה אחרת כשרוצה לאכול בשר. וא\"צ להפסיק בבהמ\"ז אם אינו אוכל גבינה קשה אלא יקנח פיו יפה וידיח כדאיתא ביו\"ד סי' פ\"ט:","{יז} זכרון לב' הלחם - וא\"כ יהיו של חטין דוגמת שתי הלחם. כתב הפמ\"ג יש ליזהר בענין מאכלי בשר וחלב בכל מה שנזהרין בכל השנה המבואר ביו\"ד סי' פ\"ח ופ\"ט ושלא לצאת שכרם בהפסדם. עוד כתב בנוסח ברכת הפטרה על התורה ועל העבודה וכו' את יום חג השבועות הזה אבל אין מזכירין לומר מקרא קודש וכו'. ומזכירין נשמות ואומרים אב הרחמים ביום שני ובכל מקום שקורין כל הבכור מזכירין נשמות שיש בו מתנת יד ונודרים צדקה. כשחל שבועות ביום וי\"ו זיי\"ן אין אומרים פרקים וכשחל שבועות במו\"ש אומרים פרקים במנחה בשבת:  "]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ביום השני קורין בפרשת <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>כל <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>הבכור עד סוף סידרא ומפטיר קורא כמו אתמול ומפטיר בחבקוק מן <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>וה' בהיכל קדשו עד למנצח בנגינותי:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i><i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>אסור להתענות <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>במוצאי חג השבועות: <small>הגה <i data-commentator=\"Chok Yaakov\" data-order=\"6\"></i>ואין אומרים <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>תחנון <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>מתחילת ראש חודש סיון עד ח' בו דהיינו אחר <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>אסרו חג (הגהות מיימוני הלכות ברכות ומנהגים) <i data-commentator=\"Chok Yaakov\" data-order=\"7\"></i>ונוהגין <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>לשטוח <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"7\"></i>עשבים בשבועות בבית הכנסת והבתים זכר לשמחת מתן תורה ונוהגין <i data-commentator=\"Chok Yaakov\" data-order=\"8\"></i>בכל מקום לאכול <i data-commentator=\"Chok Yaakov\" data-order=\"9\"></i>מאכלי <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Chok Yaakov\" data-order=\"10\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>חלב ביום ראשון של שבועות ונראה לי הטעם שהוא <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>כמו השני תבשילין שלוקחין בליל פסח זכר לפסח וזכר לחגיגה כן אוכלים מאכל חלב <i data-commentator=\"Chok Yaakov\" data-order=\"11\"></i>ואח\"כ מאכל בשר <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>וצריכין להביא עמהם ב' לחם על השלחן שהוא במקום המזבח ויש בזה <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>זכרון <i data-commentator=\"Chok Yaakov\" data-order=\"12\"></i>לשני הלחם שהיו מקריבין ביום הבכורים</small>:","m":[]}],"495":[{"s":"<b>איזה מלאכות אסורים בי\"ט. ובו ד סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>כל מלאכה האסורה בשבת <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>אסורה ביום טוב <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>חוץ ממלאכת אוכל נפש <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>וחוץ מהוצאה והבערה <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>וכן מכשירי אוכל נפש שלא הי' אפשר לעשותם מאתמול: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>ויש מחמירין אפילו באוכל נפש עצמו כל <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>שאינו מפיג טעם כלל אם עשאו מערב י\"ט (א\"ז מהרי\"ל) מיהו אם לא עשאו מערב י\"ט ויש בו צורך י\"ט מותר לעשותו <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>ע\"י <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>שינוי (סמ\"ג ור\"ן)</small>:","m":["{א} האסורה בשבת - בין שאיסורה מן התורה ובין שאיסורה משום שבות וכן כל דבר שאסור לעשותו בעצמו אסור לומר גם לעכו\"ם לעשותו כמו בשבת:","{ב} חוץ ממלאכת אוכל נפש - כדכתיב בקרא אך אשר יאכל לכל נפש הוא לבדו יעשה לכם:","{ג} וחוץ מהוצאה והבערה - ופרטי דיניהם יתבארו לקמן סימן תקי\"א ותקי\"ח:","{ד} וכן מכשירי אוכל נפש וכו' - ופרטי דין זה עיין לקמן סימן תק\"ח ותק\"ט:","{ה} שלא היה אפשר - דנתקלקל ביו\"ט או שלא הספיק לו השעה ומשמע דבאוכל נפש גופיה מותר לדעת המחבר אפילו באפשר לעשותו מאתמול ומיהו בדבר שדרך לעשותו בפעם אחת לימים רבים גם להמחבר אסור בדבר שטוב מאתמול ולא יפיג טעמו וכדלקמן סימן תק\"י ס\"ג ע\"ש וע\"י שינוי משמע מהגר\"א דשרי:","{ו} מאתמול - אבל אם אפשר לעשותו מאתמול הרי הוא כשאר מלאכות ואסור מן התורה:","{ז} ויש מחמירין וכו' - מדרבנן כדי שלא יעבור עליו כל היום במלאכות וימנע משמחת יו\"ט:","{ח} כל שאינו מפיג - דלישה ואפיה ושחיטה ובישול אם עשאן בעיו\"ט יש בהם חסרון טעם שאין לחם שנילוש ונאפה היום כלחם שנילוש ונאפה מאתמול ולא תבשיל שנתבשל היום כתבשיל שנתבשל מאתמול ולא בשר שנשחט היום כבשר שנשחט מאתמול ולהכי לא גזרו בהם אבל דבר שאין בו קלקול טעם והפסד אם נעשה מאתמול ל\"ל לעשותן ביו\"ט וכתבו האחרונים דנקטינן למעשה כסברא זו. וכתבו עוד דלפי דעה זו אסור ללוש ביו\"ט וורימזלי\"ן (שקורין לאקשי\"ן) שאפשר הנילושים מבע\"י טובים ביותר וכן אסור לבשל פירות יבשים ביו\"ט שהוא ידוע שהמבושלים מעיו\"ט טובים הם יותר לאכילה אח\"כ ביו\"ט מיהו אם לא היה לו שהות מקודם לבשל וכש\"כ כשלא היה לו הפירות מקודם בודאי מותר לבשלם ביו\"ט וכן לענין לישה הנ\"ל:","{ט} טעם כלל - משמע דאם מפיג טעם אפילו במקצת שרי לכו\"ע ובמהרי\"ל כתוב שאסור לדוך שקדים ביו\"ט להוציא מהן חלב מדהיה אפשר ליה לדוך מאתמול אע\"פ שמפיג טעם קצת וכתבו האחרונים דמשו\"ה החמיר בזה דדמי קצת לסחיטת פירות דאסור. ומ\"מ ע\"י שינוי נראה דיש להתיר:","{י} מותר לעשותו ע\"י שינוי - ואם לא עשאו מעיו\"ט מפני איזה אונס מותר אפילו בלי שינוי. וכתב המ\"א דאפילו לכתחלה מותר להמתין לעשותו ע\"י שינוי ובספר בגדי ישע מפקפק ע\"ז אכן אם אין לו שהות קודם יו\"ט בודאי יש לסמוך ע\"ז:","{יא} קצירה וכו' - וה\"ה דישה והרקדה וכה\"ג:","{יב} וסחיטה - ר\"ל לסחוט הפירות להוציא מהן שמנן ויינן לאכילה ביו\"ט:","{יג} אסרום חכמים - דמן התורה כל מלאכה שהוא באוכל נפש מותר אלא חכמים אסרו דברים שהם עבודה רבה כגון הני שהאדם רגיל לקצור שדהו ולבצור כרמו כאחד ולדרוך כל ענביו כאחד ולטחון הרבה בפ\"א וא\"כ יטרד כל היום בעבודתו וימנע משמחת יו\"ט ולכן אסרו חכמים ואפילו ע\"י שינוי אסור והניחו בהיתרן רק דברים שמסתמא הן רק לצורך אכילת יו\"ט והרבה פוסקים חולקין וסוברין דמלאכת עבודה הנ\"ל אסור מן התורה אפילו באוכל נפש ולא התירה התורה באוכל נפש אלא מה שהוא דרך לעשות ליום זה כגון מלישה ואפיה ואילך וכה\"ג מלאכות שהם לצורך אכילה ביו\"ט ופרטי דינים אלו יתבארו בסימנים הבאים כאו\"א במקומו:","{יד} אין מוציאין משא וכו' - לפי דעת הג\"ה לעיל סימן רמ\"ו ס\"ג דאין אדם מצווה על שביתת בהמתו צ\"ל דהכא אינו אלא איסורא דרבנן בעלמא שלא יעשה כדרך שהוא עושה בחול עם בהמתו ואפילו לצורך יו\"ט ואפילו ברשות אחד ממקום למקום נמי אסור ולפ\"ז לשון אין מוציאין לאו דוקא ולעיל בסימן רמ\"ו הבאנו דעת החולקים דאדם מצווה על שביתת בהמתו ביו\"ט כמו בשבת וכ\"ש כשהוא מחמר אחר בהמתו ולדעה זו אתי שפיר כפשוטו ואיסורא דאורייתא קאמר המחבר. ודע אם נאמר דיש שביתת בהמה ביו\"ט שייך בזה כל הדינים הנאמרים בענין זה לעיל בהלכות שבת סימן ש\"ה:","{טו} מוקצה אע\"פ שהוא מותר וכו' - פי' דלעיל בסימן ש\"י מתבאר דיש כמה מיני מוקצה המותרין בשבת כמו מוקצה מחמת שעומד לסחורה או בשהכניסו לאוצר ואין דעתו להסתפק ממנו עד אחר זמן או מוקצה מחמת מיאוס ועוד כמה גווני אך כ\"ז הקילו דוקא בשבת דחמיר לאינשי ולא חיישינן אם נקל לו לטלטל דבר מוקצה יבוא להקל בשאר איסורי שבת אבל ביו\"ט דקילי ליה שהרי הרבה מלאכות מותרים לו לצורך אוכל נפש ואם נקל לו במוקצה יבוא להקל גם בשאר איסורי יו\"ט ולפיכך אסרו לו חכמים לטלטל ולאכלו ולפי סברא זו בהמה העומדת לחלבה ותרנגולת לביצתה ושור של חרישה אסור לשחטן ביו\"ט עד שיכין אותם לכך מעיו\"ט וכן כל כה\"ג צריך הכנה מבע\"י ודבר שהוא מוקצה מחמת נולד פשיטא דאסור לדעת המחבר ביו\"ט:","{טז} ויש מתירין וכו' - דלא חמיר משבת וכתב מ\"א דכן הוא ג\"כ דעת הרש\"ל וכן פסק גם הפר\"ח:","{יז} לדבריהם וכו' - ואף דיש פוסקים שמתירין אף במוקצה דנולד הרמ\"א לא רצה לתפוס כדעתם בזה אלא כאותן פוסקים דמחמירין עכ\"פ במוקצה דנולד וכתבו האחרונים דאף שבשבת נקטינן לעיקר להתיר אפילו במוקצה דנולד דלא כבעלי סברא זו מ\"מ ביו\"ט אין להתיר עכ\"פ במוקצה דנולד ולפ\"ז אין לטלטל עצמות שנתפרקו מן הבשר ביו\"ט אע\"פ שהן ראויין לכלבים מפני שאתמול כשהיו מחוברין לבשר היו ראויין גם לאדם והוי נולד:","{יח} וכל מוקצה וכו' - קאי לסברא הראשונה דמוקצה אסור דלהמתירין מוקצה א\"צ אמירה אלא בגרוגרות וצמוקים משום דמסתמא דחינהו בידים כשהעלן לגג ליבשן ואפילו בשבת אסור וכדלעיל בסימן ש\"י ס\"ב:","{יט} שאינו בע\"ח - דבב\"ח לא מהני בשיאמר מכאן אני נוטל אלא צריך לפרט זה וזה אני נוטל וכמבואר לקמן סי' תצ\"ז ס\"י:","{כ} כגון אוצר וכו' - ר\"ל ודעתו היה מתחלה רק להסתפק ממנו לאחר זמן וה\"ה בפירות העומדים לסחורה או במוקצה של גרוגרות וצמוקים שלא נתייבשו לגמרי:","{כא} סגי כשיאמר וכו' - דאותן שיקח למחר הרי הם כמו שהוברר למפרע דלהם כוון בהכנתו דבמלתא דרבנן קי\"ל דיש ברירה:","{כב} וא\"צ שירשום וכו' - ודע דיש כמה פוסקים דפליגי ע\"ז ודעתם דלא סגי בשיאמר מכאן וכו' אלא צריך שירשום בסימן המקום שבדעתו לאכול וסברתם דכיון שהם מוקצים מחמת מעשה שעשה בהם להקצותם כגון גרוגרות וצמוקים שהעלם לגג ליבשן או אפילו פירות שהכניסם לאוצר הרי הקצם בידים למכירה לא סגי בהכנה כל דהו להוציאם ממוקצה עד שיברר יפה הפירות שבדעתו לאוכלם ויתן בהם סימן ולהלכה יש להחמיר כסברא האחרונה עכ\"פ לענין גרוגרות וצימוקים שהעלן לגג ובפירות שמכניסם לאוצר אפשר דיש לסמוך אסברא קמא ועיין בה\"ל:","{כג} ומותר להכין וכו' - ר\"ל דבכגון זה של פירות ואוצר שא\"צ לעשות מעשה ובאמירה בעלמא הוי הכנה מותר להכין אפילו ביו\"ט גופיה מיום אחד לחבירו דממ\"נ אם יום ב' קודש הרי היום חול ומותר להכין ואם היום קודש ומחר חול הרי א\"צ הכנה כלל ונמצא שאינו מתקן שום דבר בהכנתו דליאסר עליו והיכי אסרינן הכנה מיו\"ט לחבירו היכא שהוא עושה מעשה דחיישינן שמא מחר חול ונמצא שעשה מעשה ביו\"ט לצורך חול וכההיא דסימן תק\"ג עי\"ש [וכן במוקצה דבע\"ח כגון תרנגולת העומדת לגדל ביצים לא יכול להזמין מיו\"ט לחבירו אא\"כ זימן מעיו\"ט] ולפ\"ז לפי מה שכתבנו להחמיר במוקצה דאקצייה בידים כגון גרוגרות וצמוקים שצריך לרשום אם שכח לרשום בעיו\"ט ונזכר ביו\"ט אסור לעשות שום סימן להכין פירות ליו\"ט שני דשמא מחר חול ונמצא שעשה סימן ביו\"ט לצורך חול:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>קצירה <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"4\"></i>טחינה ובצירה וסחיטה וצידה אע\"פ שהם מלאכת אוכל נפש <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>אסרום חכמים:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>אין מוציאין <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>משא על הבהמה ביום טוב:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>מוקצה אע\"פ שמותר בשבת <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>החמירו בו ביום טוב <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>ואסרוהו: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>ויש מתירין מוקצה אפי' ביום טוב (טור בשם פוסקים) אבל <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>נולד אסור <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>לדבריהם אפי' בשבת וכל מוקצה שאינו בעלי חיים כגון <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>אוצר של פירות ועצים <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>סגי כשיאמר מכאן אני <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>נוטל <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>ואינו צריך <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>שירשום (רבינו ירוחם נ\"ד ח\"ג) <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i><i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>ומותר <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>להכין מיו\"ט ראשון לשני בב' ימים של גליות (כל בו) ועיין לעיל סי' ש\"י כל דיני מוקצה</small>:","m":[]}],"496":[{"s":"<b>דיני יום טוב שני של גליות. ובו ג סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>בגליות שעושין שני ימים טובים מספק כל מה שאסור בראשון אסור בשני <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ומנדין למי שמזלזל בו ואם הוא צורבא דרבנן אין מחמירין לנדותו אלא <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>מלקין אותו:","m":["{א} והיו מנדין וכו' - ואע\"ג דעכשיו בקיאין אנו בקביעות החודש לפי החשבונות שבידינו מ\"מ חששו חכמים שמא מרוב הצרות והטלטולים בגלותנו ישתכח החשבון ויבואו לעשות חסר מלא ומלא חסר ויאכלו חמץ בפסח וע\"כ הניחו הדבר בחו\"ל כמו שהיו בימים הראשונים:","{ב} למי שמזלזל בו - במזיד ואפילו זלזל בו בדבר שהוא משום שבות או בתחומים דרבנן נמי מנדין אותו וכתבו האחרונים דאפילו חיללו ע\"י עכו\"ם נמי הוא בנידוי דכל מה שאסור בראשון אסור בשני ונתבאר בפוסקים דיו\"ט שני חמור בזה מיו\"ט ראשון דביו\"ט ראשון אין מנדין רק בעבר על איסור דאורייתא אבל על שבות דרבנן אין מנדין רק מלקין אותו מכת מרדות משא\"כ ביו\"ט שני והטעם משום דיו\"ט שני כל עיקרו אינו אלא מדרבנן א\"כ כי עבר בו על איזה דבר שהוא הרי הוא כעוקר את כולו ולהכי החמירו עליו משא\"כ ביו\"ט ראשון שאינו עוקרו במה שעבר על שבות שהרי באיסור דאורייתא שבו לא עקרו ויש פוסקים חולקים בזה ולדידהו אין חילוק כלל בין יו\"ט א' לשני והדבר תלוי רק לפי ראות עיני הדיינים במה שרואין לפי הענין אם להקל עליו במלקות או להחמיר עליו בנידוי רק שהרשות בידם אפילו לנדותו. כתבו האחרונים דאם עשה הדבר ע\"פ הוראת חכם שטעה אין לנדותו שהרי שוגג הוא:","{ג} אלא היו מלקין אותו - ושיעור מכת מרדות יש בזה דיעות בין הפוסקים עיין במ\"א וא\"ר:","{ד} אלא לענין מת - משום כבודו ויתבאר לקמן בסימן תקכ\"ו. ולענין כיבוי דליקה עיין פר\"ח ויתבאר לקמן בסימן תקי\"ד ס\"א:","{ה} וכן לכחול את העין - מיירי שחש בעינו קצת וכל גופו בריא ואינו מרגיש מיחוש בגופו מחמת העין דבכגון זה בשבת ויו\"ט אסור לעשות שום רפואה ע\"י עצמו אפילו בשינוי וכמו שנתבאר לעיל סימן שכ\"ח סי\"ז במ\"ב ס\"ק נ\"ב והכא ביו\"ט שני שרי לכתחלה ואפילו בלי שינוי:","{ו} או שאר חולי - וג\"כ בשאינו כולל כל הגוף:","{ז} בשני מותר וכו' - שמיני הנאת הגוף לא החמירו בו ביו\"ט שני בשבות דרבנן:","{ח} אסור לישראל וכו' - ואפילו חש בכל גופו נמי אסור ע\"י עצמו. כתב באו\"ה אדם הנופל או הנגוף ונצרר דם במקום נפילתו או נגיפתו אין חשיב חולי הפנימי ומאחר שאין מצטער כ\"כ ויכול להמתין למחר בלי סכנה נראה דאסור להקיז דם שקורין קעפפ\"ן [ובלשוננו באנקע\"ס] אפילו ביו\"ט שני של גליות ואפילו ע\"י עכו\"ם עכ\"ל:","{ט} אסורים לעשות מלאכה - דנותנין עליו חומרי מקום שהלך לשם ואפילו בצנעא אסור וכמו שנתבאר לעיל בסימן תס\"ח ס\"ד ומ\"מ אם עשה מלאכה אין מנדין אותו:","{י} בישוב - לאפוקי אם יצא מן הישוב ובא לו למדבר אין צריך להתנהג כמנהג חו\"ל כיון שאין דעתו להשתקע שם. כתבו הפוסקים דישוב נקרא ישוב של ישראל דוקא וכל זמן שלא הגיע לעיר של ישראל א\"צ להתנהג כחומרי אותה המדינה. וכתבו עוד דתוך התחום הוי כתוך העיר וצריך להתנהג כחומרי אותו מקום:","{יא} אבל אם הגיע לישוב - אפילו לישוב נכרים דכיון שאין דעתו לחזור נמשך אחרי המדינה שבא לשם מכיון שהגיע לישוב של ב\"א ויש מי שמקיל גם בזה כמו בדעתו לחזור ובעי שיגיע דוקא לישוב של ישראל:","{יב} בין במדבר - ר\"ל אחר שנכנס לישוב אפילו יצא אח\"כ למדבר לא נפקע חיובו:","{יג} וכל חוץ לתחום וכו' - ר\"ל בין בדעתו לחזור בין באין דעתו לחזור כל שלא הגיע לתחום הישוב מקרי לא הגיע לישוב עדיין. כתבו הפוסקים בני א\"י שבאו לח\"ל ודעתו לחזור וחל יו\"ט ב' בע\"ש א\"צ לערב עירובי תבשילין מפני שהוא דבר שבצנעא ולכן אין צריך לנהוג בזה כחומרי המקום שהלך לשם כיון שדעתו לחזור ומטעם זה צריכים הם להתפלל תפלת י\"ח בלחש ביו\"ט שני. וכן להניח תפילין בצנעא כיון שדעתו לחזור נותנין עליהם חומרי המקום שיצאו משם כמ\"ש בסי' תס\"ח אבל צריכים ללבוש מלבושי יו\"ט מפני שהוא דבר של פרהסיא. ובן חו\"ל שבא לא\"י אם דעתו לחזור למקומו צריך לעשות שני ימים יו\"ט ומ\"מ תפלת יו\"ט צריך להתפלל בביתו בצנעא אכן אם דעתו שלא לחזור למקומו לעולם יתנהג כבני א\"י וכמו שמבואר לעיל בסימן תס\"ח עי\"ש במ\"ב ובה\"ל. כתבו האחרונים דמי שעוקר דירתו עם אשתו ובניו ממקום למקום לישא וליתן ולהרויח אע\"פ שבשעת עקירתו היה דעתו לחזור למקומו כמי שאין דעתו לחזור דמי דסתמא דמילתא כיון דעקרינהו לאינשי ביתיה כל שמוצא פרנסתו מרווחת באותו מקום שהלך לשם אינו זז משם. וכתבו עוד דמי שאין דעתו לחזור אע\"פ שאשתו נשארה במקומה הראשון אפ\"ה אין דעתו לחזור מיקרי:"]},{"s":"אין חילוק בין ראשון לשני <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אלא <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>לענין מת <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>וכן <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>לכחול את העין: <small>הגה או שאר חולי שאין בו סכנה (ר\"ן פרק אין צדין) </small> אע\"פ שאסור בראשון אלא על ידי <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>עכו\"ם אם אין בו סכנה בשני מותר אפי' על ידי ישראל חוץ מי\"ט שני של ראש השנה דשני ימים קדושה אחת אריכתא הן: <small>הגה ודוקא שבות דרבנן דומיא דמכחיל עינא אבל אב מלאכה אסור לישראל לעשותו אפילו בי\"ט שני (ר\"ן פרק אין צדין והמגיד פרק ראשון)</small>:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i><i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>בני ארץ ישראל שבאו לחוצה לארץ אסורים לעשות מלאכה ביו\"ט שני <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>ביישוב <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>אפילו דעתו לחזור וכל זמן שלא הגיעו ליישוב אפילו אין דעתו לחזור מותר לפי שעדיין לא הוקבע להיות כמותן <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>אבל אם הגיע <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>ליישוב ואין דעתו לחזור נעשה כמותן ואסור בין במדבר בין ביישוב וכל <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>חוץ <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"5\"></i>לתחום אין נותנין עליו חומרי מקום שהלכו לשם:","m":[]}],"497":[{"s":"<b>דיני הכנה ביום טוב. ובו יז סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אין צדין דגים מן הביברים: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>אפי' במקום שאינם מחוסרים צידה לפי שהביבר רחב הרבה <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>והדגים <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>נשמטים אילך ואילך: (המגיד פ\"ב)</small>","m":["{א} מן הביברים - היינו בריכות של מים מוקפים מד' רוחות. ובמן הנהר לא איצטריך ליה לאשמועינן דבודאי אסור דכולהו איתנהו ביה צידה גמורה דאסור כקצירה וטחינה ושארי מלאכות וכדלעיל סימן תצ\"ה ס\"ב וגם מוקצה:","{ב} אפילו במקום שאינם מחוסרים צידה - ר\"ל שהיה הביבר קטן שא\"צ לומר הבא מצודה ונצודנו ובחיה ועוף כה\"ג חשיב אין מחוסר צידה כדלקמן בס\"ז גבי דגים הואיל והם מכוסים מן העין והביבר רחב לעולם הם נשמטים לחורין ולסדקין ולכן לא חשיבי כניצודים הואיל ויש עכ\"פ טורח לתפסם וכתב המ\"א דאם המים צלולים ורואה הדגים מותר אם אין מחוסר צידה שהביבר קטן ויש מאחרונים שסוברין דעכ\"פ מטעם מוקצה אסור לצודן:","{ג} והדגים נשמטים וכו' - ולענין אם נתנם מבע\"י בתוך התיבה יבואר לקמיה בס\"ה:","{ד} דגים ועופות וכו' שהם מוקצה - מדתלה הטעם במוקצה משמע דה\"ה בהמה כגון בהמה מדברית המבואר לקמן בסימן תצ\"ח ס\"ג או כגון אווז ותרנגולת העומדת לגדל ביצים אף דלא שייך בהן צידה כיון דהם מוקצה אסור להשקותן וליתן לפניהם מזונות שמא יבוא לאכול מהן ביו\"ט אבל לקמן בסעיף ז' סתם המחבר כדעת הפוסקים דתלוי הדבר בצידה דכל שאין מחוסרין צידה מותר ליתן לפניהם מזונות וכתב הפר\"ח דכן נוהגין העולם וכן הוא העיקר עי\"ש:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>דגים ועופו' וחיה שהם מוקצה אין משקין אותם ביום טוב <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>ואין נותנים <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>לפניהם מזונות <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>שמא יבא ליקח מהם וכל שאסור לאכלו או להשתמש בו מפני שהוא מוקצה אסור לטלטלו:","m":["{ה} אין משקין וכו' ואין נותנין לפניהם - כתבו האחרונים דוקא לפניהם ממש אסור ליתן אבל אם נותן ברחוק קצת מהם והם באים ואוכלים לית לן בה כיון דעושה הכירא מדכר ולא אתי ליקח מהם:","{ו} שמא יבוא ליקח מהם - לאכלם ובבהמה טמאה דלא שייך זה מותר לכו\"ע:","{ז} ספק צידה - ואע\"ג דלכמה פוסקים עיקר צידה ביו\"ט אינה מן התורה וכמו שסתם ג\"כ המחבר בסימן תצ\"ה ס\"ב מ\"מ החמירו כאן אפילו בספיקא משום דהוא דבר שיש לו מתירין שהרי אפשר לו לאוכלם אחר יו\"ט ובדבר שיש לו מתירין החמירו חכמים אפילו בספק דרבנן:","{ח} אסורים - ואפילו בטלטול מיהו לערב מותר באכילה ואפילו בודאי ניצוד היום ולא בעינן בכדי שעושה כיון דלא ניצוד בידי אדם רק ממילא והסכימו הפוסקים דלאו דוקא ספק צידה אלא ה\"ה כל ספק מוקצה וכ\"ש ספק נולד דמחמרינן בהו כשל תורה ובספק אם בא מחוץ לתחום יש דעות בפוסקים ויתבאר לקמן בסי' תצ\"ח ס\"ג וד':","{ט} ואם מצא המצודות מקולקלות - כלומר שהמצודות פרוסות באורך רב וכשחיה נופלת בראשו א' מתוך שמתפרקת ומתנתקת לצאת מתקלקלות כולן וראשן השני ג\"כ ניתק ממקום שנתקע וע\"כ אף שבמקום זה לא ראה שום דבר ניצוד מ\"מ סימן הוא שניצוד חיה או עוף בראש השני:","{י} ביו\"ט שני - וביום טוב שני של ראש השנה אסור דב' ימים כיומא אריכתא הוא וכן ביו\"ט שני הסמוך לשבת:","{יא} דהוי ס\"ס - שמא אין היום יו\"ט ושמא ניצוד מאתמול וכבר הוכן ולא מחמרינן משום יש לו מתירין למחר כיון דהוא ס\"ס גמורה להיתרא אין כאן איסור כלל ויש חולקין בזה וסבירא להו דלדידן יו\"ט שני לא מטעם ספק הוא שהרי בקיאין אנו בקביעא דירחי ויודעין אנו שהוא חול אלא שאנו מקיימין מנהג אבותינו והוי כיו\"ט ודאי מדרבנן ואין כאן אלא ספק אחד ואסור וכמו בסעיף ג' ויש להחמיר כסברא זו אם לא במקום הפסד גדול:","{יב} בכניסה וביציאה - כדי שלא יכנסו חדשים ושלא יצאו הישנים:","{יג} מותר ליקח וכו' - ומוקצה אין כאן דמעשה הסכירה חשוב כמו שהזמין דגים ידועים. ואם מותר לו לברור כפי מה שצריך ולהחזיר השאר למים תלוי בזה אם בשעה שסכר חשב שאפשר שיצטרך ביו\"ט לכל הדגים שימצא בהאמה א\"כ הרי הוכנו כל הדגים ושפיר יכול להעלות כמו שירצה ולברור הגדולים המשובחים ולהחזיר השאר למים אבל אם בשעה שסתם אמת המים היה יודע בודאי שלא יצטרך ביו\"ט רק איזה דגים א\"כ הרי לא הוכנו כלום וכשבורר ומניח הקטן אגלאי מלתא דהאי לא הוכן א\"כ טלטלם שלא לצורך כדלקמן סעיף יו\"ד ולכן לא יברור ויניח השאר אלא צריך ליקח ולאכול כל מה שיעלה בידו בין טוב ובין רע ולא יחזיר מה שלא ייטב לו:","{יד} היא צרה - עיין בב\"ח וש\"א שכתבו דאם היא רחבה יותר מן ו' טפחים אסור ולענין ארכה מקילין הרבה אחרונים אפילו אם ארוכה כמה כיון שאינה רחבה בקל יש לתפוס הדגים. ואפילו באופן המותר ג\"כ יש מחמירין שלא לצודן במצודה כדרך שעושין בחול אלא ביד ויש לחוש לסברא זו לכתחלה ולאו דוקא אמת המים אלא ה\"ה אם הכניס דגים לתיבה מלאה נקבים והעמידה במים נמי שייכי כל הני דיני ויש מי שאומר דדוקא בביבר ובאמת המים שעכ\"פ הדגים הם בקרקע מקום חיותם מה שא\"כ כשהם מונחים בכלי לא שייך בהו כלל צידה ואפילו צריך להביא מצודה שרי וע\"כ נראה שאין להחמיר בתיבה ליטול ביד אפילו אם רחבה התיבה יותר מן ו' טפחים הרבה. כתבו האחרונים דאם הכניס דגים מבע\"י לבאר וצריך לצוד אותם ע\"י כלי דוקא אסור לצודם ביו\"ט ומ\"מ אם הם בבור עמוק א\"צ לירד למטה כדי לתופסן בידו אלא עומד למעלה ותופסן על ידי כלי:","{טו} שבבית וכו' - ר\"ל שגדלין בבית:","{טז} העומדים לאכילה - לאפוקי אם הם עומדים לביצים אסור למאן דאוסר מוקצה ביו\"ט. ואם קנה עופות אלו ולא חשב כלל לאיזה דבר יעמידם מותרים דסתמייהו לאכילה קיימי:","{יז} מותר לצודן - ואפילו מר\"ה ואפילו צריך להביא מצודה דכיון דבאין לכלובן בערב וגם ניזונין תמיד בבית הרי הם כניצודים. וכ\"ז אם תופסן כדי לשוחטן והתירו משום שמחת יו\"ט הא לא\"ה אסור לכמה פוסקים וכמו שהובא דעתם לעיל סימן שט\"ז סעיף י\"ב בהגה. וכתבו האחרונים עוף שקנה מחדש ועדיין לא הורגל בבית ואינו בא לכלובו בערב דבזה חייב בשבת אם צד וכדלעיל סימן שט\"ז גם ביו\"ט אסור לצודן אפילו הם בבית אא\"כ נכנסו במקום צר. ובח\"א כתב דבלילה כשהן יושבין על הקורה מותר לצודן דעיניהם מתעורות אז ואינן נשמטין מיד התופסן:","{יח} ואינו צריכין זימון - דמוכנים הם וכתבו הפוסקים דמ\"מ ירא שמים יתן עיניו בתחלה בהעופות ויברור איזה שירצה כדי שלא יבא למחר ליטול ולהניח ואעפ\"י שכולם מוכנים הם מ\"מ טורח טרחא יתירה ביו\"ט:","{יט} שצ\"ל הבא מצודה וכו' - עיין לעיל סימן שט\"ז מ\"ב ס\"ק א' ושם נתבאר דכל שאין יכולין לתופסו בריצה אחת אלא צריך להנפש קודם שיגיענו כמי שצ\"ל הבא מצודה ונצודנו דמי. ולפי המבואר עוד שם בעוף אפילו היה במקום דחוק שאפשר לתופסו בשחיה אחת מ\"מ אם החלון או הגג פתוח שיכול לברוח דרך שם אסור לצודו:","{כ} מותר לצודן וכו' - היינו אם הזמינם דלית בהו משום מוקצה הא לא\"ה אסור לתופסן שהרי אסורים גם בטלטול:","{כא} בפרדס - גדור שהוא מקום המשתמר שאין הולד יכול לצאת משם וקל לצודו:","{כב} מותרים בלא זימון - דמסתמא דעתיה עלייהו לכל שעה שיצטרך:","{כג} בתוך ע' - וד' טפחים וכדלעיל בסי' שנ\"ח:","{כד} דדעתיה עלייהו - דכיון שהמקום קרוב ורואה אותם תמיד לא אסח דעתיה מינייהו אפילו בסתמא אבל אם אינו סמוך אי זמין אין אי לא זמין לא:","{כה} כיון שמחוסרת צידה - ומיירי שהפרדס גדול שצ\"ל הבא מצודה ונצודנו ואפילו תהא ניצודה מאליה ביו\"ט ג\"כ אסור משום מוקצה כיון שהזמנתו מבעוד יום לא חלתה:","{כו} יוני שובך וכו' - ר\"ל יוני מדבריות שקננו בשובך שבחצירו או שקננו בעליתו:","{כז} וצפרים וכו' - מיירי גם כן כנ\"ל שאינם מורגלים אצלו אלא פורחים כל היום בשדות ולערב באים שם ללון:","{כח} אסור לצודן - אפילו בכלובן כיון שיכולין לצאת משם ובשבת חייב חטאת ולא דמי ליונים שבבית שניזונים בבית. ובאין תדיר לאכול וכניצודין דמי וגם עי\"ז בני תרבות הם ואינן בורחין ונשמטין כ\"כ כשרוצים לאחוז אותם משא\"כ ביונים אלו שניזונין מעלמא ואין מניחים עצמן ליתפס ביד:","{כט} שאינם מפריחין - אלא מדדין וה\"ה אפילו יכולין לפרוח מעט כל שבקל לתופסו עד שא\"צ לומר הבא מצודה שרי:","{ל} אבל זימון צריכים - ולא דמי לעפרים בס\"ז שאפילו הזמנה א\"צ שאני עוף שיכול לדדות ולהתרחק מחוץ לקן ולהכי כל שלא הזמינם אסור. ודע דאפילו מאן דמתיר מוקצה ביו\"ט מודה הכא דאסור בלי הזמנה:","{לא} וא\"צ לנענעם - לאפוקי מדעת ב\"ש דלא הוי זימון אא\"כ עביד מעשה דהיינו שינענע הקן וכ\"ש אם יאחוז היונים שבורר בידים ולא קי\"ל כן רק אפילו בעומד מרחוק ובראית עינו בורר איזה מהם סגי ומ\"מ צריך שיסמן בדעתו או יטבע עיניו בטביעת עין גמור שלא יחליף למחר באחרת:","{לב} לא סגי - משום דלא פירש בהדיא איזה מהן יקח ולא אמרינן האי דלוקח למחר הוברר דאליו כוון בהזמנתו דחששו חכמים שמא כשיבוא ליקח אחד מהם ימשמשנו וימצאנו כחוש ויניחו ויקח אחר שמן ממנו ונמצא אותו קמא טלטל שלא לצורך ומוקצה הוא שהרי לא הזמין אלא אותו שיקח לבסוף ומשום זה אפילו אם ירצה אח\"כ ליקח מן הבא בידו ג\"כ אסור אמנם אם מזמין עוף פלוני בפירוש אפילו לא משמשו ולא מחזי כלל לא חיישינן שמא כשיקחנו למחר ימצאנו כחוש ויניחנו שכיון שבעיו\"ט אפשר היה לו למשמשו היטב אם שמן הוא ולא עשה כן מסתמא נתרצה איך שיהיה:","{לג} אם זימן כל השובך - וה\"ה לזימן זוג וא\"צ אלא לאחד מהם:","{לד} אינו מועיל - דאדרבה כיון שהזמין יותר ממה שצריך מסתמא דעתו היה לברור למחר את השמן ביותר ואיכא חשש דטלטול מוקצה וכנ\"ל:","{לה} נוטל מה שצריך - ומותר לו אפילו לטלטל ולהניח שכולם מזומנים הם:","{לו} זימן שנים וכו' - וא\"כ איכא עכ\"פ חד דאתי מעלמא שאינו מזומן ולא מיבטל דבע\"ח חשיבי ולא בטלי גם הוא דבר שיש לו מתירין וכתבו האחרונים דכל זה בהניחן קשורים או מותרין ומצא גם השלישי קשור או מותר הא אם הניחן קשורין ומצאן כמו שהניחן רק מצא אצלן שלישי אינו מקושר אין לאסור השנים ואמרינן בודאי הן הם שהכינן וזה שאינו מקושר הוא דאתי מעלמא. עוד כתבו דאין האחד אוסר כולם רק באם היו כולם לפנינו הא אם נאכל אחד מהם או נפל לים שכבר אינו בעולם מותרים השאר דאמרינן איסורא נפל או נאכל וע\"פ האופנים המבוארים ביו\"ד סימן ק\"י סעיף ז' ח' וע\"ש בהג\"ה:","{לז} בקנים המובדלים וכו' - כדרך כל שובכין עשויין עליות עליות הרבה וכל עליה יש בה מחיצות הרבה אבל זימן שחורים ולבנים בקן אחד ומצאן שלא במקומן מותרין דהני ודאי איתהפוכי איתהפך:","{לח} ומצא שחורים במקום וכו' - ובמשכח להו בדוכתייהו שהניחם אע\"פ שיש עוד הרבה לבנים בשובך או שחורים שלא הזמין לא חיישינן שמא איתהפוכי איתהפך:","{לט} אסורין - דבזימן שנים ומצא וכו' בודאי עכ\"פ חד אתי מעלמא ובזימן שחורים וכו' ג\"כ חיישינן דהני שהזמין פרחו והני אחריני נינהו דאתו מעלמא ומיירי דאיכא שובכים בתוך חמשים אמה או שהיונים יכולים לפרוח קצת דאל\"ה מוטב לנו לומר דאיתהפוכי איתהפך משנאמר דמעלמא אתי וכמו שכתב המחבר בסי\"ד:","{מ} זימן ג' ומצא שנים וכו' - דלא מחזקינן ריעותא ואמרינן דהשנים הן הם שהכינן רק אחת אזלא לעלמא:","{מא} מנתחי מהדדי - שדרך בע\"ח להתפרק ולהנתק מקשירתם ואמרינן שהשלישי נתפרק מהם ואזל לעלמא וה\"ה אם מצא גם השנים שמותרים מקשירתם דשרי ג\"כ מטעם זה והנה הרב ט\"ז חולק אדין זה ולדבריו כל שלא מצא כפי שהניחן אמרינן הני שהזמין אזלו לעלמא והנהו אחריני נינהו [מיהו בהזמין שנים ומצא שנים גם הוא מודה דאפילו הניחם מקושרין ומצאן מותרין לא מחזקינן ריעותא ואמרינן דניתקו קשירתם] אבל כמה אחרונים מסכימים לדברי הג\"ה בכל גווני:","{מב} ומצא לפני הקן - פי' דרך כל השובכין להיות מעט מדף העליה בולט מחוץ המחיצה החיצונה של קן וקן ושם היונים יוצאין לשאוף אויר ונוחין שם וחוזרין לקן ואע\"ג דאשכחינהו לפני הקן שרגילין לצאת בו מכיון דלא אשכחינהו בדוכתייהו חיישינן דלמא הני דאזמין אזלו והני מעלמא אתו מהשובכין שסביבות שובך זה:","{מג} סביבותיהם - היינו בתוך חמשים אמה שדרכם לדדות עד שיעור זה וכדלקמיה:","{מד} מותרים - דודאי אלו הן שהזמין בתוך הקן ובאו לפניה:","{מה} אבל אם הם מפריחים וכו' - ומיירי בהם מפריחים קצת דאם יכולין לפרוח כראוי אין בהם דין זימון כלל שהרי אסורים בצידה וכדלעיל בס\"ט ואפ\"ה חיישינן שיפרחו אפילו לחוץ מחמישים אמה:","{מו} ואפילו יש וכו' - ר\"ל ובמדדין גופא ויש קן סביבותם בתוך נ' אמה אין לאסור אלא בשהשובך אחר עומד ביושר נגד שובך זה:","{מז} כיון שאין צריכים צידה - שהרי קטנים הם שאינם פורחין וכדלעיל בס\"ט:","{מח} מותרים - אף למי שהביאם דשל ישראל בכה\"ג אין איסורם רק משום שלא הזמינם ואקצי דעתיה מהם עיו\"ט והכא שהם של נכרי הנכרי לא אקצי דעתיה מהם וממילא מוכנים הם לכל ואם הביאם הנכרי מחוץ לתחום אסורין למי שהביא ומותרין לאחר וכדלקמן סימן תקט\"ו ס\"ה:","{מט} עד שיפשיט - ולהפשיט עכ\"פ מותר קודם שבדקה שאין חוששין שמא תטרף שרוב בהמות כשרות הן:","{נ} לא יהא רשאי להפשיטה - שהרי היא מלאכה שלא לצורך אכילה [וכן עוף שנטרפה בשחיטה אסור למרוט הנוצות] ואפילו להפשיט בדרך שאינו אסור אלא משום שבות גם כן אסור ולא שרינן ליה משום טעמא דלמא מימנע ולא שחיט ויתבטל משמחת יו\"ט וכמו ההיא דתצ\"ט ס\"ג שהרי אפשר ליה להפשיט קודם בדיקה:","{נא} אסור לטלטלה - ואפילו עומדת בחמה ותסרח אסור להניחה במקום צל ולא התירו זה משום שמא מימנע ולא שחיט כיון שיוכל לשחטה במקום צל או להעמידה שם עכ\"פ קודם הבדיקה ויש שכתבו דלהכי לא חששו לשמא מימנע ולא שחיט דמשום שמא ימצא טריפה לא מימנע דלא שכיחא טריפות ומשום זה יש שכתבו דהאידנא דמחמרינן בטריפות הריאה בכמה חומרות שכיחי טריפות ושפיר איכא למיחש שמא ימנע ולא שחיט כשלא נתיר לו עכ\"פ להצניע הטריפה במקום מוצנע שלא יתקלקל וע\"כ יש להתיר בזה\"ז להצניע רק באווזין ותרנגולין דליכא בהו טריפות הריאה מוקמינן אדינא ואסורים בטלטול. וכל זה הוא לשיטת המחבר דמוקצה אסור ביו\"ט וכדלעיל בסימן תצ\"ה אבל לי\"א שהביא הרמ\"א שם דמוקצה שרי גם בעניננו שרי כן כתבו כמה פוסקים ויש מהן שסוברין דבהמה שנטרפה הוי נולד דמעיקרא הויא חזיא לאכילת אדם והשתא עומדת היא לאכילת כלבים וא\"כ גם לי\"א אסור שהרי כתב שם בהג\"ה דמחמירין בנולד:","{נב} אבל מותר וכו' - וכתבו האחרונים דה\"ה בבהמה כשרה מקום שאין מנקר לנקר האחוריים מותר למוכרו לנכרי בדרך המבואר כאן וכ\"ז אם חושש שמא יסרח ויתקלקל עד אחר יו\"ט אבל אם אפשר לו לשמרו לא שרינן מכירה ביו\"ט בין בטריפה ובין באחוריים ואפילו בחושש שיסריח לא שרינן אלא א\"כ שחטה ביו\"ט או בעיו\"ט סמוך לערב שלא היה לו שהות למכור קודם יו\"ט הא אם היה לו שהות אסור בכל גווני:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i>אפילו <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>ספק צידה אסור כגון מצודו' חיה דגים ועופו' שהיו פרושות מערב י\"ט ולמחר מוציא בהם אסורים אא\"כ ידוע שניצודו מבעוד יום <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ואם מצא <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>המצודות מקולקלו' מערב יום טוב בידוע שמערב יום טוב ניצודו:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ספק מוכן מותר בי\"ט שני משום <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>דהוי <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>ספק ספיקא:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אם סכר אמת המים בכניסה ויציאה מעי\"ט <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>מותר ליקח ממנה דגים בי\"ט דהוי ליה ניצודין ועומדין <small> (מאחר שאמת המים <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>היא <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>צרה ואינן יכולין להשמט) (המגיד פ\"ח)</small>:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i><i data-commentator=\"Turei Zahav\" data-order=\"5\"></i><i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>אווזים ותרנגולים ויונים שבבי' או שבחצר העומדים לאכילה מותר <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>לצודן ואין צריכים זימון:","m":[]},{"s":"שאר כל חיה ועוף <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i><i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>שמחוסרים צידה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"5\"></i>שצריך לומר הבא מצודה ונצודנו אסור לצודן וליתן לפניהם מזונו' וכל שאין מחוסרים צידה מותר לצודם וליתן לפניהם מזונות:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>איל וצבי שקננו בפרדס וילדו בו עפרים ועדיין הם קטנים שאין צריכים צידה מותרים בלא זימון ודוקא בפרדס הסמוך לעיר <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>בתוך שבעים אמה <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>דדעתו עלויה <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>והאם אפילו זימון אין מועיל לה כיון שמחוסרת צידה:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>יוני שובך ויוני עליה וצפרים שקננו בטפיחים <small> (פי' כלי חרס הבנוים בכותלים לקנן בהם העופות) </small> <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>אסור לצודן לפיכך אין זימון מועיל להם והני מילי בגדולים אבל בקטנים <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>שאינם מפריחים <i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>מותר לצודן אבל זימון צריכים:","m":[]},{"s":"<i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"6\"></i>כיצד הוא הזימון <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>אומר זה וזה אני נוטל למחר וא\"צ לנענעם <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>אבל באומ' <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>מכאן אני נוטל למחר <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>לא סגי:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i><i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>אם זימן כל השובך וא\"צ אלא לזוג אינו מועיל: <small>הגה ואם הוא אפשר שיצטרך כל השובך יכול להזמין כל השובך ולמחר נוטל מה שצריך (רבינו ירוחם והגהות אשירי פ\"ק דביצה)</small>:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i><i data-commentator=\"Turei Zahav\" data-order=\"8\"></i>זימן שנים <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>ומצא שלשה או זימן שחורים ולבנים בקינים המובדלים <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>במחיצה ומצא שחורים במקום לבני' ולבנים במקום שחורים אסורין אא\"כ מכירן:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>זימן שלשה ומצא שנים מותרים <i data-commentator=\"Turei Zahav\" data-order=\"9\"></i><small> (ואפי' היו מקושרים ביחד מנתחי מהדדי) (ב\"י)</small>:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"20\"></i>זימן בתוך הקן ומצא <i data-commentator=\"Turei Zahav\" data-order=\"10\"></i>לפני הקן אסורים <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>ואם אין <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>סביבותיהם קן אחר הרי אלו מותרים <i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"21\"></i>וה\"מ במדדין <i data-commentator=\"Turei Zahav\" data-order=\"11\"></i>אבל אם הם מפריחין אסורים ואפי' יש קן אחר בתוך נ' אמה אם היא בקרן זוית שאין יכול לראותו מקן זה כיון שאינם מפריחין אלא מדדין משום דכל היכא דמדד' ולא הדר חזי לקני' לא מדדה: <small> (ואם הזמין תוך הקן ומצא על פתח הקן מותרים) (א\"ז)</small>:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"22\"></i>עכו\"ם שהביא דורון לישראל בי\"ט בני יונה קטנים משובכות שיש לו בעיר <i data-commentator=\"Magen Avraham\" data-order=\"17\"></i>כיון שאין צריכים צידה מותרים:","m":[]},{"s":"<i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"7\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"23\"></i>השוחט בהמה ביום טוב טוב לו שלא יבדוק עד שיפשיט שאם תמצא טריפה לא יהא רשאי <i data-commentator=\"Magen Avraham\" data-order=\"18\"></i>להפשיטה:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"24\"></i>אם נמצאת טריפה <i data-commentator=\"Magen Avraham\" data-order=\"19\"></i>אסור לטלטלה אבל מותר <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>למכרה לעכו\"ם כדרך שהתירו מכירה לישראל שלא ישקול ולא יזכיר סכום דמים ואם אינו מאמינו יקח ממנו משכון:","m":[]}],"498":[{"s":"<b>דיני שחיטה ביום טוב. ובו כ סעיפים:</b><br><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אין מראין סכין לחכם בי\"ט לראות אם הוא ראוי לשחוט בו שמא תהיה פגומה ויאמר לו אסור לשחוט בה מפני פגימת' וילך ויחדדנה במשחז' <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>וחכם שראה סכין לעצמו <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>יכול להשאילו לאחרים: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>ועכשיו בזמן הזה שכל שוחט רואה סכין בעצמו כל הרוצה לשחוט בי\"ט יבדוק סכינו מעי\"ט ולא ביום טוב שמא ישחיזנו (ד\"ע ומהרי\"ל והגהות שחיטה) מיהו אם לא בדקו מעי\"ט והוא שעת הדחק יכול לבדקו ביום טוב: (שחיטות ישנים)</small>:","m":["{א} אין מראין וכו' - אפילו אם כבר בדק הטבח לעצמו בעיו\"ט ונמצאת יפה:","{ב} לראות וכו' - כמו שהיה המנהג בזמן חכמי הש\"ס להראות הסכין אחר בדיקתו לחכם מפני כבודו:","{ג} שמא תהיה פגומה וכו' - ובדיעבד אם הראה לו ונמצאת יפה מותר לשחוט בה:","{ד} שראה סכין לעצמו - היינו בביתו ביו\"ט כדי לשחוט בה ועיין בפר\"ח שמצדד דאפילו לכתחלה יכול החכם לראות סכינו של עצמו כדי להשאילה לאחרים והטעם שהתירו לחכם דלגביה ל\"ל שמא ישחיזנה דיודע שאסור להשחיז ומטעם זה מותר החכם גם כן כשאינו רוצה לסמוך על בדיקתו להראות סכינו לחכם אחר:","{ה} רואה סכין לעצמו - שסומכין על קבלה שיש לו:","{ו} יבדוק סכינו מעיו\"ט - ולא יחזיר הסכין לנדן שלו דאם החוד או צדדי הסכין נוגעין בקשיות הנדן לא מקרי תו סכין בדוק כמ\"ש בתבו\"ש סימן י\"ח סק\"ד. וכתבו האחרונים דנכון שיהא לכל טבח ב' או ג' סכינים בדוקים מעיו\"ט:","{ז} ולא ביו\"ט - היינו הבדיקה ראשונה אבל הבדיקה שצ\"ל אחר השחיטה מותר דלא שייך גביה שמא ישחיזנה אם ימצאנה פגומה דלא יועיל ההשחזה להכשיר השחיטה ששחט מקודם:"]},{"s":"<i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>יכול להוליך סכין והבהמה אצל טבח לשחוט ואפי' גדי קטן שצריך להוליכו על כתפו <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>ואע\"פ שהיה אפשר להוליכה מאתמול: <small> (וה\"ה שהטבח יכול להוליך הסכין אצל הבהמה) (ב\"י)</small>:","m":["{ח} יכול לבדקו ביו\"ט - וכגון שאין בעיר סכין אחר שנבדק מעיו\"ט:","{ט} סכין והבהמה אצל טבח - ואפי' דרך ר\"ה ואין חוששין שמא ימלך ולא ישחט ונמצא דהוציא שלא לצורך:","{י} ואע\"פ שהיה אפשר וכו' - דהוצאה באוכל נפש כתיקון אוכל נפש עצמו דמי [ולא כמכשירין] ולכך אין חילוק בין אפשר מבע\"י או לא ואפילו לדעת היש מחמירין לעיל בסי' תצ\"ה ס\"א בהג\"ה לענין הוצאה אין להחמיר:","{יא} וה\"ה וכו' הסכין אצל הבהמה - ולא אמרינן דטוב יותר שהבהמה תלך ברגליה אצל הטבח:","{יב} ובאות ולנות - לאו דוקא בכל יום אלא אפילו שבאים לפרקים ללון נמי מוכנות הן מן הסתם וכדלקמיה:","{יג} ולוקחין מהם - ואפילו לא באו מבע\"י אלא בלילה (אם רק לית בהו איסור תחומין כגון שבאו מאליהם וכדומה) דלא חשב עלייהן כלל ביה\"ש נמי מותרין דכבהמות בייתיות דמי וא\"צ לחשוב עליהם:","{יד} והלנות חוץ לתחום - היינו שדרכם להיות רועות כל הקיץ עד חודש חשון ואח\"כ באות לביתם מ\"מ כל ימי הקיץ אין דעת אנשי העיר עליהם והרי הן מוקצין וע\"כ אם באו וכו':"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>בהמו' שיוצאות ורועות חוץ לתחום ובאות ולנות בתוך התחום הרי אלו מוכנות ולוקחין מהן ושוחטין אותן ביום טוב אבל הרועות והלנות חוץ לתחום אם באו בי\"ט <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>אין שוחטין אותן בי\"ט מפני שהן מוקצין ואין דעת אנשי העיר עליהן וה\"מ בבהמות ישראל <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אבל של עכו\"ם לית בהו משום מוקצה דאין העכו\"ם צריך הכן אא\"כ באו בשביל ישראל שאז אסור <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>לפיכך עכו\"ם שהביא בהמה במקולין <small> (פי' מקום ששם שוחטין הבהמות) </small> אם ידוע שלנות חוץ לתחום <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>אסורות ואם <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ספק <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>מותרות אפי' באו לצורך ישראל שהמוקצה הולכים בספיקו להקל ואם הביאום לצורך העכו\"ם או אפי' סתם בעיר שרוב עכו\"ם מותר שכל המביא לצורך הרוב מביא:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>בהמות הידועות ללון חוץ לתחום <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>ונמצאו בעיר <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>ביום <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>שני אני אומר שמא מבערב הכניסן וחוץ לחומה לנו ומותרו' וכל שכן השחוטות בבוקר שחזקה מבערב הכניסן לתוך התחום:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>עגל שנולד ביו\"ט מותר לשחטו <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i>אם האם <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i><i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>עומדת <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>לאכילה והוא <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>דקים ליה בגויה שכלו לו חדשיו: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ובעינן גם כן <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>שהפריס על גבי קרקע (טור והרא\"ש) <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>דחיישי' שמא יראה בו ריעותא באיברים הפנימיי' ונמצא שחט בי\"ט שלא לצורך כן נראה לי מדברי הרא\"ש והטור</small>: <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>ואם היו שבת וי\"ט סמוכים זה לזה נולד בזה <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>מותר בזה:","m":["{טו} אם באו ביו\"ט - ומיירי דלית בהו איסור תחומין כגון שבאו מאליהם או עירבו לאותו צד או לענין להתיר אותם לישראל אחר דאל\"כ בלא\"ה אסורין שהרי באו מחוץ לתחום:","{טז} אין שוחטין וכו' - ולמאן דשרי מוקצה ביו\"ט מותרים ויש מי שכתבו דלכו\"ע אסור דכיון שאין נכנסות לתחום העיר כל ימי הקיץ הוי להו כגרוגרות וצמוקים שהעלם לגג ליבשן דלכו\"ע אסוחי אסח דעתייהו מנייהו עד שיתייבשו וכמבואר לעיל בסי' ש\"י:","{יז} דאין הנכרי צריך הכן - וכמו שפירשנו לעיל בסי' תצ\"ז סט\"ו ולהכי אפילו היו מהבהמות הלנות בכל ימות הקיץ שלא בבית לית לן בה:","{יח} שאז אסור - עכ\"פ לישראל זה שהובא עבורו מטעם איסור תחומין ולישראל אחר מותר:","{יט} לפיכך וכו' אם ידוע וכו' - הלשון מגומגם קצת דאינו מסיים מענינא דרישא ובאמת המחבר מתחיל עתה מענין אחר וחסר כאן איזה תיבות כמו שביארתי בבה\"ל וכצ\"ל ודוקא כשידוע שלנו חוץ לתחום ולא בספק לפיכך וכו':","{כ} נכרי שהביא בהמה במקולין - שיש מקומות שהנכרים מביאין בהמות במקולין של ישראל וישראל שוחט ומוכרים הבשר ואם מסתפק לנו על בהמה זו אם הביאה העכו\"ם ביו\"ט מחוץ לתחום אין לאסור:","{כא} שלנות וכו' - צ\"ל שלנו:","{כב} אסורות - היינו בעיר שאין רובה נכרים דאמרינן מסתמא לצורך ישראל הביאם:","{כג} שהמוקצה הולכים וכו' - ר\"ל באיסור של חוץ לתחום וקרי ליה נמי מוקצה אבל בספק מוכן בודאי לחומרא אזלינן וכדלעיל סימן תצ\"ז סעיף ג' וד' והמחבר בכאן החזיק בשיטת הפוסקים דתחומין קילא ולא מחמרינן בספיקה וכבר תמהו האחרונים דבכמה מקומות פסק כדעת הפוסקים להחמיר גם בספק תחומין [עיין בסימן שכ\"ה ס\"ט ובסימן תקט\"ו] ובסעיף ד' יתבאר:","{כד} לצורך הנכרי - ר\"ל ואז מותר אפילו היא עיר של ישראל:","{כה} בהמות הידועות וכו' - היינו הך דס\"ג אלא דרבותא קמ\"ל שאפילו הבהמות שרואים היום אצל עכו\"ם ידועות לנו שדרכם ללון חוץ לתחום וגם בערב יו\"ט לא היו עוד בעיר וסד\"א דגם עתה היה כן אלא שהעכו\"ם הביאם בעיר היום לצורך המקולין קמ\"ל דגם בזה לא נפק מכלל ספיקא דשמא שפיר הביאם מאתמול רק היו חוץ לחומה ובבוקר הכניסם לעיר:","{כו} ביום שני - כתבו המפרשים דט\"ס הוא וצ\"ל ביו\"ט:","{כז} השחוטות בבקר - ר\"ל שמביאן הנכרי למקולין לשחוט אותן בבקר ואמרינן שבודאי מביאן מבע\"י כדי שלא יאחר הזמן וגם שאין מצוי כ\"כ לילך עם הבהמות בלילה. וכ\"ז הוא כפי שיטתו בס\"ג דבתחומין תלינן להקל כ\"ז שאינו ברור לנו וכבר כתבנו דהמחבר בעצמו מחמיר בזה בכמה מקומות ודעת המ\"א שלא להקל רק בשהעכו\"ם שרוי בעיר ובהמות מצויות לו תוך התחום דבזה לא מחזקינן איסורא או ביו\"ט שני ומטעם ס\"ס וכדלעיל בסימן תצ\"ז ס\"ד:","{כח} עומדת לאכילה - ר\"ל דאז מותר אפילו למאי דפסק לעיל בסימן תצ\"ה ס\"ד דמוקצה אסור ביו\"ט ומטעם דכיון שאמו מוכנת לאכילה הרי הוא מוכן אגב אמו שאם היה רוצה היה שוחט האם קודם שנולד העגל ואוכל שניהם ביו\"ט [ואפי' אם ידוע שהאם היא טרפה מ\"מ אינה מוקצה ביו\"ט שהרי היא מוכנת כבר לכלבים א\"כ גם העגל ממילא אינו מוקצה] ולפי מנהג מדינותינו שאין אוסרין מוקצה ביו\"ט אלא נולד [כמו שפסק הרמ\"א שם בהג\"ה] יש להתיר עגל שנולד ביו\"ט אפילו אם אמו עומדת לגדל ולדות ואין לאסרו משום נולד כיון שהלידה לא עשתה שינוי בגופו כלל שהרי אף קודם לידתו היה ראוי לאכילה כמו אחר שנולד:","{כט} והוא דקים ליה וכו' - והאידנא אין אנו בקיאין בזה כדאיתא ביו\"ד סימן י\"ג סס\"ג וע\"כ אין שוחטין עגל שנולד ביו\"ט או בשבת עיו\"ט קודם יום שמיני שמא נפל הוא והיכא דצריך להמתין שבעה ימים כגון לדידן שאין אנו בקיאים אם כלו חדשיו וחל יום שמיני ביו\"ט א' י\"ל דאסור דאתקצאי בין השמשות וה\"ה כשחל יום שמיני ביו\"ט ב' [פמ\"ג במשב\"ז] אבל בספר ישועות יעקב מתיר בזה כיון דרוב הולדות ולד מעליא ילדן ובודאי יגיע לכלל היתר לא חשיב מוקצה:","{ל} חדשיו - בן ט' חדשים לגסה וחמשה לדקה:","{לא} ובעינן גם כן שהפריס וכו' - דעי\"ז יצא מחשש שמא נתרסקו איבריו ביציאתו מן הרחם שהוא מקום צר:","{לב} דחיישינן וכו' - ר\"ל אע\"פ שאם נולד בחול היכי דידעינן שכלו לו חדשיו מותר לשוחטו בו ביום ואין חוששין שמא נתרסקו איבריו וא\"צ בדיקה באיבריו הפנימים מ\"מ ביו\"ט חיישינן שמא בלא מתכוין יראה חשש טריפות באיבריו הפנימיים ונמצא ששחט ביו\"ט שלא לצורך. ודעת הרש\"ל וט\"ז דא\"צ להפריס ואין לחוש לכל הני חששות אך לדידן אין נ\"מ בכל זה דאין אנו בקיאין בכלו חדשיו וכנ\"ל:","{לג} נולד בזה מותר בזה - אעפ\"י שהוא יו\"ט ואין שבת מכינה ליו\"ט לפי שאין לידה זו חשיבא הכנה כיון שהיה ראוי לאכילה קודם הלידה כמו אחר הלידה:","{לד} כדי לאכול ממנה - אחר שתצא נפשה כמ\"ש ביו\"ד סימן כ\"ז ואף שאין בדעתו לאכול ממנה כלום והטעם דבאופן זה שיש שהות לאכול אין איסור מן התורה לשחטה ביו\"ט דאלו היו מזדמני ליה אורחים שלא אכלו עדיין ורוצים עתה לאכול מבהמה זו היתה השחיטה מתרת להם א\"כ שחיטה זו נקראת מלאכת אוכל נפש וע\"כ אע\"פ שלא נזדמנו אורחים אין בשחיטה זו איסור מן התורה אלא שחכמים אסרוה כל שאין בה צורך יו\"ט ובמקום הפסד לא העמידו חכמים דבריהם משא\"כ בבהמה בריאה אין לשחטה אא\"כ צריך לה ביו\"ט גופא:","{לה} כזית צלי - שזהו הקל בבישולין ודי בכזית משום דא\"א לכזית בשר בלא שחיטה וא\"כ הוי השחיטה כולה לצורך יו\"ט:","{לו} ואפי' אין שהות וכו' - כיון דמן הדין מותר בלא בדיקת הריאה אלא שהחמירו לכתחלה לבדקה הכא משום הפסד ממונו א\"צ להחמיר בזה:","{לז} תחלה - ודעת כמה אחרונים דבעינן שיהיה שהות כדי להפשיטה ולבודקה ובספר ישועות יעקב כתב דדוקא בגדיים וטלאים דלא שכיח בהו סירכא יש להקל אבל בבהמה גסה בעינן שיהיה ג\"כ שהות כדי להפשיטה ולבודקה:","{לח} אינו נוטל עורה - ר\"ל לטלטלו ולהניח על מקומו אחר שהפשיטו מן הבהמה וכדלעיל בסימן ש\"ח סכ\"ה ואע\"ג דלקמן בסימן תצ\"ט שרינן לטלטל העור אחר ששחטו הבהמה ביו\"ט התם בבהמה בריאה ומשום דאי לא שרית ליה לא ישחוט ואתי לאימנועי משמחת יו\"ט משא\"כ הכא דמוכרח לשחוט שלא תמות:","{לט} אבר אחד - שאז בטל העור לגבי האבר ומותר לטלטלו עמו:","{מ} וי\"א דאין וכו' - דהפשטה הוא ג\"כ בכלל מלאכה ואסור כיון שהוא שלא לצורך אכילה ואע\"ג דליכא בזה איסור דאורייתא דהואיל אי מזדמני ליה אורחים שהיו צריכין להבשר לאכול היה בודאי מותר להפשיט [אבל זהו רק בשיש שהות ביום כדי להפשיט ולהאכילם] השתא נמי מותר עכ\"פ מדרבנן מיהו אסור ודעת המחבר דכשם שהתירו בשחיטה משם הפסד ממון כן התירו נמי בהפשטה משום הפסד ממון שלא יסריח הבשר ועיין במ\"א וא\"ר וש\"א דהעיקר כדברי המחבר ורק לכתחלה יש ליזהר [אכן זהו דוקא באופן שיש לחוש שאם ימתין עד הערב תסרח הבשר אבל בלא\"ה בודאי אסור עכ\"פ מדרבנן להפשיט] וכתב הפמ\"ג דכ\"ז בשיש שהות הרבה אבל אם שחט סמוך לערב וא\"א לאכול כ\"א כזית אסור להפשיט העור מן התורה הואיל דליתא בזה הסברא דאי מזדמני ליה אורחים אחר דאין שהות לאכול יותר:","{מא} כלל - וכן השוחט עוף מפני שהוא מסוכן ואין דעתו לאכול ביו\"ט אסור למרוט נוצתו:","{מב} להורות - ואפשר דאם יפשיט ע\"י שינוי כגון בקוץ או בקנה דבעלמא ג\"כ אין בזה אלא משום שבות אין להחמיר בזה אחרי דהרבה מסכימים עם דעת המחבר וכנ\"ל:","{מג} אם שחט בהמה - מדסתם משמע דאף בבהמה בריאה דינא הכי:","{מד} יביאנה בידו - אע\"ג דמפיש עי\"ז בהלוכא מ\"מ עדיף טפי כדי שלא יהא כעובדא דחול ועיין בפמ\"ג שמוכיח מהר\"ן דאפילו ע\"י שינוי אין כדאי להביא על ידי מוט:","{מה} איברים איברים - ואם א\"א לו לשנות להביא איברים איברים כגון שצריך למהר להביא לאורחים נראה דמותר להביא ע\"י מוט ומוטה [או\"ז וע\"ש דמוכח דבמסוכנת יש להחמיר ללישנא קמא גם באופן זה ואין להקל אלא בבריאה]:","{מו} ולכן צריך שהיה מעל\"ע - כדי שיצא מחשש ריסוק איברים וצריך ג\"כ בדיקה דנהי דבודאי לא נתפרקו איבריו מדשהה מעל\"ע מ\"מ שמא אירע ריעותא באיברים הפנימים ונטרף עי\"ז:","{מז} לשחטו ביו\"ט - היינו אחר ששהה מעל\"ע אף שהוא מחוסר בדיקה עדיין ולפי דעת הג\"ה ביו\"ד סי' נ\"ח ס\"ה דאין אנו בקיאין בבדיקת כל האיברים לא משכחת דין זה לדידן והרמ\"א לא העיר בזה שסמך על מה שכתב ביו\"ד שם:","{מח} ולא חיישינן וכו' - דאע\"ג דצריך בדיקה מ\"מ כיון שהיה לו מתחלה חזקה דכשרות דרוב בהמות ועופות כשרות הן מותר לשחטו דמעמידין אותו בחזקת היתר:","{מט} אע\"ג דאיתיליד ביה ריעותא - וה\"ה בספק נקובה בקוץ וכה\"ג דמותר לשוחטו וכ\"ש היכא דליכא ריעותא כלל רק שיש מקומות שמצויות טריפות הרבה כמו כשירות דאין לנו לחוש שמא ימצא טרפה דמעמידין אותה בחזקת היתר דרוב בהמות שבעולם כשרות הן ויש חולקים אעיקר דינא דמחבר וסוברין דאין לשחוט במקום דאיכא ריעותא וה\"ה במקום שהטריפות מצויות כמו כשרות ועיין בשע\"ת שכתב דמכ\"ש אם רובן טריפות אפילו רק מחמת חומרות האחרונים דאסור לשחוט ביו\"ט ולמעשה הכריעו האחרונים דיש לחוש לדעה זו ולהחמיר אפי' במחצה על מחצה והוא שהמחצה טריפות שמצוי הם טרפות גמורות מצד הדין אבל אם רק מחמת חומרות האחרונים מותר לשחוט ביו\"ט אם הוא לצורך וה\"ה במסוכנת מחמת הפסד ממון אבל בלא\"ה המנהג שלא לשחוט שום בהמה ביו\"ט אפי' היכא דלא שכיחי טריפות כ\"כ שמא תמצא טרפה אבל עוף נוהגין לשחוט ביו\"ט [ח\"א]:","{נ} אין חכם יכול וכו' - בין שהומם ביו\"ט בין שהומם מערב יו\"ט משום דמיחזי כמתקן דאסור ביו\"ט ולא דמי לשאר הוראה שאין האיסור וההיתר תלוי בהוראת פי המורה אלא בידיעת הדבר משא\"כ בבכור אפילו יש בו מום גמור כל שלא התירו אותו חכם או ג' הדיוטות ושחטו אסור ולפיכך כשמתירו הרי הוא כמתקנו:","{נא} לראותו וכו' - ולהתירו אבל לראות בכור ולעיין בדינו לא להורות לאחרים למעשה הוי כלימוד תורה בעלמא ולא אסור:","{נב} אינו יכול לשוחטו - אע\"ג דמשום דעבר חכם אהא דאין רואין אין סברא לאסור מ\"מ אסור משום מוקצה לא מיבעי אם הומם ביו\"ט דבודאי לא מיתחזי מערב יו\"ט ואפילו בהומם מערב יו\"ט די\"ל דעתיה עליה למשאל לחכם ביו\"ט ואם יתירנו יאכלנו מ\"מ כיון שאסרו חכמים לראות מומין ביו\"ט א\"כ ע\"כ אסח דעתיה מיניה דלא אסיק אדעתיה שימצא חכם או אפילו ג' הדיוטות שיעברו אאיסור דאין רואין מומין וכתבו הפוסקים דלכו\"ע אסור בזה ואפילו למאן דשרי מוקצה בעלמא ביו\"ט בהיסח הדעת כזה מודו דאסור:","{נג} אבל אם נולד במומו - היינו שנולד ביו\"ט ומום עמו ליכא כאן משום מוקצה שהרי ביה\"ש היה ראוי הולד לאכול אגב אמו אם היה שוחטה ולהכי אף שכשנולד אידחי שהרי נאסר כ\"ז שלא התירו חכם מ\"מ כשנמצא חכם והתירו אין לאסור משום מוקצה שהרי ביה\"ש לא היה מוקצה ואם נולד תם והומם בו ביום עיין בה\"ל איך דינו:","{נד} ואם ראה המום וכו' - ר\"ל היכא שעיקר ראיית הבכור היה בעיו\"ט דהיינו שעיין בדינו אם הוא מום קבוע והוסכם אצלו שהוא מום גמור רק שלא חקר ודרש עדיין אם לא פשע בעל הבכור בנפילת המום [שכל מום שלא נפל מעצמו אלא אחרים גרמו לו בכוונה אינו חשוב מום לישחט על פיו] בזה מותר לו לעשות חקירה ודרישה גם ביו\"ט ואין זה בכלל אין רואין מומין ביו\"ט:","{נה} אסור להעלותו - ואפילו הומם מחמת נפילתו וכדמסיים דהא וכו' וטלטול שלא לצורך שחיטה אסור:","{נו} אלא עושה לו פרנסה במקומו - ואע\"ג דפסק המחבר לעיל בסימן תצ\"ז ס\"ב דכל דבר שהוא מוקצה אסור ליתן לו מזונות הכא התירו שלא ימות:","{נז} אותו ואת בנו וכו' - דבהמות בעלמא שנפלו בודאי מותר לו להעלותו אע\"פ שאינו שוחט מהם כיון שראויין לשחיטה ואפשר יצטרך לו בתר הכי אבל אותו ואת בנו שע\"כ חדא לא חזיא ומטלטל שלא לצורך וע\"כ צריך להערים:","{נח} ואינו שוחטו - שמוצא לו עלילה שמא חבירו שמן ממנו והתירו לו להערים משום צעב\"ח ומשום הפסד ממונו:","{נט} רצה זה שוחט - ומשמע דעכ\"פ מחויב לשחוט אחד מהם אכן הרבה פוסקים הביאו בשם הירושלמי דאם רוצה אח\"כ שלא לשחוט אחד מהם ג\"כ הרשות בידו דעכ\"פ העלאה היתה בהיתר ומ\"מ כתב בעבודת הקודש להרשב\"א דראוי לחוש ולהחמיר ולשחוט אחד מהם שלא יהא ניכר ההערמה:","{ס} יכולים לשחטה - כיון דא\"א לכזית בשר בלי שחיטה אינו עושה הישראל בשביל עכו\"ם כלום אלא לעצמו הוא עוסק:","{סא} ואפילו יש להם שתים - דהיה אפשר לומר עם העכו\"ם מתרצה לחלקן יחלקו מחיים קמ\"ל דאינו מחויב לחלוק לא מיבעיא אם אינו צריך רק חצי בהמה ליו\"ט א\"כ כשיחלוק ויצטרך לשחוט בהמתו בשביל מעט הבשר שצריך לו יופסד הבשר הנשאר אלא אפילו צריך לכולא בהמה ורוצה לשחוט שתיהן ועכו\"ם נתרצה לחלוק ג\"כ לא אמרינן ליה לחלוק ואפילו ב' הבהמות שוות במראה ובקומה ובדמיהן דאפשר אין הבשר של בהמה זו שמן ומוטעם כבשר בהמה אחרת וניחא ליה טפי שיאכל מבשר ב' הבהמות וי\"א דאם העכו\"ם מתרצה ליתן לו הגדולה והטובה אסור לשחוט השניה אכן אם הישראל ששוחט אינו נוטל לעצמו כ\"א חלק הפנימי וחלק אחורים מניח בעור לעכו\"ם המשותף לכו\"ע מותר לשחוט שתיהן בכל גווני דהא אין לו טרחא בחלק העכו\"ם וא\"א לכזית בשר בלא שחיטה:","{סב} לתלוש הצמר - דהוי עוקר דבר מגידולו ואף דהוא כלאחר יד דאין דרך להסיר הצמר ע\"י תלישה רק ע\"י גזיזה עכ\"פ מדרבנן אסור:","{סג} בידו - ולא בכלי משום דנראה כגוזז [פמ\"ג]:","{סד} ואם וכו' - ואין בו איסורא דה\"ל דבר שאינו מתכוין שאינו מתכוין לתלוש אלא לפנות:","{סה} נתלש - ולא יזיזנו ממקומו אלא ישאר שם מסובך עם שאר צמר הצואר. ואם היה צמר מסובך על הצואר שא\"א לפנותו ואין לשחוט כך כמבואר ביו\"ד סימן כ\"ח ס\"ח בהג\"ה ולא היה באפשרו מעיו\"ט לזה י\"ל דשרי לעשות כן ביו\"ט [פמ\"ג]:","{סו} לא ימרוט - דמריטת נוצה הוא תולדה דגוזז דעוף דרכו במריטה ואע\"ג שאחר השחיטה מותר למרוט הנוצה ואיסור גוזז שייך אף לאחר מיתה וכמו שכתבנו בסימן ש\"מ לא אמרינן מה לי מחיים מה לי לאחר השחיטה דלאחר שחיטה שאני שכיון שכבר הותרה בשחיטה לאכול וא\"א לאוכלה בלי מריטת נוצה מותר למורטה כמו שמותר לצלותה ולבשלה וכן בבהמה מותר לאחר שחיטה להפשיט את עורה מטעם זה אע\"ג דהפשט אב מלאכה הוא אבל בעוד שלא נשחטה כל מאי דעביד מכשירי אוכל נפש שאפשר לעשות מאתמול הוא ואסור [הרא\"ש]:","{סז} לעשות - ומ\"מ לפנות בידו ולמשוך אילך ואילך וכנ\"ל בסי\"ב מותר גם בנוצות:","{סח} לסכין - הנה בב\"י הביא דעת הרמב\"ן שמיקל בזה והוא הסכים לדינא לאיסור כרוב הפוסקים החולקים עליו וכמו שסתם כאן ומ\"מ נהגו עכשיו השוחטים למרוט מפני שאומרים שא\"א לשחוט בלא זה וסומכין על דעת הרמב\"ן ומ\"מ בודאי אם אפשר לשחוט בלא מריטה רק שיפנה בידו יש להחמיר וכנ\"ל:","{סט} חיה ועוף - שצריכין כיסוי הדם:","{ע} עפר מוכן וכו' - ויהיה העפר תיחוח שיוכל לכסות בו ולא יצטרך לכתשנה דכתישת רגבים הוא מלאכה גמורה דהוא תולדה דטוחן ולא הותרה ביו\"ט וה\"ה באפר של הסקה שהוסק מבעוד יום דמסתמא מוכן הוא לכל תשמיש וכדלקמיה בסט\"ו וכשיש לו עפר מוכן או אפר יטלטלנו ויניח למטה במקום שישחוט ואחר השחיטה יכסנו בם גם למעלה דצריך כיסוי בתיחוח למטה ולמעלה כמבואר ביו\"ד סימן כ\"ח וע\"ש ביו\"ד דאם שחט ע\"ג קרקע קשה ויש שם דם הרבה יטול קצת ממנו ויתנו בעפר תיחוח ויכסהו אכן אם נתייבש הדם קצת אסור לגוררו ביו\"ט דשמא אתי לאשוויי גומות דהוי מלאכה דאורייתא:","{עא} מבע\"י - דאם ירצה לחפור ביו\"ט כדי לכסות יש בזה תרי איסורי אחד משום חפירת גומא ואחד משום טלטול העפר דהוא מוקצה. ומש\"כ אם יש לו וכו' דאם אין לו לא יכסהו עד הערב:","{עב} דקר נעוץ מבעוד יום - דעל ידי זה שנעוץ הדקר בקרקע הו\"ל הקרקע כחפור ועומד ודעת כמה פוסקים דבעינן שינעוץ בהדיא לשם הכנה לצורך מחר:","{עג} בעפר תיחוח - דבעפר קשה הלא צריך לכתוש כדי לכסות ואסור וכנ\"ל ואע\"ג דבתיחוח נמי הלא קעביד גומא עכשיו בהוצאת העפר אין בזה איסור דאורייתא דהוא מלאכה שא\"צ לגופה וגם הוא מקלקל והתירו בדיעבד כששחט משום מצות כיסוי ומשמע מהפוסקים דחשש גומא אינו אלא כשהיה רק מעט עפר תיחוח באמצע וסביב קרקע קשה וכשנוטל העפר נשאר גומא אבל כשהיה עפר תיחוח הרבה סביב אין עושה גומא בנטילתו שמיד שנוטל העפר נשאר עפר אחר במקומו. ומ\"מ לענין לשחוט לכתחלה אפילו על סמך עפר כזה אסור דנעיצת דקר אינה הכנה גמורה להוציא מידי מוקצה שהרי מ\"מ לא נטלו להעפר ממקום חיבורו מבעוד יום ולא התירו ע\"י נעיצת דקר אלא בדיעבד כשכבר שחט:","{עד} מכסהו בו - וכתבו האחרונים דאם העפר תיחוח היה הרבה עד שלא נעשה גומא ע\"י נטילתו העפר יכול לכסות בדיעבד כשכבר שחט אפילו לא היה שם דקר נעוץ מבע\"י:","{עה} לכמה דקירות - שכשנעץ הדקר להכנה מסתמא דעתו היה להכין מן העפר כפי השיעור שיצטרך לו לכיסוי ויש מאחרונים שסוברין דהכנה שהכין מאתמול לא מהני אלא לאותו דקר שנעץ שהזמינו לכך אבל לא לדקור מחדש בשביל זה וכ\"ש להפוסקים שסוברין דהטעם דבעינן דקר נעוץ מבע\"י כדי שלא יהא חשש חפירה ביו\"ט פשיטא דאסור לדקור מחדש ביו\"ט:","{עו} מותר לכסות בו - היינו אפילו לשחוט לכתחלה ע\"ד זה דהו\"ל מוכן דכיון שהיה אפר מאתמול דעתיה עלויה לכל מילי שיצטרך:","{עז} אסור - ואפילו להמתירין מוקצה ואפילו בנולד מ\"מ בנולד גמור כזה דמעיקרא עצים והשתא אפר כו\"ע מודים דאסור בטלטול. ואם הסיק עצים היום ע\"ג אפר של אתמול ונתערב האפר באפר של אתמול [בענין שלא היה ניכר מעולם בפ\"ע בלי תערובות דבזה ליכא כללא דדבר שיש לו מתירין אפי' באלף לא בטיל] בטל ברוב:","{עח} אא\"כ הוא חם שראוי וכו' - דאתמול בעודן עצים היו מוכנים להיסק ולבשל ולצלות ועודנו בתשמישו זה ואיידי דחזי לאפוכי ביה מידי לצליית ביצה שקיל ליה נמי ומכסה בו להדם:","{עט} אע\"פ שאינו ראוי - דשרו רבנן מוקצה בדיעבד שלא לבטל מצות כיסוי:","{פ} ומיהו עדיף טפי וכו' - דדקר שהיה נעוץ מבע\"י לכך אין בו איסור מוקצה ורק עשיית גומא דאינו אלא מקלקל במקום שא\"צ להגומא וס\"ל דזהו קילא מאיסור מוקצה אכן כמה אחרונים חולקים אהגה\"ה זו וס\"ל להיפך דמוטב לכסות באפר מוקצה דאינו אלא טלטול בעלמא ולא להגביה העפר עם הדקר שעושה גומא בידים:","{פא} לביתו לצורך גינתו - היינו שדעתו היה בפירוש לצורך גינתו לשוטחה שם ולכך דוקא אם הוא עפר הרבה ומשום דכ\"ז שהוא צבור וכו' אבל אם רק מלא קופתו לא ואפי' הניחם בקרן זוית לא מהני משא\"כ בסי\"ז שהכניס לבית בסתם אפילו מלא קופתו מותר כשייחד לו קרן זוית וכדלקמי' ויש מן הפוסקים שסוברין דדוקא אם הכניס לגינתו ממש דאז אמרינן אם הוא מועט מלא קופה וכיוצא בטל לגבי קרקע הגינה משא\"כ במכניסו לבית או לחצר אע\"פ שלא הכניס אלא מלא קופה וייחד לו מקום אינו בטל:","{פב} והוא כנוס במקום אחד - ר\"ל שלא שטחם עדיין ע\"פ גינתו אלא מונחים לע\"ע כמו שהכניסם בצבור אחד:","{פג} לכסות בו - ואפילו לשחוט לכתחלה ע\"ד עפר זה וכמו שמסיים שכל זמן וכו'. וכתבו האחרונים דסעיף זה מיירי גם כן בשהיה העפר תיחוח כמו ההיא דסי\"ד הלא\"ה אסור לכסות בו ולענין לשחוט לכתחלה [או לשאר צרכים] צריך שיהיה תיחוח כ\"כ עד שלא יעשה שום גומא בנטילתו:","{פד} לכל מה שיצטרך - ומשמע דלכל תשמיש מותר ויש פוסקים שכתבו שלא התירו אלא לענין כיסוי שהוא צורך מצוה אבל לשאר תשמישים לא ואפילו לענין כיסוי דוקא דיעבד אבל לא לשחוט לכתחלה ע\"ד זה ולא דמי לסעיף י\"ז דלקמיה דכאן אין הכנה גמורה כיון שעיקרו בא לצורך גינתו ויש להחמיר כסברא זו:","{פה} מלא קופתו וכו' - מעיו\"ט ומערה אותו על הקרקע:","{פו} בסתם - ר\"ל שלא חישב בהדיא לצורך גינה אלא בסתם וכנ\"ל:","{פז} וע\"ל סי' ש\"ח וכו' - ר\"ל שמבואר שם דמותר אף לכסות בו צואה אף דאפשר היה לומר דכונתו לא היה אלא לדבר שתשמישו תדיר ודאי אבל לא לזה דאפשר שלא יעשה התינוק צרכיו בבית ודוקא בזה שהכניסו לבית בסתמא דאז אמרינן דדעתו לכל מה שיצטרך אבל אם הכניסו לדבר שתשמישו ודאי כגון שהכניסו לכסות בו דם עוף שדעתו לשחטו ביו\"ט אסור לכסות בו צואה ויש מקילין גם בזה:","{פח} אגב קרקע הבית - משום מיעוטו וכמו בסעיף הקודם:","{פט} שייחד לו קרן זוית - וגם צריך ליזהר ליטול ממנו בשוה ולא לעשות גומא או דמיירי שהוא תיחוח הרבה דתיכף כשנוטל החול נופל לתוך הגומא וסותמה [אחרונים]:","{צ} דכיון שלא שטחו וכו' - עיין לעיל בסי' ש\"ח במ\"ב ס\"ק מ\"ד דאם שטחו נתבטל אגב קרקע הבית אפילו אם הכניסו בפירוש לצרכיו:","{צא} ואם הוא עפר תיחוח וכו' - דאל\"כ הלא צריך כתישה ואסור. ואם מיירי שלא שחט עדיין צריך שיהיה העפר תיחוח כ\"כ כל סביביו שבלקיחתו לא יעשה גומא או שיטול ממנו בשוה [וכגון שהיה משופע וגבוה קצת] וכנ\"ל דאל\"כ אסור לכתחלה עכ\"פ לשחוט ע\"ד זה וכמבואר למעלה. וכתבו האחרונים דעשיית גומא שייך אפילו בקרקע תלוש כמו בכאן שהעפר כבר נתלש ונחפר וה\"ה בעפר שבכלים ולפ\"ז אין לתחוב נר בכלי מלא עפר אם העפר קשה קצת שנעשה גומא בתחיבתו [דאם העפר תיחוח דכשיוציאנו תחזור ותפול אין זה חשיב עושה גומא] ומ\"מ להוציא נר מעפר זו אע\"פ שנעשה גומא ממילא לית לן בה:","{צב} כוי פי' וכו' - ויש עוד מין כוי שהוא בריה בפ\"ע והוא ספק חיה ספק בהמה ויהבינן להו חומרי שניהם דטעונין כיסוי כחיה וחלבן אסור כבהמה:","{צג} מתיש וצבי - ר\"ל צבי הבא על התישה דאלו תיש הבא על הצביה אף דג\"כ חלבו אסור מ\"מ שוחטין אותו ביו\"ט כמבואר ביו\"ד סימן כ\"ח ס\"ג באחרונים שם:","{צד} אין שוחטין אותו ביו\"ט - שהרי א\"א לכסות דמו עד מוצאי יו\"ט ושמא יתבלע בקרקע ולא יהא רשומו ניכר ויבטל מצות כיסוי:","{צה} עפר מוכן - ואפילו הכינו בהדיא לשם כיסוי כוי [מאירי] ועיין בצל\"ח שדעתו דדוקא בכוי שהוא בריה בפ\"ע אבל בנולד מצבי הבא על התישה אם הכינו בהדיא מעיו\"ט לכיסויו מותר לשחוט אותו ביו\"ט עי\"ש טעמו:","{צו} מפני שהרואה וכו' - ר\"ל כדי שלא יטעו לחשוב כי כוי חיה ודאית היא מדשרו טרחא ביו\"ט ויש כח ביד חכמים לבטל מצוה בשב ואל תעשה כדי שלא יבוא לידי מכשול בספק כרת בקום ועשה:","{צז} ולערב אם רשומו וכו' - ולדידן דעושין שני ימים צריך להמתין בכיסוי עד מוצאי יו\"ט שני:","{צח} אפי' דם בהמה - ומשמע דכ\"ש דם כוי דמותר לכסות כיון דבלאו מצות כיסוי צריך הוא לכסות משום מיאוס ושוב לא יטעו להתיר חלבו דיאמרו מכסה הוא בשביל שלא יתלכלכו כליו ועיין במ\"א שמצדד דאין להקל בזה לכסות רק היכא שמכוין באמת בשביל שלא יתלכלכו כליו אבל אם מכוין רק לשם מצות כיסוי אסור ועיין בה\"ל:","{צט} אם יש לו עפר מוכן - כגון שהכניס מלא קופתו עפר בסתם כבסי\"ז או שהכין לכסות בו צואה מוכן הוא גם לזה:","{ק} דהו\"ל כגרף ש\"ר =של רעי= וצריך לכסות - ר\"ל שדרכו לכסות וכו':","{קא} שחט בהמה וחיה - וה\"ה כוי וחיה:","{קב} ונתערב דמם - והיה דם החיה מרובים עד כדי שאם היה דם בהמה מים היה ניכר אדמומית דם החיה בזה בחול חייב בכיסוי וכמבואר ביו\"ד סימן כ\"ח:","{קג} בדקירה אחת - לאו דוקא והכונה שאין צריך להרבות בטלטול עפר בשביל דמי הבהמה שניתוספו וכדמסיים:","{קד} יכסנו - וה\"ה אם היה לו דקר נעוץ מבע\"י בעפר תיחוח נמי שרי בדקירה אחת דהא לא טרח טפי בשביל הבהמה. ודע עוד דלפי מה שנתבאר לעיל בסט\"ו דבדיעבד אם שחט ואין לו עפר מוכן מותר לכסות אף באפר שאין מוכן ה\"ה בעניננו נמי דינא הכי דמותר דהא לא טרח טפי בשביל הבהמה ולא העתיק המחבר עפר מוכן אלא משום סיפא דאם אינו יכול לכסותו בדקירה אחת אפילו בעפר מוכן לא יכסנו:","{קה} לא יכסנו - דטרח בשביל בהמה והסכימו האחרונים דאפילו דקירה אחת שהיה נוטל בשביל דמי החיה נמי אסור דכיון דמעורב בדם בהמה אם כן אפשר דבמקום שמכסה דם בהמה מרובים כ\"כ עד כדי שדם החיה לא היה ניכר אם דם הבהמה היה מים ופטור אותו מקום מלכסות וא\"כ טרח בשביל דם הבהמה שאינו חייב בכיסוי ואסור. וכתבו האחרונים דאם שחט באמצע החצר מותר לכסות בעפר מוכן אפילו בכמה דקירות כדי שלא יתלכלכו כליו וכדלעיל בהג\"ה:","{קו} שחט צפור וכו' לא יכסנו - ואפילו יש לו עפר מוכן נמי לא שרי ליה למטרח כיון דהיה אפשר לו מעיו\"ט ומימנע משמחת יו\"ט ליכא כאן דאפילו לא מכסה ליה שרי הבשר באכילה. וימתין עד לערב ואם יהיה רשומן ניכר יכסנו ויש לכפות עליו כלי לשמרו כדי שיכסנו:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>בהמה מסוכנת שירא שמא תמות והוא אכל כבר ואין צריך לה אסור לשחטה <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>אלא א\"כ <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"4\"></i>יש <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>שהות ביום <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>כדי <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>לאכול ממנה <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>כזית צלי מבע\"י <small> (ואפי' <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>אין שהות לנתחה ולבדקה תחילה) (טור) </small> וכשיש שהות ביום ושחטה <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>אינו נוטל עורה אא\"כ שייר ממנו אבר אחד ומביאו עמו: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>וי\"א <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>דאין להפשיטה כלל אלא א\"כ שחטה לצורך י\"ט וכן ראוי להורות: (הגהות אלפסי פ' אין צדין)</small>:","m":[]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"6\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>אם שחט בהמה <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>בשדה לא יביאנה במוט או במוטה כדרך שעושה בחול אלא <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>יביאנה בידו איברים איברים:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>עוף שנדרס ברגלים ויש לחוש שנתרסקו איבריו ולכן צריך שהייה מעת לעת ובדיקה אחר שחיט' <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>מותר לשחטו בי\"ט <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>ולא חיישינן שמא ימצא <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"10\"></i>טריפה <i data-commentator=\"Turei Zahav\" data-order=\"8\"></i>אע\"ג דאתיליד ביה ריעותא:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i><i data-commentator=\"Turei Zahav\" data-order=\"9\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"5\"></i>בכור בזמן הזה שאינו יכול לשחטו בלא מום <i data-commentator=\"Magen Avraham\" data-order=\"17\"></i>אין חכם יכול <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"11\"></i>לראותו בי\"ט אם יש בו מום <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>ואפי' אם עבר וראהו ומצא שיש בו מום <i data-commentator=\"Magen Avraham\" data-order=\"18\"></i>אינו יכול לשחטו אבל אם <i data-commentator=\"Magen Avraham\" data-order=\"19\"></i>נולד במומו ועבר וראהו נשחט על פיו <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i>ואם ראה המום מעי\"ט וראה שהוא מום שראוי לישחט עליו יכול לחקור עליו בי\"ט אם נפל בו המום מאיליו ומתירו: <small>הגה ואם נפל בכור בבור אסור להעלותו דהא אינו ראוי לשחטו אלא עושה לו פרנסה במקומו: (רמב\"ם פ\"ב)</small>","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>אותו ואת בנו שנפלו לבור מעלה את הראשון על מנת לשוחטו <i data-commentator=\"Magen Avraham\" data-order=\"20\"></i>ואינו שוחטו וחוזר <i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>ומערים ומעלה את השני רצה זה שוחט רצה זה שוחט:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"20\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"6\"></i>בהמה חציה של עכו\"ם וחצי' של ישראל <i data-commentator=\"Turei Zahav\" data-order=\"10\"></i><i data-commentator=\"Eshel Avraham\" data-label=\"ב\" data-order=\"2\"></i>יכולי' לשחטה בי\"ט ואפילו יש להם שתים יכול לשחוט <i data-commentator=\"Magen Avraham\" data-order=\"21\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"13\"></i>שתיהן:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"21\"></i>השוחט בהמה בי\"ט אינו רשאי <i data-commentator=\"Magen Avraham\" data-order=\"22\"></i>לתלוש הצמר לעשות מקום לסכין אלא מפנהו <i data-commentator=\"Magen Avraham\" data-order=\"23\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"14\"></i><small> (בידו ב\"י) </small> ומושכו אילך ואילך ואם נתלש נתלש:","m":[]},{"s":"השוחט את העוף <i data-commentator=\"Turei Zahav\" data-order=\"11\"></i><i data-commentator=\"Magen Avraham\" data-order=\"24\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"22\"></i>לא ימרוט את הנוצה כדי לעשות מקום לסכין:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"23\"></i><i data-commentator=\"Turei Zahav\" data-order=\"12\"></i>לא ישחוט אדם חיה ועוף בי\"ט אלא אם כן יש לו עפר מוכן <i data-commentator=\"Ba'er Hetev\" data-order=\"15\"></i><i data-commentator=\"Eshel Avraham\" data-label=\"ג\" data-order=\"3\"></i>מבע\"י ואם עבר ושחט אם יש לו דקר <small> (פי' כעין יתד של ברזל שחופרין בו את הקרקע) </small> נעוץ מבעוד יום <i data-commentator=\"Magen Avraham\" data-order=\"25\"></i>בעפר תיחוח מכסהו בו <i data-commentator=\"Magen Avraham\" data-order=\"26\"></i><small> (ואפי' היה צריך <i data-commentator=\"Turei Zahav\" data-order=\"13\"></i>לכמה דקירות שרו) [ב\"י]</small>:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"24\"></i>אפר כירה שהוסק מעי\"ט <i data-commentator=\"Magen Avraham\" data-order=\"27\"></i>מותר לכסות בו אבל <i data-commentator=\"Turei Zahav\" data-order=\"14\"></i>אם הוסק ביום טוב <i data-commentator=\"Magen Avraham\" data-order=\"28\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"16\"></i>אסור אלא א\"כ הוא <i data-commentator=\"Ba'er Hetev\" data-order=\"17\"></i>חם <i data-commentator=\"Turei Zahav\" data-order=\"15\"></i><i data-commentator=\"Magen Avraham\" data-order=\"29\"></i>שראוי לצלות בו ביצה <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"25\"></i><i data-commentator=\"Turei Zahav\" data-order=\"16\"></i>ואם שחט <i data-commentator=\"Magen Avraham\" data-order=\"30\"></i>מותר לכסות בו אע\"פ שאינו ראוי לצלו' בו ביצה <i data-commentator=\"Magen Avraham\" data-order=\"31\"></i><small>ומיהו עדיף טפי לכסות בדקר נעוץ בעפר תיחוח אם יש לו: [ב\"י בשם הרא\"ש וטור]</small>:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"26\"></i><i data-commentator=\"Turei Zahav\" data-order=\"17\"></i>הכניס <i data-commentator=\"Magen Avraham\" data-order=\"32\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"18\"></i>עפר הרבה לביתו לצורך גינתו והוא כנוס במקום אחד מותר לכסות בו שכל זמן שהוא צבור דעתו עליו לכל מה שיצטרך אבל אם הכניס מלא קופה לצורך גינתו לא שמאחר שהוא מועט בטל:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"27\"></i>מכניס אדם מלא קופתו עפר לבית <i data-commentator=\"Magen Avraham\" data-order=\"33\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"19\"></i>בסתם ועושה בו כל צרכו <small> (וע\"ל סי' ש\"ח סעיף ל\"ח) </small> ולא אמרי' שהוא בטל אגב קרקע הבית <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"28\"></i>והוא שייחד לו קרן זוית דכיון שלא שטחו מוכחא מילתא דלצרכיו בעי ליה <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"29\"></i><i data-commentator=\"Turei Zahav\" data-order=\"18\"></i>ואם הוא עפר תיחוח מותר לכסות בו:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"30\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"20\"></i>כוי <small> (פי' בריה שנולדה מתיש וצבי') </small> אין שוחטין אותו <i data-commentator=\"Eshel Avraham\" data-label=\"ד\" data-order=\"4\"></i>בי\"ט ואם שחטו אין מכסין את דמו <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"31\"></i>אפי' יש לו עפר מוכן <i data-commentator=\"Magen Avraham\" data-order=\"34\"></i>מפני שהרואה יאמר ודאי חיה הוא <i data-commentator=\"Turei Zahav\" data-order=\"19\"></i>דאל\"כ לא היו מטריחין לכסות דמו בי\"ט ויבא להתיר חלבו <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"32\"></i>ולערב אם רשומו ניכר יכסנו: <small>הגה ודוקא ששחטו בקרן זויות וכהאי גוונא אבל אם שחטו באמצעית החצר <i data-commentator=\"Magen Avraham\" data-order=\"35\"></i>אפי' דם בהמה יכול לכסות אם יש לו עפר מוכן <i data-commentator=\"Turei Zahav\" data-order=\"20\"></i>דהוה ליה כגרף של רעי וצריך לכסות שלא יתלכלכו כליו בחצר: [הגהות אלפסי פרק קמא דביצה]</small>:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"33\"></i><i data-commentator=\"Turei Zahav\" data-order=\"21\"></i>שחט בהמה וחי' <i data-commentator=\"Magen Avraham\" data-order=\"36\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"21\"></i>ונתערב דמם ויש לו עפר מוכן או אפר כירה אם יכול לכסותו בדקירה אחת שאינו צריך להרבות בשביל דם הבהמה <i data-commentator=\"Magen Avraham\" data-order=\"37\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"22\"></i>יכסנו ואם לאו <i data-commentator=\"Magen Avraham\" data-order=\"38\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"23\"></i>לא יכסנו:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"34\"></i>שחט צפור מערב י\"ט ולא כיסה דמו <i data-commentator=\"Magen Avraham\" data-order=\"39\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"24\"></i>לא יכסנו בי\"ט:","m":[]}],"499":[{"s":"<b>דיני מליגה ומליחה ביום טוב. ובו ה סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>אין מרגילין בי\"ט כיצד הוא מרגיל זה המוציא <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>כל הבשר <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>מרגל אחד כדי שיוציא כל העור שלם ולא יקרע מפני שטורח בהפשט זה טורח גדול ואין בו צורך למועד:","m":["{א} מרגל אחד וכו' - טורח גדול. משמע מלשון זה דאם מפשיט העור דרך שתי הרגלים [דהיינו שחותך מרגל האחד עד השני בין שני רגלים האחרונים ועי\"ז מפשיט העור שלם] דשרי דלאו טרחא רבה היא כ\"כ ויש מחמירין בכל גווני שלא להפשיט העור שלם דעכ\"פ הוא טרחא יתירא שלא לצורך יו\"ט:","{ב} למלוג גדי - דהיינו ליתנו ברותחין לאחר המליחה כדי להעביר השער:","{ג} אא\"כ מולגו לאכול העור - דמתוך שעורו רך יש שאוכלין אותו ביחד עם הבשר והוי לצורך אוכל נפש וכמו שמותר למלוג הראש והרגלים [וכדלקמן בסימן ת\"ק ס\"ד] והרבה פוסקים חולקין בזה דלא התירו למלוג רק הראש והרגלים דנהיגי בכך אבל מליגת כל הגוף אינו אלא למפונקים ביותר ואינו צורך כל נפש וגם נראה יותר כמעשה חול ונכון להחמיר לכתחלה. כתבו הפוסקים דבעוף דלא שייך הפשט לכו\"ע מותר למלוג ולהבהב כל הגוף:","{ד} להגביה עורה - ר\"ל לטלטלה ולהניחה במקום משומר או מחמה לצל כדי שלא תפסד ואע\"ג דבעלמא עור לח אסור לטלטלו וכדלעיל בסימן ש\"ח סכ\"ה הכא הקילו דאי לא שרית ליה לא ישחוט ואתי לאימנועי משמחת יו\"ט:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אסור למלוג גדי <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אא\"כ מולגו <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>לאכול העור:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>בהמה שנשחטה בי\"ט <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>מותר <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>להגביה עורה וליתנה במקום דריסת הרגלים אע\"פ שאין עליו בשר כלל <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ומותר למלוח עליו מליחה קלה כדרך שמולחים <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>לצלי <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ומותר להערים ולמלוח כאן מעט וכאן מעט עד שימלח את כולו <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>אבל אם נשחטה <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>מערב י'ט אסור: <small>הגה ונוצות של עוף דינן כמו בעור דמותר לטלטלן <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>כדי <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>להצניען כמו בעור</small>:","m":["{ה} וליתנה במקום וכו' - ר\"ל וכן הקילו שמותר ליתנה במקום דריסת הרגלים שע\"י הדריסה מתעבד העור קצת וכיון דלא מוכחא מילתא להדיא שעושה משום כן דאפשר שטחה כדי שישבו עליה (שעיקר ישיבתם באותו הזמן היה בדרך זו שוטחין עור או בגדים ע\"ג קרקע ויושבין עליהן) הו\"ל התיקון כלאחר יד ולא רצו לאסור עליו דא\"כ מימנע ולא שחיט משום הפסד העור ואתי לאימנועי משמחת יו\"ט. ומיהו דוקא ליתנה במקום הדורסין אבל לשוטחה ע\"ג יתדות כדי שתתייבש אסור משום דמוכחא מלתא דלצורך העור קעביד ואם נתיר לו שיטוח לצורכה אתי למימלחה ג\"כ:","{ו} כלל - דאי יש עליה כזית בשר בלא\"ה מותר לטלטלה משום הבשר:","{ז} למלוח עליו - ר\"ל שימלח בשר על הטור דעי\"ז ממילא ימלח גם העור קצת:","{ח} כדרך שמולחים לצלי - ר\"ל שרוצה לצלות אותה דבזה א\"צ מליחה מרובה ולאפוקי אם ימלחנה מליחה מרובה אסור דעי\"ז יהיה עיבוד יפה גם לעור:","{ט} כאן מעט וכו' - ר\"ל כאן בשר מעט וכאן בשר מעט:","{י} אבל אם נשחטה מעיו\"ט וכו' - לא מיבעיא אם גם הופשטה קודם יו\"ט בודאי דאסור ביו\"ט להגביה אותה וליתנה במקום הדורסין ולמלוח עליה שהרי אפשר היה לעשות כל אלה מעיו\"ט אלא אפילו הופשטה ביו\"ט אסור דמשום זה לא ימנע מלשחוט דהא יכול להפשיטו מעיו\"ט אם לא שלא היה לו שהות להפשיט מעיו\"ט אז יש להקל. כתבו הפוסקים דאפילו שכח למלחו מעיו\"ט אסור למלחו ביו\"ט דאין לחלק בין מזיד לשוכח. בגליות שעושין שני ימים טובים מספק הרי יו\"ט א' נחשב לחול לגבי יו\"ט שני לפיכך אם נשחטה ביו\"ט ראשון אפשר דדינה כאלו נשחטה בעיו\"ט לענין טלטול העור ומליחתו כשיגיע יו\"ט שני:","{יא} ונוצות של עוף - היינו שנשחטה ביו\"ט דאי נשחטה מעיו\"ט אע\"ג דהוסרו הנוצות ביו\"ט אסור לטלטלן כדלעיל גבי עור:","{יב} כדי להצניען - אבל בלא\"ה אסור לטלטלן דלא חזו למידי. והפר\"ח מחמיר בכ\"ג והאחרונים מסכימים לפסק שו\"ע ומיהו פלעדערו\"ש מאווז שנשחטה לכו\"ע שרי לטלטולי דראוי להשתמש בה:","{יג} אין מולחין וכו' - דדבר שאינו אוכל גמור אם מולח כדי שלא יסריח יש בו משום מעבד:","{יד} ולא מהפכין בהם - הוא ג\"כ כעין תקון להחלבים ואסור מטעם הנ\"ל:","{טו} אפילו לשוטחן וכו' - דמוכחא מילתא שעושה זה כדי שלא יסריחו וגזרינן דלמא אתי ג\"כ למולחם. ולענין טלטול דעת הט\"ז בשם הג\"א להקל והמ\"א העלה דלפי מאי דפסק הרמ\"א בסימן תצ\"ה דנולד אסור גם החלבים אסור לטלטלן כשנשחטה ביו\"ט דהוי נולד ואע\"ג דחזו להדלקה מאתמול לא היה עומד להדלקה ורק לטלטלן כדי להצניען או כדי שלא יסריחו מותר דשרינן סופן משום תחלתן וכנ\"ל גבי נוצות אבל כשנשחטה מעיו\"ט מותר לטלטל החלבים דחזו להדלקה וה\"ה חתיכת שעוה מותר לטלטל דיכול להניח פתילה ע\"ג וחזי להדלקה. עוד כתב מ\"א דעור שהופשט מעיו\"ט אם הוא לח אסור לטלטלו ואם הוא יבש מותר לטלטלו כמ\"ש סימן ש\"ח סכ\"ה [וע\"ש דהרמ\"א הביא דעת החולקין ע\"ז] אבל כשנשחט ביו\"ט הו\"ל נולד וע\"כ אם הוא לח מותר לטלטלו כדי שלא יסריח וכנ\"ל [ואם הוא מונח גם עתה במקום צל ויודע שלא יתקלקל אסור לטלטלו] ואם יבש אסור לטלטלו דהו\"ל נולד:","{טז} אסור למלוח וכו' - כדי שיפול מן המלח על החלבים והטעם דחלבים מליחה מועטת סגי להו ואסור משום חששא דעיבוד וכנ\"ל:","{יז} באויר - דעל החלבים ממש אי אפשר להניח בשר שבולע מן החלבים:","{יח} לכתוש בו הריפות - דאסור ביו\"ט וכדלקמן סימן תק\"ד ס\"ג:","{יט} מותר לטלטלו - כדין כל כלי שמלאכתו לאיסור לעיל בסימן ש\"ח סעיף ג' שמותר לטלטלו לצורך גופו (דהיינו לעשות בו מלאכה המותרת) או לצורך מקומו ודעת מג\"א דאפילו היה העלי מוקצה מחמת חסרון כיס כגון שמקפיד על העלי מלהשתמש בו בדבר אחר שלא יתקלקל דבכגון זה אסור בכל מקום הכא שרי משום שמחת יו\"ט ועיין ביאור הלכה:","{כ} מחמה לצל - או כדי שלא יגנב וכדלעיל בסימן ש\"ח:","{כא} אבל לצורך וכו' - כדין כל כלי שמלאכתו לאיסור. וסדן העב שקוצבין עליו בשר מותר לטלטלו לאחר שקצב אפילו מחמה לצל וכה\"ג דהא הוא כלי שמלאכתו להיתר:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i><i data-commentator=\"Turei Zahav\" data-order=\"4\"></i><i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>אין מולחין את החלבים ולא מהפכים בהם <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>אפי' <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>לשטחן על גבי יתדות אע\"פ <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>שנשחט' <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>ביום טוב וכן <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i>אסור למלוח בשר <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>עליהם באויר:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>עלי שהוא דף עב וכבד וכלי היא אלא <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>שמלאכתו <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>לאיסור <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>לכתוש בו הריפות מותר לטלטלו לקצב עליו בשר <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>ולאחר שקצב עליו אסור לטלטלו <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>מחמה לצל: <small>[אבל לצורך גופו <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>ומקומו שרי]</small>:","m":[]}],"500":[{"s":"<b>הנצרך לבשר ביום טוב היאך יתנהג וסדר מליחתו. ובו ו סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אין קונין בשר בפיסוק דמים לומר לטבח תן לי בסלע או בשתים וכן לא יאמר לו הריני שותף עמך בסלע אלא <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>מחלק להם שלישיות או רביעיות כפי החלקים שדרך לחלק בעיר בלא פיסוק דמים ומביא שתי בהמות ויאמר <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>זו כזו ולמחר שמין הנשאר כפי ששוה כך יפרע לו: <small>הגה וי\"א <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>דדוקא ישראל לגבי ישראל שרי בכהאי גונא אבל ישראל <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>עם <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>עכו\"ם אפי' בכהאי גונא אסור: [הגהות אשירי פרק אין צדין]</small>:","m":["{א} אין קונים בשר וכו' - אפילו ליקח בהקפה משום גזירת מקח וממכר:","{ב} הריני שותף וכו' - ר\"ל אע\"פ שאינו קונה ממנו אלא משתתף עמו בגוף הבהמה אפ\"ה אסור כיון שמזכיר שם דמים:","{ג} אלא מחלק וכו' - עיין בה\"ל:","{ד} להם - דוקא בלא גורל כגון שהם מוותרים זה לזה ואין מקפידין אם יקח חבירו מנה יפה אבל אם מקפידין וצריכין גורל אסור ועיין סוף סי' שכ\"ב ואפילו גורל ע\"י סכין כמו שעושין הקצבים [דהיינו שמניחין סכין בין שני החלקים ושואלים להקונים איזה צד רוצה אם החלק שמונח לצד החד או לצד הגב] גם זה מקרי גורל ואסור [אור זרוע הלכות יו\"ט]:","{ה} ומביא וכו' - ר\"ל וכדי שידעו אח\"כ כמה צריך לפרוע שהרי יש בהמה שחלק ממנה שוה דינר ויש בהמה שנתח ממנה שוה שני דינרים לזה אמרו חכמים שקודם ששוחט לבהמה מביא בהמה אחרת ששויה כזו לעין הרואה ולמחר שמין דמיה וכן ישלמו. ונראה דאם הקונים סומכין על הטבח בדבר המקח שיאמר להם למחר א\"צ להביא בהמה אחרת אח\"כ מצאתי שכ\"כ בא\"ר בשם תניא וז\"ל וה\"ה שיוכל לילך לטבח ישראל או כותי ולומר לו תן לי רגל או חצי וכיו\"ב בלא זכירת מקח וממכר ופיסוק דמים ולמחר פורע לו המעות כמו שיוכל וכעין זה משמע בטור סימן תקי\"ז:","{ו} זו כזו - ומ\"מ אסור לפרש ולומר מה שאתה נוטל למחר בעד זו ניתן לך בעד זו דהוי סכום מקח:","{ז} אפילו בכה\"ג אסור - היינו אפילו בלא פיסוק דמים שאומר לעכו\"ם הריני עמך בבהמה זו למחצה וכו' והטעם משום דאין ישראל רגיל להשתתף עם העכו\"ם מחזי טפי כמקח וממכר ולא הקילו בזה ויש חולקין בזה דלא מפלגינן בין ישראל לעכו\"ם וכל שאינו מזכיר דמים מותר ויש להחמיר כסברא ראשונה. בד\"א בדבר שאין שיעור מקחו ידוע כמו בשר אבל דבר שמקחו ידוע כמו ביצים ואגוזים וכה\"ג מותר ליקח חלק אצל נכרי אם אינו מזכיר לו סכום דמים. וכתב הלבוש דאסור לו לישראל למכור לעכו\"ם ביו\"ט אפילו בלי פיסוק דמים [אם לא דאיכא פסידא כגון בשר טריפה וכדלעיל בסוף סימן תצ\"ז ע\"ש] דלא התירו זה אלא כשישראל קונה ומשום שמחת יו\"ט:","{ח} אסור לשקול - ואפילו אינו שוקל במשקל הרגיל אלא שמניח בכף כלי או סכין ודעתו למחר לשקלו אפ\"ה אסור דעובדא דחול הוא כתבו האחרונים דאפילו אינו מדקדק במשקל כ\"כ רק פוחת מעט או מוסיף ג\"כ אסור דמ\"מ נראה כשוקל:","{ט} ואפי' ליתנו וכו' - ר\"ל ובכף השני מונח משקלות:","{י} שרגילין לשקול בה - דאז נראה כשוקל ועיין בבה\"ל כתבו האחרונים דלא קאי רק אנותנו לשמור מן העכברים הא במקום ששוקל להדיא אפילו אינה תלויה במקומה אסור:","{יא} ואפילו לשקול מנה וכו' - מנה הוא חלק ור\"ל כשיש להם בשר לחלק ומניחין חלק אחד בכף אחת והשני בכף שכנגד להשוותם:","{יב} שלוקח וכו' ומשער - דוקא בזה שהוא השערה בעלמא אבל אם לוקח משקל ביד אחת וביד השני בשר לשער נגד המשקל אסור:","{יג} אפילו זה אסור - מפני שהוא רגיל בזה יודע הוא לכוין המשקל בצמצום וכשוקל במאזנים דמי וכתבו האחרונים דלא מחמרינן בזה אלא בשעה שמוכר אבל לעצמו בביתו לית לן בה. אסור לשקול הבשר במים דהיינו כלי שיש בו שנתות [דהיינו חריצים] ונותן בו מים ומניח בו הבשר וכשהמים מגיעין עד השנתות יודע כמה ליטרא יש בבשר ג\"ז אסור ואפילו פיחת מעט או הוסיף מעט שניכר שמכוין למשקל [גמרא]:","{יד} חותך כדרכו - כתב המ\"א דמותר לומר לטבח תן לי ליטרא בשר דאינו מכוין למשקל אלא להודיע לו כמה הוא צריך וכמו שכתב הרמ\"א לעיל סימן שכ\"ג ס\"ד וע\"ש במ\"ב סק\"כ ובה\"ל:","{טו} לתלותו בו - מלשון זה משמע דאפילו בעה\"ב לעצמו אין לו לעשות נקב בבשר השחוט כדי שיוכל לתלותו על הכותל שלא יעשה כדרך שהוא עושה בחול אבל יש מפרשים דאין הדברים אמורים אלא בקצב המוכר בשר שדרכו בחול לעשות נקב בסכין בהבשר כדי שיוכל הלוקח לאחוז שם בידו להוליכו לביתו וביו\"ט צריך לשנות לעשות הנקב ביד כדי שיהיה היכר שאין מקח וממכר מותר בו ולעשות נקב בחתיכת האפיקומן בפסח לתלותו נראה דלכו\"ע מותר אפילו בסכין ומ\"מ לעשות בו נקב עיגול או משולש כמגן דוד יש להחמיר [פמ\"ג]:","{טז} לעשות בו סימן - שלא יחליפנו אדם:","{יז} מותר אפילו בסכין - איתא בגמרא דרבה בר ר\"ה =רב הונא= מחתך אתלת קרנתא [כשהיה משלח הבשר לביתו היה רגיל לעשות כל חתיכה בעלת שלש קרנות ובביתו היו יודעין שזה היה סימן שלו תמיד] אבל אותיות [וציורים] אסור לעשותן בבשר דרך סימן ביו\"ט:","{יח} מולגין וכו' - ברותחין אחר המליחה כדי להשיר השיער וכן מהבהבין וכו' דהוי מלאכה לצורך אוכל נפש ופשוט דלדעת היש מחמירין לעיל בסימן תצ\"ה דאף באו\"נ גופא אם אפשר לו לעשות מעיו\"ט אסור ביו\"ט מיירי כאן בשלא היה לו פנאי למולגו מעיו\"ט [דידוע שאינו מתקלקל אם היה מולגו מעיו\"ט] או דמיירי ששחטו ביו\"ט גופא:","{יט} באור - וה\"ה דמותר להטמין אותו ברמץ:","{כ} בסיד וכו' - כדי להסיר השער:","{כא} בבת אחת - במפולת יד אחת כגון שיש כאן שלש חתיכות יניחם זו אצל זו ויקח מלח מלא חפניו כדי שיעור מליחה של כל החתיכות וזורה עליהם בבת אחת:","{כב} אע\"פ שאינו צריך - ליו\"ט אלא אחת והטעם שטורח אחד הוא טורח לכל הבשר שהרי מולחן ביחד ואע\"פ שהוא מוסיף קצת טרחא שהרי צריך להפך כל חתיכה וחתיכה בפ\"ע כדי למולחם בצד השני מ\"מ כיון דמן התורה אין עיבוד באוכלין כמו שכתבנו לעיל בסימן שכ\"א הקילו חכמים למלוח בבת אחת אם חושש שמא יסריח הבשר:","{כג} וי\"א דלא שרי להערים וכו' - הלשון מגומגם דלא נזכר הערמה כלל בדברי המחבר וכתבו הרבה מפרשים שחסר כאן בדברי המחבר וכצ\"ל ומותר להערים ולמלוח חתיכה ואח\"כ ליטול אחרת ולומר בזה אני רוצה ור\"ל דאפילו כשאינו מולח בבת אחת יש תקנה דהיינו ע\"י הערמה שיאמר בזו האחרת אני רוצה עכשיו והתירו לו דבר זה כדי שלא ימנע מלשחוט אם ידע שלא יתירו לו למלוח כל הבשר ואתי למסרח [ויש שכתבו דאפילו נשחט מעיו\"ט נמי מותר למלוח כולן ביו\"ט ע\"י הערמה] וע\"ז הגיה רמ\"א וי\"א דלא שרי להערים וכו':","{כד} רק קודם אכילת וכו' - דבאמת צריך לאכול אז איזה חתיכה אבל אם כבר אכל ואין בדעתו לאכול עוד יותר היום אסור להערים ולמלוח אע\"פ שיבשל ויטעום מעט כיון שאינו טועם רק כדי להתיר לו מליחת שאר החתיכות וכעין שנתבאר לקמן בסימן תק\"ג ס\"א ע\"ש. ואפי' אם ירצה למלוח כל החתיכות ביחד נמי אסור בכגון זה דלא שייך בזה לומר טרחא אחת לכולם שהרי גם לאחת א\"צ באמת. והסכימו האחרונים דכ\"ז בשאינו ידוע לו בודאי שיסריח אם לא ימלחנו אבל בידוע לו בודאי מותר למולחו אפילו אחר אכילה ואפילו בזה אחר זה ע\"י שיערים על כל חתיכה לומר מזו אוכל היום וצריך שיאכל כזית מאחת מהן ואפילו זה לא התירו אלא כששחט ביו\"ט כדי שלא ימנע על להבא מלשחוט אבל כששחטה מעיו\"ט כיון שהיה יכול למלחה מעיו\"ט אסור למלוח בשר שא\"צ לו ביו\"ט אא\"כ מולחו קודם אכילה:","{כה} ומותר למלוח וכו' - ר\"ל כשמולחו להכשירו להוציא דמו [ומטעם דאם היה מולחו מעיו\"ט היה צריך אחר הדחה שניה למולחו עוד פעם שני ולהשהותו במלח עד למחר [דאל\"כ היה מתקלקל] ודבר ידוע הוא כשהבשר שוהה הרבה במלח מפיג טעם לפיכך מותר למלוח הבשר שרוצה לאכלו בו ביום ואגבן מותר למלוח שארי הבשר כיון שהוא בבת אחת או ע\"י הערמה וכנ\"ל] אבל אם כבר נמלח והודח משום דם אסור למולחו פעם שנית ביו\"ט כדי שלא יפסיד ואפילו בשחרית קודם אכילה שהרי אין דרך למלוח בשר בשעת בישולו ואדרבה מדיחין אותו ממלחו בשעת בישולו ואם כן מוכחא מלתא שמולח רק לתקן הבשר ולכן אסור. אמנם בליל יו\"ט ב' מותר לחזור ולמלחו ע\"י שיערים על כל חתיכה לומר מזו אוכל למחר וכן יעשה שיאכל מהן מעט למחר:","{כו} אע\"פ שהיה וכו' - ומ\"מ דגים שהם משובחין כשמונחין במלח אסור למולחן ביו\"ט כשהיה יכול למלחן מעיו\"ט [ואין בכלל זה מה שנותנין מלח לתוך המחבת שמבשלין אותן בה דאין איסור במליחה אלא משום גזרת עיבוד או משום דטורח שלא לצורך יו\"ט משא\"כ בזה שנותן לתוך התבשיל] ומיני דגים הרכים המתקלקלים כשינוחו זמן רב במלח מותר למלחן ביו\"ט אפילו אם קרען בעיו\"ט ודינן כמליחת בשר לכל דבר:","{כז} אפילו נשחט מעיו\"ט - וכנ\"ל לענין מליחה וכ\"ז כשמנקר הבשר שדעתו לאכלה ביו\"ט אבל שאר בשר אסור לנקרו ואפילו נשחט ביו\"ט שהרי טורח הוא לצורך חול אא\"כ רוצה למלחו מפני שחושש שמא יסריח הבשר ולמלחו אסור קודם ניקור כמ\"ש ביו\"ד סימן ס\"ה בזה מותר לו לנקר גם שאר בשר ע\"י הערמה דהיינו לאחר שניקר חתיכה אחת לצורך היום אומר חתיכה זו אינה טובה בעיני כ\"כ רק חתיכה אחרת ומנקרה וכן כולם. ודוקא כשנשחט ביו\"ט אבל אם נשחטה בעיו\"ט והיה לו פנאי לנקרה מבע\"י אסור לו לנקר ביו\"ט רק הבשר שצריך לו לאכילה ביו\"ט שהרי הניקור אינו מפיג טעם הבשר כלל והיה לו לנקר קודם יו\"ט:","{כח} וטוב לשנות קצת - דהיינו שינקרנו בקופיץ או בקרדום ואע\"ג דלעיל גבי מליחה אף שהיה יכול למלחו מעיו\"ט א\"צ שינוי התם משום דבשר ששוהה הרבה במליחה מפיג טעם משא\"כ הכא ע\"י הניקור אינו מפיג טעם כלל והיה לו לנקרו מעיו\"ט:","{כט} אם יוכל לשנות - ואם א\"א לו לשנות מותר אפילו בלי שינוי ואע\"ג דהיה יכול לעשות מעיו\"ט משום דבניקור ליכא שום לתא דמלאכה אלא משום טרחא בעלמא וחלק אחוריים דא\"א לנקר היטב ע\"י שינוי יש להחמיר שלא לנקרו אם נשחט מעיו\"ט והיה שהות לנקרו מעיו\"ט ובמקום דחק יש להקל לצורך יו\"ט. בשר מנוקר שהוא ביום ג' לשחיטתו ואם ישהה אחר יו\"ט יהיה אסור לאכלו כ\"א צלי כמבואר ביו\"ד סי' מותר להדיחו ביו\"ט הואיל וראוי לאכילה ואף דטרחא זו לצורך חול הוא אינו עושה מעשה רק ששופך עליו מים [ומ\"מ ראוי לכתחלה שיאכלו הקצבים חתיכה ממנה ואם אפשר להניח ההדחה עד יו\"ט ב' לא ידיחו ביו\"ט ראשון] אבל בשבת דא\"א לבשל ולאכול אסור [מ\"א] ועיין לעיל בסימן שכ\"א במ\"ב סקכ\"א מה שכתבנו בשם האחרונים דע\"י עכו\"ם בודאי יש להקל להדיח ואם א\"א ע\"י עכו\"ם מותר גם ע\"י ישראל. עוד כתב המ\"א דאם אירע זה בבשר שאינו מנוקר גם ביו\"ט אסור להדיחו משום דכיון דאסור לנקר מה שאינו לצורך יו\"ט ע\"י הערמה שיאמר אוכל ממנו כזית כיון דהיה יכול לנקרה מבע\"י וכנ\"ל ממילא לא חזי לאכילה וע\"כ דינו כמו בשבת דאסור להדיחו והנה לפי מה שהקילו האחרונים גם בשבת במקום הדחק מטעם דכיון דחזי לטלטול ממילא מותר להדיחו ג\"כ גם בבשר שאינו מנוקר אין להחמיר מטעם זה כמו שביארתי בבה\"ל. ומ\"מ אם אפשר ע\"י עכו\"ם טוב יותר ע\"י עכו\"ם או כשמונח הבשר בכלי טוב שירחוץ ידיו עליו עד שיהיה הבשר שרוי במים:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>אסור לשקול בשר אפי' <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>בביתו <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>לידע כמה יבשלו <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ואפי' ליתנו בכף מאזנים לשמרו מן העכברים אסור <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אם הוא תלוי במקום שרגילים לשקול בה <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ואפי' לשקול מנה כנגד מנה אסור <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ומותר לשקול <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>בידו שלוקח החתיכה בידו ומשער כמה יש בה <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>וטבח <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>אומן אפי' זה אסור <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>אבל אם הוא יודע לכוין דרך חתיכתו לחתך ליטר' או חצי ליטר' <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"6\"></i>חותך כדרכו ואינו חושש:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i><i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>אין <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>נוקבין נקב בבשר בסכין לתלותו בו אבל ביד מותר <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>ואם <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>לעשות בו <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>סימן מותר אפי' בסכין:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>מולגין הראש והרגלים ומהבהבין אותם <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>באור אבל אין טופלין אותם בסיד ולא בחרסית ולא באדמה דמתחזי כעיבוד ואין גוזזין אותם במספרים שנראה כעוש' לצורך השיער:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i><i data-commentator=\"Magen Avraham\" data-order=\"10\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>מותר למלוח <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>כמה חתיכות בבת אחת אף על פי שאינו צריך אלא אחת: <small>הגה וי\"א דלא שרי להערים רק קודם אכילת שחרית ומותר למלוח הבשר בי\"ט <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>אע\"פ שהיה אפשר למלחו <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>מעי\"ט (מהרי\"ל ות\"ה סי' פ')</small>:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i><i data-commentator=\"Turei Zahav\" data-order=\"4\"></i><i data-commentator=\"Magen Avraham\" data-order=\"12\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i>נוהגין לנקר בשר בי\"ט אפי' נשחט מעי\"ט: <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i><small>[וטוב <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"10\"></i>לשנות קצת אם יוכל לשנות באיזה דבר] (מהרי\"ל ות\"ה סי' פ\"ד)</small>:","m":[]}]};